```cpp
#include <cassert>
#include <cstddef>
#include <cstdint>
#include <fuzzer/FuzzedDataProvider.h>
#include <span>
#include <vector>

struct TlvRecord {
    uint8_t tag;
    std::vector<uint8_t> value;
    bool operator==(const TlvRecord&) const = default;
};

bool parse_tlv_stream(std::span<const uint8_t> buf, std::vector<TlvRecord>& out);
std::vector<uint8_t> encode_tlv_stream(std::span<const TlvRecord> records);

extern "C" int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size) {
    FuzzedDataProvider fdp(data, size);

    if (fdp.ConsumeBool()) {
        std::vector<uint8_t> raw = fdp.ConsumeRemainingBytes<uint8_t>();
        std::vector<TlvRecord> decoded;
        if (parse_tlv_stream(raw, decoded)) {
            std::vector<uint8_t> reencoded = encode_tlv_stream(decoded);
            std::vector<TlvRecord> roundtrip;
            assert(parse_tlv_stream(reencoded, roundtrip));
            assert(decoded == roundtrip);
        }
    } else {
        size_t count = fdp.ConsumeIntegralInRange<size_t>(0, 32);
        std::vector<TlvRecord> records;
        records.reserve(count);
        for (size_t i = 0; i < count && fdp.remaining_bytes() > 0; ++i) {
            uint8_t tag = fdp.ConsumeIntegral<uint8_t>();
            size_t len = fdp.ConsumeIntegralInRange<size_t>(0, 1024);
            std::vector<uint8_t> val = fdp.ConsumeBytes<uint8_t>(len);
            records.push_back(TlvRecord{tag, std::move(val)});
        }
        std::vector<uint8_t> wire = encode_tlv_stream(records);
        std::vector<TlvRecord> parsed;
        assert(parse_tlv_stream(wire, parsed));
        assert(parsed == records);
    }
    return 0;
}
```

