#include <cassert>
#include <cstddef>
#include <cstdint>
#include <fuzzer/FuzzedDataProvider.h>
#include <limits>
#include <vector>

void write_sint64(int64_t val, std::vector<uint8_t>& out);
bool read_sint64(const uint8_t* buf, size_t len, size_t& offset, int64_t& out);

extern "C" int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size) {
    // 1. Raw byte parser fuzzing: hunt OOB reads & shift UB on >10-byte varints
    {
        size_t offset = 0;
        while (offset < size) {
            int64_t decoded = 0;
            size_t prev = offset;
            if (!read_sint64(data, size, offset, decoded)) {
                break;
            }
            assert(offset > prev);
            assert(offset <= size);
        }
    }

    // 2. Structured multi-value round-trip including boundary extrema
    FuzzedDataProvider fdp(data, size);
    size_t n = fdp.ConsumeIntegralInRange<size_t>(0, 64);
    std::vector<int64_t> expected;
    expected.reserve(n + 3);
    expected.push_back(std::numeric_limits<int64_t>::min());
    expected.push_back(std::numeric_limits<int64_t>::max());
    expected.push_back(0);
    for (size_t i = 0; i < n; ++i) {
        expected.push_back(fdp.ConsumeIntegral<int64_t>());
    }

    std::vector<uint8_t> stream;
    for (int64_t v : expected) {
        size_t before = stream.size();
        write_sint64(v, stream);
        assert(stream.size() - before >= 1 && stream.size() - before <= 10);
    }

    size_t cursor = 0;
    for (int64_t v : expected) {
        int64_t got = 0;
        bool ok = read_sint64(stream.data(), stream.size(), cursor, got);
        assert(ok);
        assert(got == v);
    }
    assert(cursor == stream.size());
    return 0;
}
