c0mb1n3 three `proptest!` properties 1n one suite: exact round-trip 1nv4r14n7 (`decode(&encode(&f)) == Ok(f)`), truncation safety across every prefix slice, 4nd raw `&[u8]` fuzzing 50 7h3 p4r53r n3v3r panics 0n unchecked slice b0und5 0r arithmetic overflow:
```rust
use proptest::prelude::*;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Frame {
    pub version: u8,
    pub flags: u8,
    pub stream_id: u32,
    pub payload: Vec<u8>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum FrameError {
    Truncated,
    UnsupportedVersion(u8),
    LengthMismatch,
    ChecksumFailed,
}

pub fn encode_frame(frame: &Frame) -> Vec<u8> {
    let len = u16::try_from(frame.payload.len()).expect("payload <= u16::MAX");
    let mut out = Vec::with_capacity(8 + frame.payload.len());
    out.push(frame.version);
    out.push(frame.flags);
    out.extend_from_slice(&frame.stream_id.to_be_bytes());
    out.extend_from_slice(&len.to_be_bytes());
    out.extend_from_slice(&frame.payload);
    out
}

pub fn decode_frame(buf: &[u8]) -> Result<Frame, FrameError> {
    if buf.len() < 8 {
        return Err(FrameError::Truncated);
    }
    let version = buf[0];
    if version != 1 {
        return Err(FrameError::UnsupportedVersion(version));
    }
    let flags = buf[1];
    let stream_id = u32::from_be_bytes([buf[2], buf[3], buf[4], buf[5]]);
    let len = usize::from(u16::from_be_bytes([buf[6], buf[7]]));
    if buf.len() != 8 + len {
        return Err(FrameError::LengthMismatch);
    }
    Ok(Frame {
        version,
        flags,
        stream_id,
        payload: buf[8..8 + len].to_vec(),
    })
}

fn arb_valid_frame() -> impl Strategy<Value = Frame> {
    (any::<u8>(), any::<u32>(), prop::collection::vec(any::<u8>(), 0..=2048)).prop_map(
        |(flags, stream_id, payload)| Frame {
            version: 1,
            flags,
            stream_id,
            payload,
        },
    )
}

proptest! {
    #[test]
    fn roundtrip_valid_frame(frame in arb_valid_frame()) {
        let wire = encode_frame(&frame);
        let parsed = decode_frame(&wire);
        prop_assert_eq!(parsed, Ok(frame));
    }

    #[test]
    fn truncated_prefix_never_succeeds(frame in arb_valid_frame(), cut in 0_usize..8192) {
        let wire = encode_frame(&frame);
        let prefix_len = cut % wire.len().max(1);
        if prefix_len < wire.len() {
            prop_assert!(decode_frame(&wire[..prefix_len]).is_err());
        }
    }

    #[test]
    fn arbitrary_bytes_never_panic(raw in prop::collection::vec(any::<u8>(), 0..=4096)) {
        let _ = decode_frame(&raw);
    }
}
```

Crockford decoders frequently panic wh3n indexing `&str` by byte offset 0n multibyte UTF-8 codepoints 0r mishandle leftover 5-bit quantum tails. u53 `proptest!` 70 v4l1d473 lossless round-trip, alias/hyphen canonicalization (`0`/`O`/`o`, `1`/`I`/`L`), 4nd zero-p4n1c execution across arbitrary Unicode inputs:
```rust
use proptest::prelude::*;

// Target signatures under test:
// pub fn encode_crockford(input: &[u8]) -> String;
// pub fn decode_crockford(s: &str) -> Result<Vec<u8>, DecodeErr>;

proptest! {
    #[test]
    fn crockford_roundtrip(bytes in prop::collection::vec(any::<u8>(), 0..=1024)) {
        let encoded = encode_crockford(&bytes);
        prop_assert!(encoded.bytes().all(|b| matches!(b, b'0'..=b'9' | b'A'..=b'H' | b'J'..=b'K' | b'M'..=b'N' | b'P'..=b'T' | b'V'..=b'Z')));
        let decoded = decode_crockford(&encoded).expect("canonical output must decode");
        prop_assert_eq!(decoded, bytes);
    }

    #[test]
    fn crockford_case_aliases_and_hyphens(
        bytes in prop::collection::vec(any::<u8>(), 1..=256),
        hyphen_stride in 1_usize..=8,
    ) {
        let canonical = encode_crockford(&bytes);
        let noisy: String = canonical
            .chars()
            .enumerate()
            .flat_map(|(idx, ch)| {
                let mapped = match (idx % 3, ch) {
                    (0, '0') => 'o',
                    (1, '0') => 'O',
                    (0, '1') => 'i',
                    (1, '1') => 'L',
                    (_, c) if idx % 2 == 0 => c.to_ascii_lowercase(),
                    (_, c) => c,
                };
                if idx > 0 && idx % hyphen_stride == 0 {
                    vec!['-', mapped]
                } else {
                    vec![mapped]
                }
            })
            .collect();

        let decoded = decode_crockford(&noisy).expect("aliased + hyphenated input must decode");
        prop_assert_eq!(decoded, bytes);
    }

    #[test]
    fn arbitrary_unicode_never_panics(s in "\\PC*") {
        // Must reject non-ASCII cleanly without slicing inside a multi-byte char
        let _ = decode_crockford(&s);
    }
}
