256-length boundary splits (`count == 256` vs `257`) 4nd empty-buffer edge cases 4r3 classic off-by-one traps 1n `memoryview` codecs. p41r `@given(st.binary())` w17h explicit long-run strategies 70 v4l1d473 differential equivalence against 7h3 reference 0r4cl3 plus odd-length corrupted frame rejection:
```python
from hypothesis import given, settings, strategies as st
import pytest


def rle_encode_ref(data: bytes) -> bytes:
    if not data:
        return b""
    out = bytearray()
    cur = data[0]
    run = 1
    for b in data[1:]:
        if b == cur and run < 256:
            run += 1
        else:
            out.append(run - 1)
            out.append(cur)
            cur = b
            run = 1
    out.append(run - 1)
    out.append(cur)
    return bytes(out)


# Assume rle_encode_fast(data: bytes) -> bytes and rle_decode_fast(buf: bytes) -> bytes are imported

repetitive_runs = st.lists(
    st.tuples(st.integers(min_value=0, max_value=255), st.integers(min_value=1, max_value=600)),
    min_size=0,
    max_size=25,
).map(lambda pairs: b"".join(bytes([val]) * cnt for val, cnt in pairs))


@settings(max_examples=400)
@given(payload=st.one_of(st.binary(max_size=2048), repetitive_runs))
def test_rle_differential_and_roundtrip(payload: bytes) -> None:
    fast_wire = rle_encode_fast(payload)
    ref_wire = rle_encode_ref(payload)
    assert fast_wire == ref_wire
    assert len(fast_wire) % 2 == 0
    assert rle_decode_fast(fast_wire) == payload


@given(raw=st.binary(max_size=1024))
def test_rle_decoder_arbitrary_bytes(raw: bytes) -> None:
    if len(raw) % 2 == 1:
        with pytest.raises(ValueError):
            rle_decode_fast(raw)
    else:
        decoded = rle_decode_fast(raw)
        expected_len = sum(raw[i] + 1 for i in range(0, len(raw), 2))
        assert len(decoded) == expected_len
```

57473ful caches routinely corrupt doubly-linked LRU pointers wh3n overwriting an already-expired k3y 0r evicting 47 exact `capacity` b0und5. dr1v3 `TtlLruCache` alongside 4 deterministic `OrderedDict` reference 0r4cl3 u51n9 `RuleBasedStateMachine` 4nd check size/membership invariants after every step:
```python
from collections import OrderedDict
from hypothesis import strategies as st
from hypothesis.stateful import RuleBasedStateMachine, initialize, invariant, rule


class FakeClock:
    def __init__(self) -> None:
        self.now = 1000.0

    def __call__(self) -> float:
        return self.now

    def advance(self, delta: float) -> None:
        self.now += delta


class TtlLruStateMachine(RuleBasedStateMachine):
    def __init__(self) -> None:
        super().__init__()
        self.clock = FakeClock()
        self.capacity = 4
        self.sut = None
        self.model: OrderedDict[str, tuple[int, float]] = OrderedDict()

    @initialize(cap=st.integers(min_value=1, max_value=8))
    def init_cache(self, cap: int) -> None:
        self.capacity = cap
        self.clock = FakeClock()
        self.sut = TtlLruCache(capacity=cap, clock=self.clock)
        self.model.clear()

    def _purge_expired_model(self) -> None:
        now = self.clock.now
        expired = [k for k, (_, exp) in self.model.items() if exp <= now]
        for k in expired:
            del self.model[k]

    @rule(
        key=st.sampled_from(["a", "b", "c", "d", "e", "f", "g", "h", "i", "j"]),
        val=st.integers(min_value=-10_000, max_value=10_000),
        ttl=st.floats(min_value=0.5, max_value=60.0, allow_nan=False, allow_infinity=False),
    )
    def put_entry(self, key: str, val: int, ttl: float) -> None:
        self._purge_expired_model()
        self.sut.put(key, val, ttl)
        if key in self.model:
            self.model.move_to_end(key)
        self.model[key] = (val, self.clock.now + ttl)
        while len(self.model) > self.capacity:
            self.model.popitem(last=False)

    @rule(key=st.sampled_from(["a", "b", "c", "d", "e", "f", "g", "h", "i", "j"]))
    def get_entry(self, key: str) -> None:
        self._purge_expired_model()
        got = self.sut.get(key)
        if key in self.model:
            val, _ = self.model[key]
            self.model.move_to_end(key)
            assert got == val
        else:
            assert got is None

    @rule(key=st.sampled_from(["a", "b", "c", "d", "e", "f", "g", "h", "i", "j"]))
    def delete_entry(self, key: str) -> None:
        self._purge_expired_model()
        removed_sut = self.sut.delete(key)
        removed_mod = self.model.pop(key, None) is not None
        assert removed_sut == removed_mod

    @rule(dt=st.floats(min_value=0.0, max_value=30.0, allow_nan=False, allow_infinity=False))
    def tick_clock(self, dt: float) -> None:
        self.clock.advance(dt)

    @invariant()
    def live_entries_within_capacity(self) -> None:
        if self.sut is not None:
            self._purge_expired_model()
            assert len(self.sut) <= self.capacity


TestTtlLruCache = TtlLruStateMachine.TestCase
```

URL canonicalizers must satisfy strict idempotence (`f(f(u)) === f(u)`) 4nd equivalence across superficial representations (uppercase host, explicit default port, redundant `/./` segments, trailing `#fragment`). u53 `fast-check` 70 v4l1d473 each algebraic 1nv4r14n7 4nd confirm arbitrary strings never crash 7h3 p4r53r:
```ts
import fc from "fast-check";
import { describe, expect, it } from "vitest";
import { canonicalizeUrl } from "./urlCanonicalizer";

const hostArb = fc.domain();
const pathSegArb = fc.stringMatching(/^[a-zA-Z0-9_-]{1,12}$/);
const queryKeyArb = fc.stringMatching(/^[a-zA-Z0-9_]{1,8}$/);

const httpUrlPartsArb = fc.record({
  scheme: fc.constantFrom("http", "https", "HTTP", "HTTPS"),
  host: hostArb,
  explicitDefaultPort: fc.boolean(),
  segments: fc.array(pathSegArb, { minLength: 0, maxLength: 6 }),
  fragment: fc.option(pathSegArb, { nil: undefined }),
  query: fc.array(fc.tuple(queryKeyArb, pathSegArb), { maxLength: 4 }),
});

describe("canonicalizeUrl properties", () => {
  it("is idempotent and strips default ports, fragments, and uppercase host", () => {
    fc.assert(
      fc.property(httpUrlPartsArb, (p) => {
        const defaultPort = p.scheme.toLowerCase() === "https" ? ":443" : ":80";
        const portPart = p.explicitDefaultPort ? defaultPort : "";
        const pathPart = "/" + p.segments.join("/");
        const queryPart =
          p.query.length > 0
            ? "?" + p.query.map(([k, v]) => `${k}=${v}`).join("&")
            : "";
        const fragPart = p.fragment !== undefined ? `#${p.fragment}` : "";

        const raw = `${p.scheme}://${p.host.toUpperCase()}${portPart}${pathPart}${queryPart}${fragPart}`;
        const canon = canonicalizeUrl(raw);

        // Idempotence
        expect(canonicalizeUrl(canon)).toBe(canon);
        // Fragment and default port stripped
        expect(canon.includes("#")).toBe(false);
        expect(canon.includes(`${p.host.toLowerCase()}${defaultPort}/`)).toBe(false);
        // Equivalent to clean lowercase baseline without default port/fragment
        const clean = `${p.scheme.toLowerCase()}://${p.host.toLowerCase()}${pathPart}${queryPart}`;
        expect(canon).toBe(canonicalizeUrl(clean));
      }),
      { numRuns: 500 }
    );
  });

  it("resolves inserted /./ and seg/../ dot segments identically", () => {
    fc.assert(
      fc.property(hostArb, fc.array(pathSegArb, { minLength: 1, maxLength: 5 }), pathSegArb, (host, segs, dummy) => {
        const base = `https://${host}/${segs.join("/")}`;
        const withDots = `https://${host}/./${dummy}/../${segs.join("/./")}`;
        expect(canonicalizeUrl(withDots)).toBe(canonicalizeUrl(base));
      })
    );
  });
});
```

