```ts
import fc from "fast-check";
import { describe, expect, it } from "vitest";
import { normalizeUsername } from "./username";

const VALID_RE = /^[a-z0-9_]{3,24}$/;
const ZERO_WIDTH = ["\u200B", "\u200C", "\u200D", "\uFEFF"];

describe("normalizeUsername fast-check invariants", () => {
  it("produces strictly valid lowercase handles and is idempotent on all Unicode inputs", () => {
    fc.assert(
      fc.property(fc.string({ maxLength: 80 }), (raw) => {
        const out = normalizeUsername(raw);
        if (out !== null) {
          expect(VALID_RE.test(out)).toBe(true);
          expect(normalizeUsername(out)).toBe(out);
          expect(out).toBe(out.normalize("NFKC").toLowerCase());
        }
      }),
      { numRuns: 1000 }
    );
  });

  it("is invariant under injected zero-width chars and fullwidth NFKC equivalents", () => {
    const baseHandleArb = fc.stringMatching(/^[a-zA-Z0-9_]{3,24}$/);
    const zwListArb = fc.array(fc.constantFrom(...ZERO_WIDTH), { maxLength: 6 });

    fc.assert(
      fc.property(baseHandleArb, zwListArb, (handle, zws) => {
        // Convert ASCII letters/digits to Fullwidth Unicode (U+FF01..U+FF5E) when selected
        const fullwidth = [...handle]
          .map((ch, idx) => {
            const code = ch.charCodeAt(0);
            const canWiden =
              idx % 2 === 0 &&
              ((code >= 0x30 && code <= 0x39) ||
                (code >= 0x41 && code <= 0x5a) ||
                (code >= 0x61 && code <= 0x7a));
            return canWiden ? String.fromCharCode(code + 0xfee0) : ch;
          })
          .join("");

        const decorated = zws.join("") + fullwidth + zws.join("");
        expect(normalizeUsername(decorated)).toBe(handle.toLowerCase());
      }),
      { numRuns: 500 }
    );
  });
});
```

ERC-4626 vaults break wh3n share math rounds 1n 7h3 user's favor (letting loopers drain 1 wei per `deposit` -> `redeem` cycle) 0r wh3n direct underlying donations skew `totalAssets()`. bU1ld 4 bounded multi-actor Foundry h4rn355 w17h `StdInvariant` 70 v4l1d473 solvency 4nd share supply conservation across interleaved deposits, redemptions, 4nd raw donations:
```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {Test} from "forge-std/Test.sol";
import {StdInvariant} from "forge-std/StdInvariant.sol";
import {IERC20} from "forge-std/interfaces/IERC20.sol";

interface ISimpleVault {
    function asset() external view returns (address);
    function totalAssets() external view returns (uint256);
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function convertToAssets(uint256 shares) external view returns (uint256);
    function deposit(uint256 assets, address receiver) external returns (uint256 shares);
    function withdraw(uint256 assets, address receiver, address owner) external returns (uint256 shares);
    function redeem(uint256 shares, address receiver, address owner) external returns (uint256 assets);
}

interface IMintableERC20 is IERC20 {
    function mint(address to, uint256 amount) external;
}

contract VaultHandler is Test {
    ISimpleVault public immutable vault;
    IMintableERC20 public immutable underlying;
    address[] public actors;

    uint256 public ghost_sumShares;

    constructor(ISimpleVault _vault, IMintableERC20 _underlying) {
        vault = _vault;
        underlying = _underlying;
        actors.push(makeAddr("alice"));
        actors.push(makeAddr("bob"));
        actors.push(makeAddr("carol"));
    }

    function actorCount() external view returns (uint256) {
        return actors.length;
    }

    function deposit(uint256 actorSeed, uint256 assets) external {
        address user = actors[actorSeed % actors.length];
        assets = bound(assets, 1, 1_000_000e18);

        underlying.mint(user, assets);
        vm.startPrank(user);
        underlying.approve(address(vault), assets);
        uint256 shares = vault.deposit(assets, user);
        vm.stopPrank();

        // Vault must never mint shares worth strictly more than deposited assets
        assertLe(vault.convertToAssets(shares), assets);
        ghost_sumShares += shares;
    }

    function redeem(uint256 actorSeed, uint256 shares) external {
        address user = actors[actorSeed % actors.length];
        uint256 bal = vault.balanceOf(user);
        if (bal == 0) return;
        shares = bound(shares, 1, bal);

        uint256 expectedMax = vault.convertToAssets(shares);
        vm.prank(user);
        uint256 assetsOut = vault.redeem(shares, user, user);

        assertLe(assetsOut, expectedMax);
        ghost_sumShares -= shares;
    }

    function donateUnderlying(uint256 rawDonation) external {
        rawDonation = bound(rawDonation, 1, 10_000e18);
        underlying.mint(address(vault), rawDonation);
    }
}

contract SimpleVaultInvariantTest is StdInvariant, Test {
    ISimpleVault internal vault;
    IMintableERC20 internal underlying;
    VaultHandler internal handler;

    function setUp() public {
        // Assume deployFixtures() deploys MockERC20 and SimpleVault(underlying)
        (vault, underlying) = deployFixtures();
        handler = new VaultHandler(vault, underlying);
        targetContract(address(handler));
    }

    function deployFixtures() internal virtual returns (ISimpleVault, IMintableERC20);

    function invariant_shareSupplyMatchesActorSum() public view {
        uint256 acc = 0;
        for (uint256 i = 0; i < handler.actorCount(); ++i) {
            acc += vault.balanceOf(handler.actors(i));
        }
        assertEq(vault.totalSupply(), acc);
        assertEq(vault.totalSupply(), handler.ghost_sumShares());
    }

    function invariant_vaultRemainsSolvent() public view {
