```cpp
#include <algorithm>
#include <cassert>
#include <cstddef>
#include <cstdint>
#include <deque>
#include <fuzzer/FuzzedDataProvider.h>
#include <vector>

class BoundedRingBuffer {
public:
    explicit BoundedRingBuffer(size_t capacity);
    size_t write(const uint8_t* src, size_t len);
    size_t read(uint8_t* dst, size_t len);
    size_t peek(uint8_t* dst, size_t len) const;
    void clear();
    size_t size() const;
    size_t capacity() const;
    size_t free_space() const;
};

extern "C" int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size) {
    FuzzedDataProvider fdp(data, size);
    const size_t cap = fdp.ConsumeIntegralInRange<size_t>(1, 256);
    BoundedRingBuffer sut(cap);
    std::deque<uint8_t> model;

    uint32_t steps = fdp.ConsumeIntegralInRange<uint32_t>(1, 128);
    for (uint32_t i = 0; i < steps && fdp.remaining_bytes() > 0; ++i) {
        uint8_t op = fdp.ConsumeIntegralInRange<uint8_t>(0, 3);
        if (op == 0) {
            std::vector<uint8_t> chunk = fdp.ConsumeBytes<uint8_t>(
                fdp.ConsumeIntegralInRange<size_t>(0, cap * 2)
            );
            size_t written = sut.write(chunk.data(), chunk.size());
            size_t expected = std::min(chunk.size(), cap - model.size());
            assert(written == expected);
            model.insert(model.end(), chunk.begin(), chunk.begin() + expected);
        } else if (op == 1) {
            size_t req = fdp.ConsumeIntegralInRange<size_t>(0, cap * 2);
            std::vector<uint8_t> out(req, 0xAA);
            size_t got = sut.read(out.data(), req);
            size_t expected = std::min(req, model.size());
            assert(got == expected);
            for (size_t k = 0; k < got; ++k) {
                assert(out[k] == model.front());
                model.pop_front();
            }
        } else if (op == 2) {
            size_t req = fdp.ConsumeIntegralInRange<size_t>(0, cap + 8);
            std::vector<uint8_t> out(req, 0x55);
            size_t got = sut.peek(out.data(), req);
            size_t expected = std::min(req, model.size());
            assert(got == expected);
            for (size_t k = 0; k < got; ++k) {
                assert(out[k] == model[k]);
            }
        } else {
            sut.clear();
            model.clear();
        }
        assert(sut.size() == model.size());
        assert(sut.free_space() == cap - model.size());
    }
    return 0;
}
