const idArb = fc.stringMatching(/^[a-z0-9.:/-]{3,24}$/);

describe("validateJwtClaims boundary properties", () => {
  it("enforces exact exp and nbf boundaries under clock skew leewaySec", () => {
    fc.assert(
      fc.property(epochArb, fc.integer({ min: 10, max: 3600 }), leewayArb, idArb, idArb, (nbf, ttl, leewaySec, iss, aud) => {
