import fc from "fast-check";
import { describe, expect, it } from "vitest";
import { GcraLimiter } from "./gcraLimiter";

describe("GcraLimiter invariants", () => {
  it("grants exactly burstCount + 1 simultaneous requests from cold start, then honours retryAfterMs", () => {
    fc.assert(
      fc.property(
        fc.integer({ min: 10, max: 5_000 }),
        fc.integer({ min: 0, max: 20 }),
        fc.integer({ min: 1_000_000, max: 9_000_000 }),
        (emissionMs, extraBurst, t0) => {
