          const limiter = new GcraLimiter(emissionMs, burstToleranceMs);

          for (let i = 0; i < extraBurst + 1; i++) {
            const res = limiter.check("client-a", t0);
            expect(res.allowed).toBe(true);
            expect(res.retryAfterMs).toBe(0);
