#include <cctype>
#include <cstddef>
#include <cstdint>
#include <fuzzer/FuzzedDataProvider.h>
#include <map>
#include <optional>
#include <string>
#include <string_view>

struct IniDocument {
    std::map<std::string, std::map<std::string, std::string>> sections;
    static std::optional<IniDocument> parse(std::string_view text);
    std::string serialize() const;
    bool operator==(const IniDocument&) const = default;
};

static std::string clean_token(std::string s) {
    s.erase(std::remove_if(s.begin(), s.end(), [](unsigned char c) {
        return !std::isalnum(c) && c != '_' && c != '-';
    }), s.end());
    return s.empty() ? "k" : s;
}

extern "C" int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size) {
    FuzzedDataProvider fdp(data, size);

    if (fdp.ConsumeBool()) {
        std::string raw = fdp.ConsumeRemainingBytesAsString();
        if (auto parsed = IniDocument::parse(raw)) {
            std::string dumped = parsed->serialize();
            auto reparsed = IniDocument::parse(dumped);
            assert(reparsed.has_value());
            assert(*reparsed == *parsed);
        }
    } else {
        IniDocument doc;
        size_t sec_cnt = fdp.ConsumeIntegralInRange<size_t>(1, 8);
        for (size_t i = 0; i < sec_cnt && fdp.remaining_bytes() > 0; ++i) {
            std::string sec = clean_token(fdp.ConsumeRandomLengthString(16));
            size_t kv_cnt = fdp.ConsumeIntegralInRange<size_t>(1, 8);
            for (size_t j = 0; j < kv_cnt && fdp.remaining_bytes() > 0; ++j) {
                std::string k = clean_token(fdp.ConsumeRandomLengthString(16));
                std::string v = clean_token(fdp.ConsumeRandomLengthString(32));
                doc.sections[sec][k] = v;
            }
        }
        std::string text = doc.serialize();
        auto back = IniDocument::parse(text);
        assert(back.has_value());
        assert(*back == doc);
    }
    return 0;
}
