```rust
use proptest::prelude::*;

// Target API:
// pub struct BitWriter { ... } -> write_bits(&mut self, val: u64, width: u8), finish(self) -> Vec<u8>
// pub struct BitReader<'a> { ... } -> new(&'a [u8]), read_bits(&mut self, width: u8) -> Option<u64>

fn arb_bit_entry() -> impl Strategy<Value = (u8, u64)> {
    (1_u8..=64_u8, any::<u64>()).prop_map(|(width, raw)| {
        let mask = if width == 64 {
            u64::MAX
        } else {
            (1_u64 << width) - 1
        };
        (width, raw & mask)
    })
}

proptest! {
    #[test]
    fn bitstream_arbitrary_widths_roundtrip(
        entries in prop::collection::vec(arb_bit_entry(), 0..=128)
    ) {
        let mut writer = BitWriter::new();
        let mut total_bits: usize = 0;
        for &(width, val) in &entries {
            writer.write_bits(val, width);
            total_bits += usize::from(width);
        }

        let buf = writer.finish();
        prop_assert_eq!(buf.len(), total_bits.div_ceil(8));

        let mut reader = BitReader::new(&buf);
        for &(width, expected) in &entries {
            let got = reader.read_bits(width);
            prop_assert_eq!(got, Some(expected));
        }

        // Requesting more than 7 trailing pad bits must return None
        prop_assert_eq!(reader.read_bits(8), None);
    }

    #[test]
    fn arbitrary_bytes_and_widths_never_panic(
        raw in prop::collection::vec(any::<u8>(), 0..=64),
        widths in prop::collection::vec(1_u8..=64_u8, 0..=64),
    ) {
        let mut reader = BitReader::new(&raw);
        for w in widths {
            let _ = reader.read_bits(w);
        }
    }
}
