// Target API:
// pub fn seal_envelope(key: &[u8; 32], nonce: &[u8; 12], aad: &[u8], pt: &[u8]) -> Vec<u8>;
// pub fn open_envelope(key: &[u8; 32], aad: &[u8], frame: &[u8]) -> Result<Vec<u8>, CryptoError>;

proptest! {
    #[test]
    fn aead_envelope_roundtrip_and_bitflip_rejection(
        key in any::<[u8; 32]>(),
        nonce in any::<[u8; 12]>(),
        aad in prop::collection::vec(any::<u8>(), 0..=128),
        pt in prop::collection::vec(any::<u8>(), 0..=512),
