```python
from hypothesis import strategies as st
from hypothesis.stateful import RuleBasedStateMachine, invariant, precondition, rule

KEYS = ["k0", "k1", "k2", "k3", "k4", "k5"]


class TxKvStateMachine(RuleBasedStateMachine):
    def __init__(self) -> None:
        super().__init__()
        self.sut = TxKvStore()
        self.snapshots: list[dict[str, int]] = [{}]

    @rule(key=st.sampled_from(KEYS), val=st.integers(min_value=-1000, max_value=1000))
    def put_key(self, key: str, val: int) -> None:
        self.sut.set(key, val)
        self.snapshots[-1][key] = val

    @rule(key=st.sampled_from(KEYS))
    def delete_key(self, key: str) -> None:
        existed_sut = self.sut.delete(key)
        existed_mod = key in self.snapshots[-1]
        self.snapshots[-1].pop(key, None)
        assert existed_sut == existed_mod

    @rule()
    def begin_tx(self) -> None:
        self.sut.begin()
        self.snapshots.append(dict(self.snapshots[-1]))

    @precondition(lambda self: len(self.snapshots) > 1)
    @rule()
    def commit_tx(self) -> None:
        self.sut.commit()
        top = self.snapshots.pop()
        self.snapshots[-1] = top

    @precondition(lambda self: len(self.snapshots) > 1)
    @rule()
    def rollback_tx(self) -> None:
        self.sut.rollback()
        self.snapshots.pop()

    @invariant()
    def all_keys_match_active_snapshot(self) -> None:
        active = self.snapshots[-1]
        for k in KEYS:
            assert self.sut.get(k) == active.get(k)


TestTxKvStore = TxKvStateMachine.TestCase
