// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {Test} from "forge-std/Test.sol";
import {StdInvariant} from "forge-std/StdInvariant.sol";

interface ILinearDutchAuction {
    function seller() external view returns (address);
    function floorPrice() external view returns (uint256);
    function settled() external view returns (bool);
    function clearingPrice() external view returns (uint256);
    function sellerWithdrawn() external view returns (bool);
    function currentPrice() external view returns (uint256);
    function buy() external payable;
    function withdrawSellerProceeds() external;
}

contract DutchAuctionHandler is Test {
    ILinearDutchAuction public immutable auction;
    uint256 public ghost_lastObservedPrice;
    uint256 public ghost_netEthPaid;
    uint256 public ghost_sellerProceedsPulled;

    constructor(ILinearDutchAuction _auction) {
        auction = _auction;
        ghost_lastObservedPrice = _auction.currentPrice();
    }

    function warpTime(uint256 delta) external {
        delta = bound(delta, 1, 7 days);
        vm.warp(block.timestamp + delta);
        uint256 p = auction.currentPrice();
        assertLe(p, ghost_lastObservedPrice);
        assertGe(p, auction.floorPrice());
        ghost_lastObservedPrice = p;
    }

    function attemptBuy(uint256 buyerSeed, uint256 extraWei) external {
        if (auction.settled()) return;
        address buyer = vm.addr((buyerSeed % 5) + 1);
        uint256 price = auction.currentPrice();
        extraWei = bound(extraWei, 0, 10 ether);
        uint256 payment = price + extraWei;

        vm.deal(buyer, payment);
        vm.prank(buyer);
        auction.buy{value: payment}();

        // Buyer must receive exact refund of extraWei
        assertEq(buyer.balance, extraWei);
        ghost_netEthPaid += price;
    }

    function pullSellerProceeds() external {
        if (!auction.settled() || auction.sellerWithdrawn()) return;
        address seller = auction.seller();
        uint256 pre = seller.balance;
        vm.prank(seller);
        auction.withdrawSellerProceeds();
        ghost_sellerProceedsPulled += seller.balance - pre;
    }
}

contract DutchAuctionInvariantTest is StdInvariant, Test {
