        auction = deployAuction();
        handler = new DutchAuctionHandler(auction);
        targetContract(address(handler));
    }

    function deployAuction() internal virtual returns (ILinearDutchAuction);

    function invariant_ethConservationAndPriceFloor() public view {
        assertGe(auction.currentPrice(), auction.floorPrice());
        assertEq(
