// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {Test} from "forge-std/Test.sol";
import {StdInvariant} from "forge-std/StdInvariant.sol";

interface ISimpleMultisig {
    function threshold() external view returns (uint256);
    function txCount() external view returns (uint256);
    function getTx(uint256 txId) external view returns (address to, uint256 value, bool executed, uint256 confirmations);
    function isConfirmed(uint256 txId, address owner) external view returns (bool);
    function submitTx(address to, uint256 value) external returns (uint256 txId);
    function confirmTx(uint256 txId) external;
    function revokeConfirmation(uint256 txId) external;
    function executeTx(uint256 txId) external;
}

contract MultisigHandler is Test {
    ISimpleMultisig public immutable wallet;
    address[] public owners;
    address public immutable sink;

    uint256 public ghost_funded;
    uint256 public ghost_executedValue;
    mapping(uint256 => uint256) public ghost_execCount;

    constructor(ISimpleMultisig _wallet, address[] memory _owners) {
        wallet = _wallet;
        owners = _owners;
        sink = makeAddr("sink");
    }

    function ownerCount() external view returns (uint256) {
        return owners.length;
    }

    function fundWallet(uint256 amount) external {
        amount = bound(amount, 1, 50 ether);
        vm.deal(address(this), amount);
        (bool ok, ) = address(wallet).call{value: amount}("");
        if (ok) ghost_funded += amount;
    }

    function submit(uint256 ownerSeed, uint256 val) external {
        address o = owners[ownerSeed % owners.length];
        val = bound(val, 0, 10 ether);
        vm.prank(o);
        wallet.submitTx(sink, val);
    }

    function confirm(uint256 ownerSeed, uint256 txSeed) external {
        uint256 n = wallet.txCount();
        if (n == 0) return;
        address o = owners[ownerSeed % owners.length];
        uint256 txId = txSeed % n;
        (, , bool executed, ) = wallet.getTx(txId);
        if (executed || wallet.isConfirmed(txId, o)) return;
        vm.prank(o);
        wallet.confirmTx(txId);
    }

    function revoke(uint256 ownerSeed, uint256 txSeed) external {
        uint256 n = wallet.txCount();
        if (n == 0) return;
        address o = owners[ownerSeed % owners.length];
        uint256 txId = txSeed % n;
        (, , bool executed, ) = wallet.getTx(txId);
        if (executed || !wallet.isConfirmed(txId, o)) return;
        vm.prank(o);
        wallet.revokeConfirmation(txId);
    }

    function execute(uint256 ownerSeed, uint256 txSeed) external {
        uint256 n = wallet.txCount();
        if (n == 0) return;
        uint256 txId = txSeed % n;
        (, uint256 val, bool executed, uint256 confs) = wallet.getTx(txId);
        if (executed || confs < wallet.threshold() || address(wallet).balance < val) return;

        address o = owners[ownerSeed % owners.length];
        vm.prank(o);
        wallet.executeTx(txId);
        ghost_execCount[txId] += 1;
        ghost_executedValue += val;
    }
}

contract MultisigInvariantTest is StdInvariant, Test {
    ISimpleMultisig internal wallet;
    MultisigHandler internal handler;

    function setUp() public {
        address[] memory owners = new address[](3);
        owners[0] = makeAddr("o1");
        owners[1] = makeAddr("o2");
        owners[2] = makeAddr("o3");
        wallet = deployMultisig(owners, 2);
        handler = new MultisigHandler(wallet, owners);
        targetContract(address(handler));
    }

    function deployMultisig(address[] memory owners, uint256 threshold) internal virtual returns (ISimpleMultisig);

    function invariant_quorumAndTreasuryBalance() public view {
        assertEq(address(wallet).balance + handler.ghost_executedValue(), handler.ghost_funded());
        uint256 n = wallet.txCount();
        for (uint256 id = 0; id < n; ++id) {
            (, , bool executed, uint256 confs) = wallet.getTx(id);
            uint256 actualVotes = 0;
            for (uint256 k = 0; k < handler.ownerCount(); ++k) {
                if (wallet.isConfirmed(id, handler.owners(k))) actualVotes++;
            }
            assertEq(confs, actualVotes);
            if (executed) {
                assertGe(confs, wallet.threshold());
                assertEq(handler.ghost_execCount(id), 1);
            }
        }
    }
}
