from hypothesis import strategies as st
from hypothesis.stateful import RuleBasedStateMachine, invariant, rule


class RoomCalendarMachine(RuleBasedStateMachine):
    def __init__(self) -> None:
        super().__init__()
        self.cal = RoomCalendar()
        self.slot_owner: dict[int, int] = {}
        self.active_ids: dict[int, tuple[int, int]] = {}

    @rule(
        a=st.integers(min_value=0, max_value=96),
        b=st.integers(min_value=0, max_value=96),
    )
    def try_book(self, a: int, b: int) -> None:
        start, end = min(a, b), max(a, b)
        if start == end:
            return
        free_expected = all(t not in self.slot_owner for t in range(start, end))
        assert self.cal.is_available(start, end) == free_expected

