        else:
            assert bid is None

    @rule(idx=st.integers(min_value=0, max_value=50))
    def cancel_booking(self, idx: int) -> None:
        if not self.active_ids:
            assert self.cal.cancel(idx) is False
            return
        keys = sorted(self.active_ids)
        bid = keys[idx % len(keys)] if idx % 3 != 0 else -999
        ok = self.cal.cancel(bid)
