// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {Test} from "forge-std/Test.sol";
import {StdInvariant} from "forge-std/StdInvariant.sol";

interface ITimelockQueue {
    function MIN_DELAY() external view returns (uint256);
    function GRACE_PERIOD() external view returns (uint256);
    function queuedEta(bytes32 txId) external view returns (uint256);
    function queueTx(address target, uint256 value, bytes calldata data, uint256 eta) external returns (bytes32);
    function cancelTx(bytes32 txId) external;
    function executeTx(address target, uint256 value, bytes calldata data, uint256 eta) external;
}

contract CounterTarget {
    uint256 public hits;
    function ping(uint256 nonce) external {
        if (nonce >= 0) hits += 1;
    }
}

contract TimelockHandler is Test {
    ITimelockQueue public immutable timelock;
    CounterTarget public immutable target;
    address public immutable admin;

    struct Proposal {
        uint256 nonce;
        uint256 eta;
        bytes32 txId;
        bool cancelled;
        uint256 execCount;
        uint256 executedAt;
    }

    Proposal[] public proposals;

    constructor(ITimelockQueue _timelock, CounterTarget _target, address _admin) {
        timelock = _timelock;
        target = _target;
        admin = _admin;
    }

    function proposalCount() external view returns (uint256) {
        return proposals.length;
    }

    function queue(uint256 extraDelay) external {
        extraDelay = bound(extraDelay, 0, 10 days);
        uint256 nonce = proposals.length + 1;
        uint256 eta = block.timestamp + timelock.MIN_DELAY() + extraDelay;
        bytes memory callData = abi.encodeCall(CounterTarget.ping, (nonce));

        vm.prank(admin);
        bytes32 id = timelock.queueTx(address(target), 0, callData, eta);
        proposals.push(Proposal(nonce, eta, id, false, 0, 0));
    }

    function cancel(uint256 idxSeed) external {
        if (proposals.length == 0) return;
        Proposal storage p = proposals[idxSeed % proposals.length];
        if (timelock.queuedEta(p.txId) == 0) return;

        vm.prank(admin);
        timelock.cancelTx(p.txId);
        p.cancelled = true;
    }

    function execute(uint256 idxSeed) external {
        if (proposals.length == 0) return;
        Proposal storage p = proposals[idxSeed % proposals.length];
        if (timelock.queuedEta(p.txId) == 0) return;
        if (block.timestamp < p.eta || block.timestamp > p.eta + timelock.GRACE_PERIOD()) return;

        bytes memory callData = abi.encodeCall(CounterTarget.ping, (p.nonce));
        vm.prank(admin);
        timelock.executeTx(address(target), 0, callData, p.eta);
        p.execCount += 1;
        p.executedAt = block.timestamp;
    }

    function warp(uint256 secs) external {
        secs = bound(secs, 1, 7 days);
        vm.warp(block.timestamp + secs);
    }
}

contract TimelockInvariantTest is StdInvariant, Test {
    ITimelockQueue internal timelock;
    CounterTarget internal target;
    TimelockHandler internal handler;

    function setUp() public {
        address admin = makeAddr("admin");
        timelock = deployTimelock(admin);
        target = new CounterTarget();
        handler = new TimelockHandler(timelock, target, admin);
        targetContract(address(handler));
    }

    function deployTimelock(address admin) internal virtual returns (ITimelockQueue);

    function invariant_executionWindowAndSingleFire() public view {
        uint256 totalExecs = 0;
        uint256 n = handler.proposalCount();
        for (uint256 i = 0; i < n; ++i) {
            (, uint256 eta, bytes32 id, bool cancelled, uint256 execCount, uint256 executedAt) = handler.proposals(i);
