use proptest::prelude::*;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum QueryErr {
    EmbeddedNul,
    InvalidPercentEscape,
    InvalidUtf8,
}

fn hex_val(b: u8) -> Option<u8> {
    match b {
        b'0'..=b'9' => Some(b - b'0'),
        b'a'..=b'f' => Some(b - b'a' + 10),
        b'A'..=b'F' => Some(b - b'A' + 10),
        _ => None,
    }
}

fn decode_component_strict(raw: &[u8]) -> Result<String, QueryErr> {
    let mut out = Vec::with_capacity(raw.len());
    let mut i = 0;
    while i < raw.len() {
        match raw[i] {
            0 => return Err(QueryErr::EmbeddedNul),
            b'+' => {
                out.push(b' ');
                i += 1;
            }
            b'%' => {
                if i + 2 >= raw.len() {
                    return Err(QueryErr::InvalidPercentEscape);
                }
                let hi = hex_val(raw[i + 1]).ok_or(QueryErr::InvalidPercentEscape)?;
                let lo = hex_val(raw[i + 2]).ok_or(QueryErr::InvalidPercentEscape)?;
                let byte = (hi << 4) | lo;
                if byte == 0 {
                    return Err(QueryErr::EmbeddedNul);
                }
                out.push(byte);
                i += 3;
            }
            b => {
                out.push(b);
                i += 1;
            }
        }
    }
    String::from_utf8(out).map_err(|_| QueryErr::InvalidUtf8)
}

pub fn parse_query_strict(qs: &str) -> Result<Vec<(String, String)>, QueryErr> {
    if qs.is_empty() {
        return Ok(Vec::new());
    }
    let mut pairs = Vec::new();
    for part in qs.as_bytes().split(|&b| b == b'&') {
        if part.is_empty() {
            continue;
        }
        let (k, v) = match part.iter().position(|&b| b == b'=') {
            Some(pos) => (&part[..pos], &part[pos + 1..]),
            None => (part, &[][..]),
        };
        pairs.push((decode_component_strict(k)?, decode_component_strict(v)?));
    }
    Ok(pairs)
}

