use proptest::prelude::*;
use std::collections::BTreeSet;

const WINDOW_SIZE: u64 = 128;

// Reference specification for 128-packet sliding anti-replay window (rejecting seq == 0 if 1-indexed, or tracking seen)
struct SpecWindow {
    highest: Option<u64>,
    seen: BTreeSet<u64>,
}

impl SpecWindow {
    fn new() -> Self {
        Self { highest: None, seen: BTreeSet::new() }
    }

    fn check_and_accept(&mut self, seq: u64) -> bool {
        if let Some(hi) = self.highest {
            if seq > hi {
                self.highest = Some(seq);
                self.seen.insert(seq);
                return true;
            }
            // Too old if strictly older than hi.saturating_sub(WINDOW_SIZE - 1)
            if hi - seq >= WINDOW_SIZE {
                return false;
            }
            self.seen.insert(seq)
        } else {
            self.highest = Some(seq);
            self.seen.insert(seq);
            true
        }
    }
}

fn arb_packet_stream() -> impl Strategy<Value = Vec<u64>> {
    prop::collection::vec(
        prop_oneof![
            0_u64..300_u64,
            Just(0_u64),
            Just(127_u64),
            Just(128_u64),
            Just(256_u64),
            (u64::MAX - 300)..=u64::MAX,
        ],
        1..=150,
    )
}

proptest! {
    #[test]
    fn replay_window_matches_reference_set(stream in arb_packet_stream()) {
        let mut sut = ReplayWindow::new();
        let mut spec = SpecWindow::new();

        for seq in stream {
            let got = sut.check_and_accept(seq);
            let want = spec.check_and_accept(seq);
            prop_assert_eq!(got, want, "mismatch at seq={}", seq);
            // Immediate duplicate replay must ALWAYS be rejected
            prop_assert!(!sut.check_and_accept(seq));
        }
    }
}
