from collections import deque
from hypothesis import strategies as st
from hypothesis.stateful import RuleBasedStateMachine, invariant, rule

USERS = ["u0", "u1", "u2"]
ROLES = ["viewer", "editor", "auditor", "ops", "admin"]
PERMS = ["read", "write", "approve", "export"]


class RbacStateMachine(RuleBasedStateMachine):
    def __init__(self) -> None:
        super().__init__()
        self.sut = RbacEngine()
        self.user_roles: dict[str, set[str]] = {u: set() for u in USERS}
        self.role_perms: dict[str, set[str]] = {r: set() for r in ROLES}
        self.parents: dict[str, set[str]] = {r: set() for r in ROLES}

    def _reaches(self, start: str, target: str) -> bool:
        q = deque([start])
        seen = {start}
        while q:
            cur = q.popleft()
            if cur == target:
                return True
            for nxt in self.parents[cur]:
                if nxt not in seen:
                    seen.add(nxt)
                    q.append(nxt)
        return False

    @rule(role=st.sampled_from(ROLES), perm=st.sampled_from(PERMS))
    def grant_perm(self, role: str, perm: str) -> None:
        self.sut.grant_perm(role, perm)
        self.role_perms[role].add(perm)

    @rule(role=st.sampled_from(ROLES), perm=st.sampled_from(PERMS))
    def revoke_perm(self, role: str, perm: str) -> None:
        self.sut.revoke_perm(role, perm)
        self.role_perms[role].discard(perm)

    @rule(user=st.sampled_from(USERS), role=st.sampled_from(ROLES))
    def assign_role(self, user: str, role: str) -> None:
        self.sut.assign_user_role(user, role)
        self.user_roles[user].add(role)

    @rule(child=st.sampled_from(ROLES), parent=st.sampled_from(ROLES))
    def inherit_role(self, child: str, parent: str) -> None:
        would_cycle = self._reaches(parent, child)
        added = self.sut.add_role_inheritance(child, parent)
        if would_cycle:
            assert added is False
        else:
            assert added is True
            self.parents[child].add(parent)

    @invariant()
    def all_effective_permissions_match_bfs_oracle(self) -> None:
        for u in USERS:
            reachable_perms: set[str] = set()
            q = deque(self.user_roles[u])
            seen = set(q)
            while q:
                r = q.popleft()
                reachable_perms |= self.role_perms[r]
                for p in self.parents[r]:
                    if p not in seen:
                        seen.add(p)
                        q.append(p)
            for perm in PERMS:
                assert self.sut.user_has_perm(u, perm) == (perm in reachable_perms)


TestRbacEngine = RbacStateMachine.TestCase
