contract EscrowHandler is Test {
    IAtomicOrderEscrow public immutable escrow;
    IMintable20 public immutable sellToken;
    IMintable20 public immutable buyToken;
    address[] public traders;

    mapping(uint256 => IAtomicOrderEscrow.Status) public ghost_terminalState;

    constructor(IAtomicOrderEscrow _escrow, IMintable20 _sell, IMintable20 _buy) {
        escrow = _escrow;
        sellToken = _sell;
        buyToken = _buy;
        traders.push(makeAddr("tr1"));
        traders.push(makeAddr("tr2"));
        traders.push(makeAddr("tr3"));
    }

