        buyToken.mint(taker, buyAmt);
        vm.startPrank(taker);
        buyToken.approve(address(escrow), buyAmt);
        escrow.fillOrder(id);
        vm.stopPrank();

        ghost_terminalState[id] = IAtomicOrderEscrow.Status.Filled;
