#include <array>
#include <cassert>
#include <cstddef>
#include <cstdint>
#include <fuzzer/FuzzedDataProvider.h>
#include <optional>
#include <string>
#include <string_view>
#include <vector>

struct Ipv6Cidr {
    static std::optional<Ipv6Cidr> parse(std::string_view text);
    uint8_t prefix_len() const;
    std::array<uint8_t, 16> network_bytes() const; // masked host bits == 0
    bool contains(const std::array<uint8_t, 16>& addr) const;
    std::string to_string() const;
};

static bool ref_contains(const std::array<uint8_t, 16>& net, uint8_t plen, const std::array<uint8_t, 16>& ip) {
    size_t full_bytes = plen / 8;
    uint8_t rem_bits = plen % 8;
    for (size_t i = 0; i < full_bytes; ++i) {
        if (net[i] != ip[i]) return false;
    }
    if (rem_bits > 0) {
        uint8_t mask = static_cast<uint8_t>(0xFF << (8 - rem_bits));
        if ((net[full_bytes] & mask) != (ip[full_bytes] & mask)) return false;
    }
    return true;
}

extern "C" int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size) {
    FuzzedDataProvider fdp(data, size);
