    std::string raw = fdp.ConsumeRemainingBytesAsString();
    std::vector<char> exact(raw.begin(), raw.end());

    if (auto cidr = Ipv6Cidr::parse({exact.data(), exact.size()})) {
        assert(cidr->prefix_len() <= 128);
        auto net = cidr->network_bytes();
        // Network address must contain itself and match bit-level reference mask
        assert(cidr->contains(net));
        assert(cidr->contains(probe) == ref_contains(net, cidr->prefix_len(), probe));

        std::string canon = cidr->to_string();
        auto reparsed = Ipv6Cidr::parse(canon);
        assert(reparsed.has_value());
        assert(reparsed->prefix_len() == cidr->prefix_len());
        assert(reparsed->network_bytes() == net);
        assert(reparsed->to_string() == canon);
    }
    return 0;
}
