from hypothesis import strategies as st
from hypothesis.stateful import Bundle, RuleBasedStateMachine, initialize, invariant, rule
import pytest

USER_ACCTS = ["alice", "bob", "carol"]
TREASURY = "treasury_clearing"


class DoubleEntryStateMachine(RuleBasedStateMachine):
    entry_ids = Bundle("entry_ids")

    def __init__(self) -> None:
        super().__init__()
        self.ledger = None
        self.reversed_ids: set[int] = set()

    @initialize()
    def setup_accounts(self) -> None:
        self.ledger = DoubleEntryLedger()
        self.reversed_ids.clear()
        # Treasury allows negative clearing balance; user wallets prohibit negative balance
        self.ledger.create_account(TREASURY, allow_negative=True)
        for u in USER_ACCTS:
            self.ledger.create_account(u, allow_negative=False)

    @rule(
        target=entry_ids,
        src=st.sampled_from([TREASURY, *USER_ACCTS]),
        dst=st.sampled_from([TREASURY, *USER_ACCTS]),
        amount=st.integers(min_value=1, max_value=10_000),
    )
    def post_transfer(self, src: str, dst: str, amount: int) -> int | None:
        if src in USER_ACCTS and src != dst and self.ledger.balance(src) < amount:
            with pytest.raises(ValueError):
                self.ledger.post_entry(debit_acct=src, credit_acct=dst, amount=amount)
            return None
        eid = self.ledger.post_entry(debit_acct=src, credit_acct=dst, amount=amount)
        return eid

    @rule(eid=entry_ids)
    def reverse_transfer(self, eid: int | None) -> None:
        if eid is None:
            return
        if eid in self.reversed_ids:
            with pytest.raises(ValueError):
                self.ledger.reverse_entry(eid)
            return
        try:
            self.ledger.reverse_entry(eid)
            self.reversed_ids.add(eid)
        except ValueError:
            # Allowed only if reversing would force a non-negative user account below 0
            pass

    @invariant()
    def zero_sum_and_no_user_overdraft(self) -> None:
        if self.ledger is None:
            return
        all_accts = [TREASURY, *USER_ACCTS]
        total = sum(self.ledger.balance(a) for a in all_accts)
        assert total == 0
        for u in USER_ACCTS:
            assert self.ledger.balance(u) >= 0


TestDoubleEntryLedger = DoubleEntryStateMachine.TestCase
