        token.mint(u, addAmt);
        vm.startPrank(u);
        token.approve(address(ve), addAmt);
        ve.increaseAmount(addAmt);
        vm.stopPrank();
        ghost_totalLocked += addAmt;
    }

    function extendUnlock(uint256 seed, uint256 extraTime) external {
        address u = lockers[seed % lockers.length];
        (uint256 curAmt, uint256 unlock) = ve.lockedOf(u);
        if (curAmt == 0 || block.timestamp >= unlock) return;
        uint256 maxUnlock = block.timestamp + ve.MAX_LOCK();
        if (unlock >= maxUnlock) return;

