    while (pos < raw_headers.size()) {
        size_t eol = raw_headers.find("\r\n", pos);
        if (eol == std::string_view::npos) { *malformed = true; return std::nullopt; }
        std::string_view line = raw_headers.substr(pos, eol - pos);
        pos = eol + 2;
        if (line.empty()) break;
        if (line.front() == ' ' || line.front() == '\t') { *malformed = true; return std::nullopt; }
        size_t colon = line.find(':');
        if (colon == std::string_view::npos) { *malformed = true; return std::nullopt; }
        std::string_view name = line.substr(0, colon);
        if (!name.empty() && (name.back() == ' ' || name.back() == '\t')) { *malformed = true; return std::nullopt; }
        if (iequals_ascii(name, "Transfer-Encoding")) {
            if (seen.has_value()) { *malformed = true; return std::nullopt; }
