use proptest::prelude::*;

#[derive(Default)]
pub struct Utf8ChunkDecoder {
    tail: [u8; 3],
    tail_len: usize,
}

impl Utf8ChunkDecoder {
    pub fn push_chunk(&mut self, mut input: &[u8], out: &mut String) -> Result<(), ()> {
        if self.tail_len > 0 && !input.is_empty() {
            let mut combined = [0u8; 6];
            let take = input.len().min(4 - self.tail_len);
            combined[..self.tail_len].copy_from_slice(&self.tail[..self.tail_len]);
            combined[self.tail_len..self.tail_len + take].copy_from_slice(&input[..take]);
            let total = self.tail_len + take;
            match std::str::from_utf8(&combined[..total]) {
                Ok(s) => {
                    out.push_str(s);
                    self.tail_len = 0;
                    input = &input[take..];
                }
                Err(e) => {
                    let valid = e.valid_up_to();
                    if valid > 0 {
                        out.push_str(std::str::from_utf8(&combined[..valid]).unwrap());
                        let consumed_from_input = valid.saturating_sub(self.tail_len);
                        self.tail_len = 0;
                        input = &input[consumed_from_input..];
                    } else if e.error_len().is_some() {
                        return Err(());
                    } else {
                        self.tail[..total].copy_from_slice(&combined[..total]);
                        self.tail_len = total;
                        return Ok(());
                    }
                }
            }
        }

        match std::str::from_utf8(input) {
            Ok(s) => {
                out.push_str(s);
                Ok(())
            }
            Err(e) => {
                let valid = e.valid_up_to();
                out.push_str(std::str::from_utf8(&input[..valid]).unwrap());
                if e.error_len().is_some() {
                    Err(())
                } else {
                    let rem = &input[valid..];
                    self.tail[..rem.len()].copy_from_slice(rem);
                    self.tail_len = rem.len();
                    Ok(())
                }
            }
        }
    }

    pub fn finish(self) -> Result<(), ()> {
        if self.tail_len == 0 { Ok(()) } else { Err(()) }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn red_green_truncated_eof_and_split_surrogate_proof() {
        let mut dec = Utf8ChunkDecoder::default();
        let mut out = String::new();
        assert_eq!(dec.push_chunk(&[0xED, 0xA0], &mut out), Err(()));

        let mut dec_eof = Utf8ChunkDecoder::default();
        let mut out_eof = String::new();
        assert_eq!(dec_eof.push_chunk(b"ok\xF0\x9F", &mut out_eof), Ok(()));
        assert_eq!(dec_eof.finish(), Err(()));
