        fn differential_against_full_slice_from_utf8(
            data in prop::collection::vec(any::<u8>(), 0..96),
            cuts in prop::collection::vec(1_usize..7_usize, 1..24),
        ) {
            let oracle = std::str::from_utf8(&data).map(|s| s.to_owned()).map_err(|_| ());
            let mut dec = Utf8ChunkDecoder::default();
            let mut acc = String::new();
            let mut pos = 0;
            let mut step = 0;
            let mut stream_res = Ok(());
            while pos < data.len() {
                let n = cuts[step % cuts.len()].min(data.len() - pos);
                if dec.push_chunk(&data[pos..pos + n], &mut acc).is_err() {
