use std::io::{Read, Write};
use flate2::read::GzDecoder;
use flate2::write::GzEncoder;
use flate2::Compression;
use proptest::prelude::*;

#[derive(Debug, PartialEq, Eq)]
pub enum DecompErr {
    EmptyInput,
    OutputCapExceeded,
    RatioCapExceeded,
    CorruptStream,
}

pub fn gunzip_buggy(compressed: &[u8], max_out: usize) -> Result<Vec<u8>, DecompErr> {
    let mut out = Vec::new();
    GzDecoder::new(compressed)
        .take(max_out as u64)
        .read_to_end(&mut out)
        .map_err(|_| DecompErr::CorruptStream)?;
    Ok(out)
}

pub fn gunzip_bounded_fixed(
    compressed: &[u8],
    max_out: usize,
    max_ratio: usize,
) -> Result<Vec<u8>, DecompErr> {
    if compressed.is_empty() {
        return Err(DecompErr::EmptyInput);
    }
    let ratio_limit = compressed.len().saturating_mul(max_ratio);
    let hard_cap = max_out.min(ratio_limit);
    let probe = (hard_cap as u64).saturating_add(1);
    let mut out = Vec::with_capacity(hard_cap.min(4096));
    GzDecoder::new(compressed)
        .take(probe)
        .read_to_end(&mut out)
        .map_err(|_| DecompErr::CorruptStream)?;
    if out.len() > hard_cap {
        return if hard_cap == ratio_limit && ratio_limit < max_out {
            Err(DecompErr::RatioCapExceeded)
        } else {
            Err(DecompErr::OutputCapExceeded)
        };
    }
    Ok(out)
}

fn gzip_pack(raw: &[u8]) -> Vec<u8> {
    let mut enc = GzEncoder::new(Vec::new(), Compression::best());
    enc.write_all(raw).unwrap();
    enc.finish().unwrap()
}

