        let gz = gzip_pack(&exact_plus_one);
        // RED on buggy: returns Ok(100 truncated bytes) instead of failing!
        assert_eq!(gunzip_buggy(&gz, 100).unwrap().len(), 100);
        // GREEN on fixed: detects byte 101 and rejects cleanly
        assert_eq!(gunzip_bounded_fixed(&gz, 100, 50), Err(DecompErr::OutputCapExceeded));

        let bomb = gzip_pack(&vec![0u8; 8192]);
        assert_eq!(gunzip_bounded_fixed(&bomb, 65536, 20), Err(DecompErr::RatioCapExceeded));
    }

    proptest! {
        #[test]
        fn enforces_exact_cap_and_roundtrips_within_budget(
            payload in prop::collection::vec(any::<u8>(), 0..512),
            max_out in 1_usize..400_usize,
            max_ratio in 1_usize..32_usize,
