import fc from 'fast-check';
import { describe, it, expect } from 'vitest';

const enc = new TextEncoder();
const dec = new TextDecoder('utf-8', { fatal: true });

export function truncateBuggy(s: string, maxBytes: number): string {
  let cur = s;
  while (enc.encode(cur).byteLength > maxBytes && cur.length > 0) {
    cur = cur.slice(0, -1);
  }
  return cur;
}

export function truncateUtf8Safe(s: string, maxBytes: number): string {
  if (maxBytes <= 0) return '';
  let used = 0;
  let out = '';
  for (const ch of s) {
    const cp = ch.codePointAt(0)!;
    if (cp >= 0xd800 && cp <= 0xdfff) {
      continue;
    }
    const byteLen = cp <= 0x7f ? 1 : cp <= 0x7ff ? 2 : cp <= 0xffff ? 3 : 4;
    if (used + byteLen > maxBytes) break;
    out += ch;
    used += byteLen;
  }
  return out;
}

function hasLoneSurrogate(s: string): boolean {
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c >= 0xd800 && c <= 0xdbff) {
      const next = s.charCodeAt(i + 1);
      if (!(next >= 0xdc00 && next <= 0xdfff)) return true;
      i++;
    } else if (c >= 0xdc00 && c <= 0xdfff) {
      return true;
    }
  }
  return false;
}

describe('truncateUtf8Safe surrogate-boundary fuzzing', () => {
