#include <algorithm>
#include <cassert>
#include <cstddef>
#include <cstdint>
#include <fuzzer/FuzzedDataProvider.h>
#include <list>
#include <optional>
#include <string>
#include <utility>

template <typename K, typename V>
class LruCache {
public:
    explicit LruCache(size_t capacity);
    void put(const K& key, V value);
    std::optional<V> get(const K& key);
    bool erase(const K& key);
    size_t size() const;
};

struct RefLru {
    size_t cap;
    std::list<std::pair<uint32_t, std::string>> items; // front = MRU, back = LRU

    void put(uint32_t k, std::string v) {
        erase(k);
        items.emplace_front(k, std::move(v));
        if (items.size() > cap) items.pop_back();
    }
    std::optional<std::string> get(uint32_t k) {
        auto it = std::find_if(items.begin(), items.end(), [k](const auto& p) { return p.first == k; });
        if (it == items.end()) return std::nullopt;
        auto kv = std::move(*it);
        items.erase(it);
        items.push_front( kv );
        return items.front().second;
    }
    bool erase(uint32_t k) {
        auto it = std::find_if(items.begin(), items.end(), [k](const auto& p) { return p.first == k; });
        if (it == items.end()) return false;
        items.erase(it);
        return true;
    }
};

extern "C" int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size) {
