    LruCache<uint32_t, std::string> sut(cap);
    RefLru ref{cap, {}};

    uint32_t steps = fdp.ConsumeIntegralInRange<uint32_t>(1, 96);
    for (uint32_t i = 0; i < steps && fdp.remaining_bytes() > 0; ++i) {
