from hypothesis.stateful import RuleBasedStateMachine, invariant, rule
import pytest

PAYLOAD_POOL = [b"", b"alpha", b"beta", b"\x00\xff", b"shared-chunk-payload"]


class CasStoreMachine(RuleBasedStateMachine):
    def __init__(self) -> None:
        super().__init__()
        self.sut = CasBlobStore()
        self.blobs: dict[str, bytes] = {}
        self.refs: dict[str, int] = {}

    @rule(payload=st.sampled_from(PAYLOAD_POOL))
    def put_blob(self, payload: bytes) -> None:
        digest = self.sut.put(payload)
        expected_digest = hashlib.sha256(payload).hexdigest()
        assert digest == expected_digest
        self.blobs[digest] = payload
        self.refs[digest] = self.refs.get(digest, 0) + 1

    @rule(payload=st.sampled_from(PAYLOAD_POOL))
    def retain_blob(self, payload: bytes) -> None:
        digest = hashlib.sha256(payload).hexdigest()
        if self.refs.get(digest, 0) == 0 and digest not in self.blobs:
            with pytest.raises(KeyError):
                self.sut.retain(digest)
        elif digest in self.blobs:
            self.sut.retain(digest)
            self.refs[digest] = self.refs.get(digest, 0) + 1

    @rule(payload=st.sampled_from(PAYLOAD_POOL))
    def release_blob(self, payload: bytes) -> None:
        digest = hashlib.sha256(payload).hexdigest()
        if self.refs.get(digest, 0) <= 0:
            with pytest.raises((KeyError, ValueError)):
                self.sut.release(digest)
        else:
            self.sut.release(digest)
            self.refs[digest] -= 1

    @rule()
    def run_gc(self) -> None:
        reclaimed = self.sut.gc()
        dead = [d for d, cnt in self.refs.items() if cnt == 0 and d in self.blobs]
        assert reclaimed == len(dead)
        for d in dead:
            del self.blobs[d]
            del self.refs[d]

