from hypothesis import strategies as st
from hypothesis.stateful import RuleBasedStateMachine, invariant, rule


class UndoRopeMachine(RuleBasedStateMachine):
    def __init__(self) -> None:
        super().__init__()
        self.sut = UndoRope()
        self.cur = ""
        self.past: list[str] = []
        self.future: list[str] = []

    @rule(
        pos_seed=st.integers(min_value=0, max_value=200),
        chunk=st.text(alphabet="abcd123\n🦀", min_size=1, max_size=12),
    )
    def insert_text(self, pos_seed: int, chunk: str) -> None:
        pos = pos_seed % (len(self.cur) + 1)
        self.sut.insert(pos, chunk)
        self.past.append(self.cur)
        self.cur = self.cur[:pos] + chunk + self.cur[pos:]
        self.future.clear()

    @rule(
        pos_seed=st.integers(min_value=0, max_value=200),
        span=st.integers(min_value=1, max_value=12),
    )
    def delete_text(self, pos_seed: int, span: int) -> None:
        if not self.cur:
            return
        pos = pos_seed % len(self.cur)
        n = min(span, len(self.cur) - pos)
        self.sut.delete(pos, n)
        self.past.append(self.cur)
        self.cur = self.cur[:pos] + self.cur[pos + n :]
        self.future.clear()

    @rule()
    def undo_step(self) -> None:
        ok = self.sut.undo()
        if self.past:
            assert ok is True
            self.future.append(self.cur)
            self.cur = self.past.pop()
        else:
            assert ok is False

    @rule()
    def redo_step(self) -> None:
        ok = self.sut.redo()
        if self.future:
            assert ok is True
            self.past.append(self.cur)
            self.cur = self.future.pop()
        else:
            assert ok is False

    @invariant()
    def text_matches_oracle(self) -> None:
        assert self.sut.to_str() == self.cur
        assert len(self.sut) == len(self.cur)


TestUndoRope = UndoRopeMachine.TestCase
