#include <cassert>
#include <cstddef>
#include <cstdint>
#include <optional>
#include <set>
#include <string>

std::optional<std::string> unpack_dns_name_fixed(const uint8_t* pkt, size_t pkt_len, size_t offset) {
    if (offset >= pkt_len) return std::nullopt;
    std::string out;
    size_t cur = offset;
    size_t lowest_ptr_src = pkt_len;
    size_t wire_octets = 0;

    while (true) {
        if (cur >= pkt_len) return std::nullopt;
        uint8_t len = pkt[cur];
        if (len == 0) {
            wire_octets += 1;
            if (wire_octets > 255) return std::nullopt;
            return out;
        }
        if ((len & 0xC0) == 0xC0) {
            if (cur + 1 >= pkt_len) return std::nullopt;
            size_t target = (static_cast<size_t>(len & 0x3F) << 8) | pkt[cur + 1];
            if (target >= cur || target >= lowest_ptr_src) return std::nullopt;
            lowest_ptr_src = cur;
            cur = target;
            continue;
        }
        if ((len & 0xC0) != 0) return std::nullopt;
        if (len > 63 || cur + 1 + len > pkt_len) return std::nullopt;
        wire_octets += 1 + len;
        if (wire_octets > 255) return std::nullopt;
        if (!out.empty()) out.push_back('.');
        out.append(reinterpret_cast<const char*>(pkt + cur + 1), len);
        cur += 1 + len;
    }
}

std::optional<std::string> unpack_dns_oracle_visited(const uint8_t* pkt, size_t pkt_len, size_t offset) {
