    std::set<size_t> seen;
    std::string out;
    size_t cur = offset;
    size_t octets = 0;
    while (cur < pkt_len) {
        if (!seen.insert(cur).second) return std::nullopt;
        uint8_t b = pkt[cur];
        if (b == 0) return (octets + 1 <= 255) ? std::optional<std::string>(out) : std::nullopt;
        if ((b & 0xC0) == 0xC0) {
            if (cur + 1 >= pkt_len) return std::nullopt;
            size_t tgt = (static_cast<size_t>(b & 0x3F) << 8) | pkt[cur + 1];
            if (tgt >= cur) return std::nullopt;
            cur = tgt;
        } else if ((b & 0xC0) == 0) {
            if (b > 63 || cur + 1 + b > pkt_len) return std::nullopt;
            octets += 1 + b;
            if (octets > 255) return std::nullopt;
            if (!out.empty()) out.push_back('.');
            out.append(reinterpret_cast<const char*>(pkt + cur + 1), b);
            cur += 1 + b;
        } else {
