use std::collections::BTreeMap;
use proptest::prelude::*;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum CanonErr {
    NonFiniteFloat,
}

pub fn format_float_buggy(v: f64) -> String {
    format!("{v}")
}

pub fn format_float_canonical(v: f64) -> Result<String, CanonErr> {
    if !v.is_finite() {
        return Err(CanonErr::NonFiniteFloat);
    }
    if v == 0.0 {
        return Ok("0".to_owned());
    }
    let mut buf = ryu::Buffer::new();
    let s = buf.format_finite(v);
    Ok(s.strip_suffix(".0").unwrap_or(s).to_owned())
}

pub fn canonical_flat_object(entries: &[(String, f64)]) -> Result<String, CanonErr> {
    let mut sorted = BTreeMap::new();
    for (k, v) in entries {
        sorted.insert(k.as_str(), format_float_canonical(*v)?);
    }
    let mut out = String::from("{");
    for (idx, (k, num_txt)) in sorted.iter().enumerate() {
        if idx > 0 {
            out.push(',');
        }
        out.push_str(&serde_json::to_string(k).unwrap());
        out.push(':');
        out.push_str(num_txt);
    }
    out.push('}');
    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn red_green_neg_zero_and_nan_proof() {
        // RED on buggy formatter: emits "-0" and "NaN" (invalid JSON / broken signature digest)!
        assert_eq!(format_float_buggy(-0.0), "-0");
        assert_eq!(format_float_buggy(f64::NAN), "NaN");

        // GREEN on canonical formatter:
        assert_eq!(format_float_canonical(-0.0), Ok("0".into()));
        assert_eq!(format_float_canonical(0.0), Ok("0".into()));
        assert_eq!(format_float_canonical(f64::NAN), Err(CanonErr::NonFiniteFloat));
        assert_eq!(format_float_canonical(f64::INFINITY), Err(CanonErr::NonFiniteFloat));
    }

    proptest! {
        #[test]
        fn permutation_and_neg_zero_invariant(
            pairs in prop::collection::vec(("[a-z]{1,6}", prop_oneof![Just(-0.0), Just(0.0), -1000.0_f64..1000.0_f64]), 0..10)
        ) {
            let mut unique: BTreeMap<String, f64> = BTreeMap::new();
            for (k, v) in &pairs {
                unique.insert(k.clone(), *v);
            }
            let fwd: Vec<(String, f64)> = unique.iter().map(|(k, &v)| (k.clone(), v)).collect();
            let rev: Vec<(String, f64)> = fwd.iter().rev().map(|(k, &v)| (k.clone(), if v == 0.0 { -0.0 } else { v })).collect();

