use std::collections::BTreeMap;
use proptest::prelude::*;

#[derive(Debug, PartialEq, Eq)]
pub struct NormalizedHeaders {
    pub host: Option<String>,
    pub set_cookies: Vec<String>,
    pub combined: BTreeMap<String, String>,
}

#[derive(Debug, PartialEq, Eq)]
pub enum HeaderErr {
    DuplicateHost,
    ControlCharInValue,
}

pub fn normalize_headers_fixed(raw: &[(String, String)]) -> Result<NormalizedHeaders, HeaderErr> {
    let mut host: Option<String> = None;
    let mut set_cookies: Vec<String> = Vec::new();
    let mut combined: BTreeMap<String, String> = BTreeMap::new();

    for (k, v) in raw {
        if v.bytes().any(|b| b == 0 || b == b'\r' || b == b'\n') {
            return Err(HeaderErr::ControlCharInValue);
        }
        let val = v.trim_matches(|c| c == ' ' || c == '\t').to_owned();
        let lower = k.to_ascii_lowercase();
        match lower.as_str() {
            "host" => {
                if host.is_some() {
                    return Err(HeaderErr::DuplicateHost);
                }
                host = Some(val);
            }
            "set-cookie" => {
                set_cookies.push(val);
            }
            _ => {
                combined
                    .entry(lower)
                    .and_modify(|existing| {
                        existing.push_str(", ");
                        existing.push_str(&val);
                    })
                    .or_insert(val);
            }
        }
    }
    Ok(NormalizedHeaders { host, set_cookies, combined })
}

#[cfg(test)]
mod tests {
