    #[test]
    fn red_green_duplicate_host_and_set_cookie_comma_proof() {
        let dup_host = vec![
            ("Host".into(), "good.example".into()),
            ("hOsT".into(), "evil.example".into()),
        ];
        assert_eq!(normalize_headers_fixed(&dup_host), Err(HeaderErr::DuplicateHost));

        let cookies = vec![
            ("Set-Cookie".into(), "sid=abc; Expires=Wed, 21 Oct 2026 07:28:00 GMT".into()),
            ("set-cookie".into(), "theme=dark; Path=/".into()),
            ("Cache-Control".into(), "no-cache".into()),
            ("cache-control".into(), "no-store".into()),
        ];
        let norm = normalize_headers_fixed(&cookies).unwrap();
        assert_eq!(norm.set_cookies.len(), 2);
        assert_eq!(norm.combined.get("cache-control").unwrap(), "no-cache, no-store");
    }

    proptest! {
        #[test]
        fn case_folding_and_crlf_rejection_invariants(
            headers in prop::collection::vec(
                (prop::sample::select(vec!["Host", "HOST", "Set-Cookie", "set-cookie", "Accept", "accept"]), "[a-zA-Z0-9;=, \r\n\0]{0,20}"),
