def canonicalize_query_strict(raw_query: str) -> bytes:
    if not raw_query:
        return b""
    if "\x00" in raw_query:
        raise ValueError("NUL forbidden")
    items: list[tuple[str, bool, str]] = []
    for seg in raw_query.split("&"):
