export function canonicalizeHeadersFixed(headers: Array<[string, string]>): string {
  const acc = new Map<string, string[]>();
  for (const [k, v] of headers) {
    if (/[\r\n\0]/.test(k) || /[\r\n\0]/.test(v)) {
      throw new Error('Forbidden control char in header');
