```ts
import fc from 'fast-check';
import { describe, it, expect } from 'vitest';

export function checkLimitsBuggy(val: unknown, maxDepth: number, ancestors = new Set<object>(), depth = 0): void {
  if (typeof val !== 'object' || val === null) return;
  if (depth > maxDepth) throw new Error('Max depth exceeded');
  if (ancestors.has(val)) throw new Error('Cycle detected');
  ancestors.add(val);
  if (Array.isArray(val)) {
    for (const item of val) checkLimitsBuggy(item, maxDepth, ancestors, depth + 1);
  } else {
    for (const k of Object.keys(val)) {
      checkLimitsBuggy((val as Record<string, unknown>)[k], maxDepth, ancestors, depth + 1);
    }
  }
  ancestors.delete(val);
}

export function enforceJsonStructureLimits(
  root: unknown,
  maxDepth: number,
  maxNodes: number
): number {
  let totalNodes = 0;
  const stack: Array<{ node: unknown; depth: number; exiting?: object }> = [{ node: root, depth: 0 }];
  const activeAncestors = new Set<object>();

  while (stack.length > 0) {
    const frame = stack.pop()!;
    if (frame.exiting) {
      activeAncestors.delete(frame.exiting);
      continue;
    }
    totalNodes += 1;
    if (totalNodes > maxNodes) {
      throw new Error(`Expanded node budget exceeded (${maxNodes})`);
    }
    const { node, depth } = frame;
    if (typeof node !== 'object' || node === null) continue;

    const nextDepth = depth + 1;
    if (nextDepth > maxDepth) {
      throw new Error(`Container nesting depth exceeded (${maxDepth})`);
    }
    if (activeAncestors.has(node)) {
      throw new Error('Circular reference forbidden');
    }
    activeAncestors.add(node);
    stack.push({ node: null, depth, exiting: node });

    if (Array.isArray(node)) {
      for (let i = node.length - 1; i >= 0; i--) {
        stack.push({ node: node[i], depth: nextDepth });
      }
    } else {
      const keys = Object.keys(node);
      for (let i = keys.length - 1; i >= 0; i--) {
        stack.push({ node: (node as Record<string, unknown>)[keys[i]], depth: nextDepth });
      }
    }
  }
  return totalNodes;
}

describe('enforceJsonStructureLimits depth off-by-one & DAG bomb proof', () => {
  it('red-green proof: rejects depth maxDepth+1 and exponential shared-reference DAG', () => {
    const depthThree = [[[1]]];
    // RED on buggy: depth starts at 0 on outer array, allowing 3 nested containers when maxDepth=2!
    expect(() => checkLimitsBuggy(depthThree, 2)).not.toThrow();
    // GREEN on fixed:
    expect(() => enforceJsonStructureLimits(depthThree, 2, 100)).toThrow(/depth/);
    expect(enforceJsonStructureLimits([[1]], 2, 100)).toBe(3);

    let dag: unknown = 'leaf';
    for (let i = 0; i < 14; i++) dag = [dag, dag];
    expect(() => enforceJsonStructureLimits(dag, 20, 1000)).toThrow(/budget exceeded/);
  });

  it('matches recursive reference node count and depth on arbitrary JSON trees', () => {
    fc.assert(
      fc.property(fc.jsonValue({ maxDepth: 5 }), (tree) => {
        function measureOracle(v: unknown): { depth: number; nodes: number } {
          if (typeof v !== 'object' || v === null) return { depth: 0, nodes: 1 };
          const children = Array.isArray(v) ? v : Object.values(v);
          let maxChildDepth = 0;
          let sumNodes = 1;
          for (const c of children) {
            const m = measureOracle(c);
            if (m.depth > maxChildDepth) maxChildDepth = m.depth;
            sumNodes += m.nodes;
          }
          return { depth: 1 + maxChildDepth, nodes: sumNodes };
        }

        const { depth, nodes } = measureOracle(tree);
        expect(enforceJsonStructureLimits(tree, depth, nodes)).toBe(nodes);
        if (depth > 0) {
          expect(() => enforceJsonStructureLimits(tree, depth - 1, nodes)).toThrow();
        }
        expect(() => enforceJsonStructureLimits(tree, depth, nodes - 1)).toThrow();
      })
    );
  });
});
