// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "forge-std/Test.sol";

contract BuggyRewards {
    uint256 public constant DURATION = 1000;
    uint256 public rewardRate;
    uint256 public periodFinish;
    uint256 public totalFunded;

    function notify(uint256 amount) external {
        totalFunded += amount;
        if (block.timestamp >= periodFinish) {
            rewardRate = amount / DURATION;
        } else {
            uint256 rem = (periodFinish - block.timestamp) * rewardRate;
            rewardRate = (amount + rem) / DURATION;
        }
        periodFinish = block.timestamp + DURATION;
    }

    function maxDistributableInCurrentEpoch() external view returns (uint256) {
        return rewardRate * DURATION;
    }
}

contract FixedRewards {
    uint256 public constant DURATION = 1000;
    uint256 public constant PRECISION = 1e18;
    uint256 public scaledRewardRate;
    uint256 public periodFinish;
    uint256 public lastUpdate;
    uint256 public totalFunded;
    uint256 public totalAccruedScaled;

    function accrue() public {
        uint256 applicable = block.timestamp < periodFinish ? block.timestamp : periodFinish;
        if (applicable > lastUpdate) {
            totalAccruedScaled += (applicable - lastUpdate) * scaledRewardRate;
            lastUpdate = applicable;
        }
    }

    function notify(uint256 amount) external {
        accrue();
        totalFunded += amount;
        uint256 scaledAmount = amount * PRECISION;
        if (block.timestamp >= periodFinish) {
            uint256 leftover = (totalFunded * PRECISION - amount * PRECISION) - totalAccruedScaled;
            scaledRewardRate = (scaledAmount + leftover) / DURATION;
        } else {
            uint256 remainingTime = periodFinish - block.timestamp;
            uint256 unspent = remainingTime * scaledRewardRate;
            uint256 dust = (totalFunded * PRECISION - amount * PRECISION) - totalAccruedScaled - unspent;
            scaledRewardRate = (scaledAmount + unspent + dust) / DURATION;
        }
        lastUpdate = block.timestamp;
        periodFinish = block.timestamp + DURATION;
    }

    function totalClaimableAfterFinish() external view returns (uint256) {
        uint256 rem = block.timestamp < periodFinish ? (periodFinish - lastUpdate) * scaledRewardRate : 0;
        return (totalAccruedScaled + rem) / PRECISION;
    }
}

contract RewardsHandler is Test {
    FixedRewards public pool;
    constructor(FixedRewards _p) { pool = _p; }

    function actionNotify(uint64 rawAmt, uint32 warpSec) external {
        vm.warp(block.timestamp + bound(uint256(warpSec), 0, 2500));
        uint256 amt = bound(uint256(rawAmt), 1, 1_000_000e6);
        pool.notify(amt);
    }
}

contract StakingPrecisionTest is Test {
    BuggyRewards buggy;
    FixedRewards fixedPool;
    RewardsHandler handler;

    function setUp() public {
        vm.warp(10_000);
        buggy = new BuggyRewards();
        fixedPool = new FixedRewards();
        handler = new RewardsHandler(fixedPool);
        targetContract(address(handler));
    }

    function test_RedGreen_SubDurationRewardZeroTruncation() public {
        buggy.notify(999);
        // RED on buggy: 999 / 1000 == 0 -> 100% of reward permanently locked!
        assertEq(buggy.maxDistributableInCurrentEpoch(), 0);

        // GREEN on fixed: scaled rate distributes 998..999 units (< 1 wei total rounding dust)!
        fixedPool.notify(999);
        vm.warp(block.timestamp + 1000);
        fixedPool.accrue();
        assertGe(fixedPool.totalClaimableAfterFinish(), 998);
    }

    function invariant_ZeroLockedFundsAndSolvency() public view {
        uint256 claimable = fixedPool.totalClaimableAfterFinish();
        assertLe(claimable, fixedPool.totalFunded());
        if (fixedPool.totalFunded() > 0) {
