// Target API:
// pub fn compile_cron_minute(expr: &str) -> Result<u64, CronError>;

#[derive(Debug, Clone)]
enum CronTerm {
    WildcardStep(u8),
    Single(u8),
    RangeStep(u8, u8, u8),
}

impl CronTerm {
    fn render(&self) -> String {
        match *self {
            Self::WildcardStep(1) => "*".to_owned(),
            Self::WildcardStep(s) => format!("*/{s}"),
            Self::Single(v) => v.to_string(),
            Self::RangeStep(lo, hi, 1) => format!("{lo}-{hi}"),
            Self::RangeStep(lo, hi, s) => format!("{lo}-{hi}/{s}"),
