                }
            }
            Self::Single(v) => mask |= 1_u64 << v,
            Self::RangeStep(lo, hi, s) => {
                for m in (lo..=hi).step_by(usize::from(s)) {
                    mask |= 1_u64 << m;
                }
            }
        }
        mask
    }
}

fn arb_cron_term() -> impl Strategy<Value = CronTerm> {
