use proptest::prelude::*;

// Target API:
// pub fn glob_match(pattern: &str, candidate: &str) -> bool;

fn collapse_stars(pat: &str) -> String {
    let mut out = String::with_capacity(pat.len());
    let mut prev_star = false;
    for ch in pat.chars() {
        if ch == '*' {
            if !prev_star {
                out.push('*');
            }
            prev_star = true;
        } else {
            prev_star = false;
            out.push(ch);
        }
    }
    out
}

proptest! {
    #[test]
    fn glob_star_collapse_and_reflexivity(
        pat in "[ab*?🦀é]{0,20}",
        txt in "[ab🦀é]{0,24}",
    ) {
        let collapsed = collapse_stars(&pat);
        prop_assert_eq!(glob_match(&pat, &txt), glob_match(&collapsed, &txt));

        // Literal text with no '*' or '?' matches itself and matches '?' per char
        let q_pat: String = txt.chars().map(|_| '?').collect();
        prop_assert!(glob_match(&txt, &txt));
        prop_assert!(glob_match(&q_pat, &txt));
    }

    #[test]
    fn glob_linear_time_on_adversarial_backtracking_inputs(
        stars in 8_usize..=24_usize,
        a_len in 32_usize..=96_usize,
    ) {
        let pat = format!("{}b", "*a".repeat(stars));
        let candidate = "a".repeat(a_len);
        // Must complete in microseconds without exponential recursion
        prop_assert!(!glob_match(&pat, &candidate));
    }
