```python
from hypothesis import strategies as st
from hypothesis.stateful import RuleBasedStateMachine, invariant, rule

JOBS = ["j0", "j1", "j2", "j3", "j4", "j5", "j6"]


class PriorityQueueMachine(RuleBasedStateMachine):
    def __init__(self) -> None:
        super().__init__()
        self.sut = PriorityJobQueue()
        self.model: dict[str, tuple[int, int]] = {}
        self.seq = 0

    @rule(jid=st.sampled_from(JOBS), prio=st.integers(min_value=-20, max_value=20))
    def enqueue_or_update(self, jid: str, prio: int) -> None:
        if jid in self.model:
            ok = self.sut.reprioritize(jid, prio)
            assert ok is True
        else:
            self.sut.enqueue(jid, prio)
        self.seq += 1
        self.model[jid] = (prio, self.seq)

    @rule(jid=st.sampled_from(JOBS))
    def cancel_job(self, jid: str) -> None:
        removed = self.sut.cancel(jid)
        expected = self.model.pop(jid, None) is not None
        assert removed == expected

    @rule()
    def pop_highest_job(self) -> None:
        got = self.sut.pop_max()
        if not self.model:
            assert got is None
            return
        # Highest priority wins; earlier sequence number wins ties (FIFO)
        best_id = max(self.model, key=lambda k: (self.model[k][0], -self.model[k][1]))
        best_prio, _ = self.model.pop(best_id)
        assert got == (best_id, best_prio)

    @invariant()
    def length_matches_oracle(self) -> None:
        assert len(self.sut) == len(self.model)


TestPriorityJobQueue = PriorityQueueMachine.TestCase
