from hypothesis import given, strategies as st
import pytest


def ref_compile_sql_like(pattern: str, esc: str = "\\") -> re.Pattern[str]:
    out = ["\\A"]
    i = 0
    while i < len(pattern):
        ch = pattern[i]
        if ch == esc:
            if i + 1 >= len(pattern):
                raise ValueError("dangling escape char at end of LIKE pattern")
