// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {Test} from "forge-std/Test.sol";
import {StdInvariant} from "forge-std/StdInvariant.sol";
import {IERC20} from "forge-std/interfaces/IERC20.sol";

interface ISimpleCdp {
    function usdToken() external view returns (IERC20);
    function ethPriceUsd() external view returns (uint256); // 1e18 scaled
    function MIN_RATIO_BPS() external view returns (uint256); // e.g. 15000 = 150%
    function collateralOf(address user) external view returns (uint256);
    function debtOf(address user) external view returns (uint256);
    function lockEth() external payable;
    function unlockEth(uint256 ethAmount) external;
    function mintUsd(uint256 usdAmount) external;
    function burnUsd(uint256 usdAmount) external;
}

contract CdpHandler is Test {
    ISimpleCdp public immutable cdp;
    IERC20 public immutable usd;
    address[] public vaults;

    constructor(ISimpleCdp _cdp) {
        cdp = _cdp;
        usd = _cdp.usdToken();
        vaults.push(makeAddr("v1"));
        vaults.push(makeAddr("v2"));
        vaults.push(makeAddr("v3"));
    }

    function vaultCount() external view returns (uint256) {
        return vaults.length;
    }

    function lockEth(uint256 seed, uint256 ethAmt) external {
        address v = vaults[seed % vaults.length];
        ethAmt = bound(ethAmt, 0.1 ether, 100 ether);
        vm.deal(v, ethAmt);
        vm.prank(v);
        cdp.lockEth{value: ethAmt}();
    }

    function mintUsd(uint256 seed, uint256 usdAmt) external {
        address v = vaults[seed % vaults.length];
        uint256 colVal = (cdp.collateralOf(v) * cdp.ethPriceUsd()) / 1e18;
        uint256 maxDebt = (colVal * 10_000) / cdp.MIN_RATIO_BPS();
        uint256 curDebt = cdp.debtOf(v);
        if (maxDebt <= curDebt) return;

        usdAmt = bound(usdAmt, 1, maxDebt - curDebt);
        vm.prank(v);
        cdp.mintUsd(usdAmt);
    }

    function burnUsd(uint256 seed, uint256 usdAmt) external {
        address v = vaults[seed % vaults.length];
        uint256 curDebt = cdp.debtOf(v);
        uint256 bal = usd.balanceOf(v);
        uint256 maxRepay = curDebt < bal ? curDebt : bal;
        if (maxRepay == 0) return;

        usdAmt = bound(usdAmt, 1, maxRepay);
        vm.startPrank(v);
        usd.approve(address(cdp), usdAmt);
        cdp.burnUsd(usdAmt);
        vm.stopPrank();
    }

    function unlockEth(uint256 seed, uint256 ethAmt) external {
        address v = vaults[seed % vaults.length];
        uint256 curCol = cdp.collateralOf(v);
        uint256 curDebt = cdp.debtOf(v);
        if (curCol == 0) return;

        uint256 reqCol = curDebt == 0
            ? 0
            : ((curDebt * cdp.MIN_RATIO_BPS() * 1e18) + (cdp.ethPriceUsd() * 10_000 - 1)) / (cdp.ethPriceUsd() * 10_000);
        if (curCol <= reqCol) return;

        ethAmt = bound(ethAmt, 1, curCol - reqCol);
        vm.prank(v);
        cdp.unlockEth(ethAmt);
    }
}

contract SimpleCdpInvariantTest is StdInvariant, Test {
    ISimpleCdp internal cdp;
    CdpHandler internal handler;

    function setUp() public {
        cdp = deployCdp();
        handler = new CdpHandler(cdp);
        targetContract(address(handler));
    }

    function deployCdp() internal virtual returns (ISimpleCdp);

    function invariant_debtMatchesSupplyAndAllVaultsCollateralized() public view {
        uint256 sumCol = 0;
        uint256 sumDebt = 0;
        uint256 price = cdp.ethPriceUsd();
        uint256 minRatio = cdp.MIN_RATIO_BPS();

        for (uint256 i = 0; i < handler.vaultCount(); ++i) {
            address v = handler.vaults(i);
            uint256 c = cdp.collateralOf(v);
            uint256 d = cdp.debtOf(v);
            sumCol += c;
            sumDebt += d;
            uint256 colUsd = (c * price) / 1e18;
            assertGe(colUsd * 10_000, d * minRatio);
        }
        assertEq(address(cdp).balance, sumCol);
        assertEq(cdp.usdToken().totalSupply(), sumDebt);
    }
}
```

