// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {Test} from "forge-std/Test.sol";
import {StdInvariant} from "forge-std/StdInvariant.sol";

interface IRoyaltyMarketplace {
    function protocolTreasury() external view returns (address);
    function creditOf(address account) external view returns (uint256);
    function recordSale(address seller, address creator, uint96 royaltyBps) external payable;
    function withdrawCredits() external returns (uint256 paid);
}

contract MarketplaceHandler is Test {
    IRoyaltyMarketplace public immutable market;
    address[] public participants;

    uint256 public ghost_totalSalesVolume;
    uint256 public ghost_totalWithdrawn;

    constructor(IRoyaltyMarketplace _market) {
        market = _market;
        participants.push(_market.protocolTreasury());
        participants.push(makeAddr("sellerA"));
        participants.push(makeAddr("sellerB"));
        participants.push(makeAddr("creatorX"));
        participants.push(makeAddr("creatorY"));
    }

    function participantCount() external view returns (uint256) {
        return participants.length;
    }

    function executeSale(uint256 sellerSeed, uint256 creatorSeed, uint96 royaltyBps, uint256 priceWei) external {
        // Pick from sellers/creators (indices 1..4), allowing seller == creator self-royalty edge case!
        address seller = participants[1 + (sellerSeed % 4)];
        address creator = participants[1 + (creatorSeed % 4)];
        royaltyBps = uint96(bound(royaltyBps, 0, 1_000)); // 0..10%
        priceWei = bound(priceWei, 1, 100 ether); // odd wei values catch rounding leaks!

        address buyer = makeAddr("buyer");
        vm.deal(buyer, priceWei);
        vm.prank(buyer);
        market.recordSale{value: priceWei}(seller, creator, royaltyBps);
        ghost_totalSalesVolume += priceWei;
    }

    function claimCredits(uint256 idxSeed) external {
        address acct = participants[idxSeed % participants.length];
        if (market.creditOf(acct) == 0) return;
        uint256 pre = acct.balance;
        vm.prank(acct);
        uint256 paid = market.withdrawCredits();
        assertEq(acct.balance - pre, paid);
        assertEq(market.creditOf(acct), 0);
        ghost_totalWithdrawn += paid;
    }
}

contract RoyaltyMarketplaceInvariantTest is StdInvariant, Test {
    IRoyaltyMarketplace internal market;
    MarketplaceHandler internal handler;

    function setUp() public {
        market = deployMarketplace(makeAddr("treasury"));
        handler = new MarketplaceHandler(market);
        targetContract(address(handler));
    }

    function deployMarketplace(address treasury) internal virtual returns (IRoyaltyMarketplace);

    function invariant_zeroTrappedDustAndExactCreditCustody() public view {
        uint256 sumCredits = 0;
        for (uint256 i = 0; i < handler.participantCount(); ++i) {
            sumCredits += market.creditOf(handler.participants(i));
        }
        // Zero dust trapped: every single wei from sales is either in credits or already withdrawn!
