#include <cassert>
#include <cstddef>
#include <cstdint>
#include <optional>
#include <vector>
#include <zlib.h>

std::vector<uint8_t> deflate_helper(const uint8_t* raw, size_t len) {
    uLong bound = compressBound(static_cast<uLong>(len));
    std::vector<uint8_t> out(bound);
    uLong dest_len = bound;
    int rc = compress2(out.data(), &dest_len, raw, static_cast<uLong>(len), Z_BEST_COMPRESSION);
    assert(rc == Z_OK);
    out.resize(dest_len);
    return out;
}

std::optional<std::vector<uint8_t>> zlib_inflate_fixed(
    const uint8_t* src,
    size_t src_len,
    size_t max_out,
    size_t max_ratio
) {
    if (src_len == 0) return std::nullopt;
    size_t ratio_cap = (src_len > SIZE_MAX / max_ratio) ? SIZE_MAX : src_len * max_ratio;
    size_t hard_cap = (max_out < ratio_cap) ? max_out : ratio_cap;

    z_stream strm{};
    strm.next_in = const_cast<Bytef*>(src);
    strm.avail_in = static_cast<uInt>(src_len);
    if (inflateInit(&strm) != Z_OK) return std::nullopt;

    std::vector<uint8_t> out;
    uint8_t chunk[1024];
    int ret = Z_OK;
    while (ret != Z_STREAM_END) {
        strm.next_out = chunk;
        strm.avail_out = sizeof(chunk);
        ret = inflate(&strm, Z_NO_FLUSH);
        if (ret != Z_OK && ret != Z_STREAM_END) {
            inflateEnd(&strm);
            return std::nullopt;
        }
        size_t produced = sizeof(chunk) - strm.avail_out;
        if (produced > hard_cap - out.size()) {
            inflateEnd(&strm);
            return std::nullopt;
        }
        out.insert(out.end(), chunk, chunk + produced);
        if (ret == Z_OK && produced == 0 && strm.avail_in == 0) {
            inflateEnd(&strm);
            return std::nullopt;
        }
    }
    bool has_trailing = (strm.avail_in != 0);
    inflateEnd(&strm);
    if (has_trailing) return std::nullopt;
