use proptest::prelude::*;

#[derive(Debug, PartialEq, Eq)]
pub enum LebErr {
    UnexpectedEof,
    OverflowOrUnusedBits,
}

pub fn encode_sleb_i64(mut val: i64) -> Vec<u8> {
    let mut out = Vec::with_capacity(10);
    loop {
        let mut byte = (val as u8) & 0x7F;
        val >>= 7;
        let done = (val == 0 && (byte & 0x40) == 0) || (val == -1 && (byte & 0x40) != 0);
        if !done {
            byte |= 0x80;
        }
        out.push(byte);
        if done {
            return out;
        }
    }
}

pub fn decode_sleb_i64_fixed(buf: &[u8]) -> Result<(i64, usize), LebErr> {
    let mut result: u64 = 0;
    for (i, &byte) in buf.iter().take(10).enumerate() {
        let shift = (i * 7) as u32;
        if i == 9 {
            if (byte & 0x80) != 0 {
                return Err(LebErr::OverflowOrUnusedBits);
            }
            if byte != 0x00 && byte != 0x7F {
                return Err(LebErr::OverflowOrUnusedBits);
            }
        }
        result |= ((byte & 0x7F) as u64) << shift;
        if (byte & 0x80) == 0 {
            let next_shift = shift + 7;
            if next_shift < 64 && (byte & 0x40) != 0 {
                result |= (!0u64) << next_shift;
            }
            return Ok((result as i64, i + 1));
        }
    }
    Err(LebErr::UnexpectedEof)
}

