import fc from 'fast-check';
import { describe, it, expect } from 'vitest';

export function addMonthsBuggy(y: number, m_one: number, d: number, delta: number): string {
  const dt = new Date(Date.UTC(y, m_one - 1, d));
  dt.setUTCMonth(dt.getUTCMonth() + delta);
  return dt.toISOString().slice(0, 10);
}

export function isLeapYearGregorian(year: number): boolean {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

export function daysInMonthUTC(year: number, month_one_based: number): number {
  switch (month_one_based) {
    case 2:
      return isLeapYearGregorian(year) ? 29 : 28;
    case 4:
    case 6:
    case 9:
    case 11:
      return 30;
    default:
      return 31;
  }
}

export function addBillingMonthsClamped(y: number, m_one: number, d: number, delta: number): string {
  if (m_one < 1 || m_one > 12 || d < 1 || d > daysInMonthUTC(y, m_one)) {
    throw new RangeError('Invalid input calendar date');
  }
  const totalMonths = y * 12 + (m_one - 1) + delta;
  const targetYear = Math.floor(totalMonths / 12);
  const targetMonthZero = ((totalMonths % 12) + 12) % 12;
  const targetMonthOne = targetMonthZero + 1;
  const clampedDay = Math.min(d, daysInMonthUTC(targetYear, targetMonthOne));
  const padTwo = (n: number) => String(n).padStart(2, '0');
  return `${String(targetYear).padStart(4, '0')}-${padTwo(targetMonthOne)}-${padTwo(clampedDay)}`;
}

