#include <cassert>
#include <cstddef>
#include <cstdint>
#include <fuzzer/FuzzedDataProvider.h>
#include <unordered_map>

class CuckooFilter {
public:
    explicit CuckooFilter(size_t bucket_count);
    bool insert(uint64_t key);
    bool remove(uint64_t key);
    bool possibly_contains(uint64_t key) const;
    size_t count() const;
