extern "C" int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size) {
    FuzzedDataProvider fdp(data, size);
    size_t buckets = size_t{1} << fdp.ConsumeIntegralInRange<size_t>(3, 7); // 8..128
    CuckooFilter filter(buckets);
    // Only remove keys we actually inserted so we never falsely evict a fingerprint twin!
    std::unordered_map<uint64_t, size_t> active_counts;
    size_t total_live = 0;

    uint32_t ops = fdp.ConsumeIntegralInRange<uint32_t>(1, 120);
    for (uint32_t i = 0; i < ops && fdp.remaining_bytes() > 0; ++i) {
        uint64_t key = fdp.ConsumeIntegral<uint64_t>();
        if (fdp.ConsumeBool() || active_counts.empty()) {
            if (filter.insert(key)) {
                active_counts[key] += 1;
                total_live += 1;
            }
        } else {
            auto it = active_counts.begin();
            uint64_t target = it->first;
            bool removed = filter.remove(target);
            assert(removed);
            if (--(it->second) == 0) {
                active_counts.erase(it);
            }
            total_live -= 1;
        }
        assert(filter.count() == total_live);

        // Fundamental invariant: ZERO false negatives for all currently active keys!
        for (const auto& [live_key, mult] : active_counts) {
            if (mult > 0) {
                assert(filter.possibly_contains(live_key));
            }
        }
    }
