#![no_main]

use arbitrary::Arbitrary;
use libfuzzer_sys::fuzz_target;
use std::collections::VecDeque;

#[derive(Debug, Clone, Arbitrary)]
enum DequeOp {
    PushFront(u64),
    PushBack(u64),
    PopFront,
    PopBack,
    Get(u8),
}

#[derive(Debug, Arbitrary)]
struct FuzzInput {
    cap_raw: u8,
    ops: Vec<DequeOp>,
}

fuzz_target!(|input: FuzzInput| {
    let cap = usize::from(input.cap_raw % 16) + 1; // 1..=16 tight wrap-around!
    let mut sut = ArrayDeque::with_capacity(cap);
    let mut oracle: VecDeque<u64> = VecDeque::with_capacity(cap);

    for op in input.ops.into_iter().take(256) {
        match op {
            DequeOp::PushFront(v) => {
                let ok = sut.push_front(v);
                if oracle.len() < cap {
                    assert!(ok);
                    oracle.push_front(v);
                } else {
                    assert!(!ok);
                }
            }
            DequeOp::PushBack(v) => {
                let ok = sut.push_back(v);
                if oracle.len() < cap {
                    assert!(ok);
                    oracle.push_back(v);
                } else {
                    assert!(!ok);
                }
            }
            DequeOp::PopFront => {
                assert_eq!(sut.pop_front(), oracle.pop_front());
            }
            DequeOp::PopBack => {
                assert_eq!(sut.pop_back(), oracle.pop_back());
            }
            DequeOp::Get(idx) => {
                let i = usize::from(idx);
                assert_eq!(sut.get(i), oracle.get(i));
            }
        }
        assert_eq!(sut.len(), oracle.len());
    }
});
