```python
from collections import deque
from hypothesis import strategies as st
from hypothesis.stateful import RuleBasedStateMachine, invariant, rule
import pytest

TASKS = ["t0", "t1", "t2", "t3", "t4", "t5"]


class DagSchedulerMachine(RuleBasedStateMachine):
    def __init__(self) -> None:
        super().__init__()
        self.sut = DagScheduler()
        self.known: set[str] = set()
        self.prereqs: dict[str, set[str]] = {}
        self.done: set[str] = set()

    def _depends_transitively(self, start: str, goal: str) -> bool:
        q = deque([start])
        seen = {start}
        while q:
            cur = q.popleft()
            if cur == goal:
                return True
            for dep in self.prereqs.get(cur, ())):
                if dep not in seen:
                    seen.add(dep)
                    q.append(dep)
        return False

    @rule(t=st.sampled_from(TASKS))
    def register_task(self, t: str) -> None:
        self.sut.add_task(t)
        self.known.add(t)
        self.prereqs.setdefault(t, set())

    @rule(task=st.sampled_from(TASKS), prereq=st.sampled_from(TASKS))
    def add_dependency(self, task: str, prereq: str) -> None:
        for node in (task, prereq):
            self.register_task(node)
        if task in self.done:
            with pytest.raises(ValueError):
                self.sut.add_dep(task, prereq)
            return

        creates_cycle = self._depends_transitively(prereq, task)
        ok = self.sut.add_dep(task, prereq)
        if creates_cycle:
            assert ok is False
        else:
            assert ok is True
            self.prereqs[task].add(prereq)

    @rule(t=st.sampled_from(TASKS))
    def finish_task(self, t: str) -> None:
        if t not in self.known:
            return
        unmet = self.prereqs[t] - self.done
        if unmet:
            with pytest.raises(ValueError):
                self.sut.mark_done(t)
        else:
            self.sut.mark_done(t)
            self.done.add(t)

    @invariant()
    def ready_tasks_match_oracle(self) -> None:
        expected_ready = {
            t for t in (self.known - self.done) if self.prereqs[t].issubset(self.done)
        }
        assert self.sut.ready_tasks() == expected_ready


TestDagScheduler = DagSchedulerMachine.TestCase
