```ts
import fc from "fast-check";
import { describe, expect, it } from "vitest";
import { MultiTierQuota } from "./multiTierQuota";

interface EventEntry {
  ts: number;
  units: number;
}

interface QuotaModel {
  nowSec: number;
  accepted: EventEntry[];
  limits: { perMin: number; perHour: number; perDay: number };
}

function windowSum(events: EventEntry[], nowSec: number, spanSec: number): number {
  return events
    .filter((e) => nowSec - e.ts < spanSec)
    .reduce((acc, e) => acc + e.units, 0);
}

class AdvanceCmd implements fc.Command<QuotaModel, MultiTierQuota> {
  constructor(readonly deltaSec: number) {}
  check = () => true;
  run(m: QuotaModel): void {
    m.nowSec += this.deltaSec;
  }
  toString = () => `advance(${this.deltaSec}s)`;
}

class ConsumeCmd implements fc.Command<QuotaModel, MultiTierQuota> {
  constructor(readonly units: number) {}
  check = () => true;
  run(m: QuotaModel, r: MultiTierQuota): void {
    const minUsed = windowSum(m.accepted, m.nowSec, 60);
    const hourUsed = windowSum(m.accepted, m.nowSec, 3_600);
    const dayUsed = windowSum(m.accepted, m.nowSec, 86_400);

    const shouldAllow =
      minUsed + this.units <= m.limits.perMin &&
      hourUsed + this.units <= m.limits.perHour &&
      dayUsed + this.units <= m.limits.perDay;

    const got = r.consume(m.nowSec, this.units);
    expect(got).toBe(shouldAllow);
    if (shouldAllow) {
      m.accepted.push({ ts: m.nowSec, units: this.units });
    }
  }
  toString = () => `consume(${this.units})`;
}

describe("MultiTierQuota atomic all-or-nothing invariants", () => {
  it("never leaks partial consumption into shorter windows when a longer window rejects", () => {
    const limits = { perMin: 10, perHour: 25, perDay: 60 };
    const cmdsArb = fc.commands([
      fc.oneof(fc.integer({ min: 0, max: 70 }), fc.integer({ min: 1_800, max: 40_000 })).map((d) => new AdvanceCmd(d)),
      fc.integer({ min: 1, max: 8 }).map((u) => new ConsumeCmd(u)),
    ], { maxCommands: 60 });

    fc.assert(
      fc.property(cmdsArb, (cmds) => {
        fc.modelRun(
          () => ({
            model: { nowSec: 1_000_000, accepted: [], limits },
            real: new MultiTierQuota(limits),
          }),
          cmds
        );
      }),
      { numRuns: 300 }
    );
  });
});
