contract GaugeVoteHandler is Test {
    IGaugeWeightController public immutable ctrl;
    address[] public voters;

    constructor(IGaugeWeightController _ctrl) {
        ctrl = _ctrl;
        voters.push(makeAddr("v1"));
        voters.push(makeAddr("v2"));
        voters.push(makeAddr("v3"));
