use std::collections::HashMap;
use proptest::prelude::*;

pub fn encode_names_fixed(initial_pad: usize, names: &[String]) -> Vec<u8> {
    let mut pkt = vec![0u8; initial_pad];
    let mut suffix_offsets: HashMap<String, usize> = HashMap::new();

    for name in names {
        if name.is_empty() {
            pkt.push(0);
            continue;
        }
        let labels: Vec<&str> = name.split('.').collect();
        let mut compressed = false;
        for i in 0..labels.len() {
            let suffix_key = labels[i..].join(".").to_ascii_lowercase();
            if let Some(&ptr_off) = suffix_offsets.get(&suffix_key) {
                let ptr = 0xC000_u16 | (ptr_off as u16);
                pkt.extend_from_slice(&ptr.to_be_bytes());
                compressed = true;
                break;
            }
            let cur_off = pkt.len();
            if cur_off <= 0x3FFF {
                suffix_offsets.insert(suffix_key, cur_off);
            }
            let lab = labels[i].as_bytes();
            pkt.push(lab.len() as u8);
            pkt.extend_from_slice(lab);
        }
        if !compressed {
            pkt.push(0);
        }
    }
    pkt
}

pub fn decode_all_names_oracle(pkt: &[u8], mut cur: usize, count: usize) -> Vec<String> {
    let mut out = Vec::with_capacity(count);
    for _ in 0..count {
        let mut labels = Vec::new();
        let mut pos = cur;
        let mut jumped = false;
        loop {
            let b = pkt[pos];
            if b == 0 {
                if !jumped { cur = pos + 1; }
                break;
            }
            if (b & 0xC0) == 0xC0 {
                let tgt = (((b & 0x3F) as usize) << 8) | (pkt[pos + 1] as usize);
                assert!(tgt < pos);
                if !jumped { cur = pos + 2; jumped = true; }
                pos = tgt;
            } else {
                let len = b as usize;
                labels.push(std::str::from_utf8(&pkt[pos + 1..pos + 1 + len]).unwrap().to_owned());
                pos += 1 + len;
            }
        }
        out.push(labels.join("."));
    }
    out
}

