use proptest::prelude::*;

pub fn is_leap_buggy(y: i32) -> bool {
    y % 4 == 0
}

pub fn is_leap_gregorian(y: i32) -> bool {
    (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0)
}

pub fn days_in_month(y: i32, m: u8) -> Option<u8> {
    match m {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => Some(31),
        4 | 6 | 9 | 11 => Some(30),
        2 => Some(if is_leap_gregorian(y) { 29 } else { 28 }),
        _ => None,
    }
