import fc from 'fast-check';
import { describe, it, expect } from 'vitest';

export class BuggySingleFlight<V> {
  private store = new Map<string, Promise<V>>();
  getOrLoad(key: string, loader: () => Promise<V>): Promise<V> {
    const existing = this.store.get(key);
    if (existing) return existing;
    const p = loader();
    this.store.set(key, p);
    return p;
  }
}

export class SafeSingleFlight<V> {
  private values = new Map<string, V>();
  private inflight = new Map<string, Promise<V>>();

  async getOrLoad(key: string, loader: () => Promise<V>): Promise<V> {
    if (this.values.has(key)) {
      return this.values.get(key)!;
    }
    const pending = this.inflight.get(key);
    if (pending) {
      return pending;
    }
    const task = (async () => {
      try {
        const val = await loader();
        this.values.set(key, val);
        return val;
      } finally {
        this.inflight.delete(key);
      }
    })();
    this.inflight.set(key, task);
    return task;
  }
}

