    // RED on buggy: second call with healthy loader still rejects with cached stale error!
    await expect(buggy.getOrLoad('jwks', async () => { bugAttempts++; return 'fresh-key'; })).rejects.toThrow('timeout');
    expect(bugAttempts).toBe(1);

