    let fixAttempts = 0;
    const safe = new SafeSingleFlight<string>();
    await expect(safe.getOrLoad('jwks', async () => { fixAttempts++; throw new Error('timeout'); })).rejects.toThrow('timeout');
    await expect(safe.getOrLoad('jwks', async () => { fixAttempts++; return 'fresh-key'; })).resolves.toBe('fresh-key');
    await expect(safe.getOrLoad('jwks', async () => { fixAttempts++; return 'ignored'; })).resolves.toBe('fresh-key');
    expect(fixAttempts).toBe(2);
  });

