pragma solidity ^0.8.24;

import "forge-std/Test.sol";

library MerkleVerifier {
    function _hashPair(bytes32 a, bytes32 b) internal pure returns (bytes32) {
        return a < b ? keccak256(abi.encodePacked(a, b)) : keccak256(abi.encodePacked(b, a));
    }

    function verifySingleHashBuggy(
        bytes32[] calldata proof,
        bytes32 root,
        bytes calldata rawLeafData
    ) internal pure returns (bool) {
        bytes32 computed = keccak256(rawLeafData);
        for (uint256 i = 0; i < proof.length; i++) {
            computed = _hashPair(computed, proof[i]);
        }
        return computed == root;
    }

    function verifyDoubleHashFixed(
        bytes32[] calldata proof,
        bytes32 root,
        bytes calldata rawLeafData
    ) internal pure returns (bool) {
        bytes32 computed = keccak256(bytes.concat(keccak256(rawLeafData)));
        for (uint256 i = 0; i < proof.length; i++) {
            computed = _hashPair(computed, proof[i]);
        }
        return computed == root;
    }
}

contract MerkleWrapper {
    function checkBuggy(bytes32[] calldata p, bytes32 r, bytes calldata d) external pure returns (bool) {
        return MerkleVerifier.verifySingleHashBuggy(p, r, d);
    }
    function checkFixed(bytes32[] calldata p, bytes32 r, bytes calldata d) external pure returns (bool) {
        return MerkleVerifier.verifyDoubleHashFixed(p, r, d);
    }
}

contract MerkleSecondPreimageTest is Test {
    MerkleWrapper w;

    function setUp() public {
        w = new MerkleWrapper();
    }

    function test_RedGreen_SixtyFourByteInternalNodeForgery() public view {
        bytes memory leafAlpha = abi.encodePacked(address(0xA11CE), uint96(100));
        bytes memory leafBeta = abi.encodePacked(address(0xB0B), uint96(200));
        bytes memory leafGamma = abi.encodePacked(address(0xCAFE), uint96(300));

        bytes32 h0 = keccak256(leafAlpha);
        bytes32 h1 = keccak256(leafBeta);
        bytes32 h2 = keccak256(leafGamma);
        bytes32 leftInternal = h0 < h1 ? keccak256(abi.encodePacked(h0, h1)) : keccak256(abi.encodePacked(h1, h0));
        bytes32 buggyRoot = leftInternal < h2
            ? keccak256(abi.encodePacked(leftInternal, h2))
            : keccak256(abi.encodePacked(h2, leftInternal));

        bytes memory forged64 = h0 < h1 ? abi.encodePacked(h0, h1) : abi.encodePacked(h1, h0);
        bytes32[] memory shortProof = new bytes32[](1);
        shortProof[0] = h2;

        // RED on buggy: forged 64-byte internal-node preimage passes verification!
        assertTrue(w.checkBuggy(shortProof, buggyRoot, forged64));

        // GREEN on double-hashed tree: same attack fails completely
        bytes32 dh0 = keccak256(bytes.concat(keccak256(leafAlpha)));
        bytes32 dh1 = keccak256(bytes.concat(keccak256(leafBeta)));
        bytes32 dh2 = keccak256(bytes.concat(keccak256(leafGamma)));
        bytes32 dLeft = dh0 < dh1 ? keccak256(abi.encodePacked(dh0, dh1)) : keccak256(abi.encodePacked(dh1, dh0));
        bytes32 fixedRoot = dLeft < dh2 ? keccak256(abi.encodePacked(dLeft, dh2)) : keccak256(abi.encodePacked(dh2, dLeft));

        bytes memory forgedDouble64 = dh0 < dh1 ? abi.encodePacked(dh0, dh1) : abi.encodePacked(dh1, dh0);
        bytes32[] memory dShortProof = new bytes32[](1);
        dShortProof[0] = dh2;
        assertFalse(w.checkFixed(dShortProof, fixedRoot, forgedDouble64));

        bytes32[] memory validProof = new bytes32[](2);
        validProof[0] = dh1;
        validProof[1] = dh2;
        assertTrue(w.checkFixed(validProof, fixedRoot, leafAlpha));
    }

    function testFuzz_InternalNodeNeverValidatesAsLeaf(bytes32 a, bytes32 b, bytes32 sibling) public view {
        bytes32 internalNode = a < b ? keccak256(abi.encodePacked(a, b)) : keccak256(abi.encodePacked(b, a));
        bytes32 root = internalNode < sibling
            ? keccak256(abi.encodePacked(internalNode, sibling))
            : keccak256(abi.encodePacked(sibling, internalNode));
        bytes memory forged = a < b ? abi.encodePacked(a, b) : abi.encodePacked(b, a);
        bytes32[] memory proof = new bytes32[](1);
        proof[0] = sibling;
        assertFalse(w.checkFixed(proof, root, forged));
    }
}
