// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "forge-std/Test.sol";

contract VestingPool {
    uint256 public immutable totalAllocation;
    uint256 public immutable start;
    uint256 public immutable duration;
    bool public immutable freezeOnRevoke;

    uint256 public claimed;
    uint256 public refunded;
    uint256 public poolBalance;
    bool public revoked;
    uint256 public revokedAt;

    constructor(uint256 _alloc, uint256 _start, uint256 _dur, bool _fix) {
        totalAllocation = _alloc;
        start = _start;
        duration = _dur;
        freezeOnRevoke = _fix;
        poolBalance = _alloc;
    }

    function vestedAmount() public view returns (uint256) {
        uint256 queryTs = (freezeOnRevoke && revoked) ? revokedAt : block.timestamp;
        if (queryTs <= start) return 0;
        uint256 elapsed = queryTs - start;
        if (elapsed >= duration) return totalAllocation;
        return (totalAllocation * elapsed) / duration;
    }

    function claim() external returns (uint256 payout) {
        uint256 vested = vestedAmount();
        payout = vested - claimed;
        claimed += payout;
        poolBalance -= payout;
    }

    function revoke() external returns (uint256 clawback) {
        require(!revoked, "ALREADY_REVOKED");
        uint256 vestedNow = vestedAmount();
        revoked = true;
        revokedAt = block.timestamp;
        clawback = totalAllocation - vestedNow;
        refunded = clawback;
        poolBalance -= clawback;
    }
}

contract VestingHandler is Test {
    VestingPool public vest;
    constructor(VestingPool _v) { vest = _v; }

    function actionWarpAndClaim(uint32 dt) external {
        vm.warp(block.timestamp + bound(uint256(dt), 0, 5_000));
        vest.claim();
    }

    function actionRevoke(uint32 dt) external {
        vm.warp(block.timestamp + bound(uint256(dt), 0, 5_000));
        if (!vest.revoked()) {
            vest.revoke();
        }
    }
}

contract LinearVestingInvariantTest is Test {
    VestingPool buggy;
    VestingPool fixedVest;
    VestingHandler handler;

    function setUp() public {
        vm.warp(1_000);
        buggy = new VestingPool(1_000e18, 1_000, 1_000, false);
        fixedVest = new VestingPool(1_000e18, 1_000, 1_000, true);
        handler = new VestingHandler(fixedVest);
        targetContract(address(handler));
    }

    function test_RedGreen_PostRevokeClaimUnderflowBrick() public {
        vm.warp(1_400);
        buggy.revoke();
        fixedVest.revoke();

        vm.warp(1_800);
        // RED on buggy: vestedAmount() computes 800e18 > poolBalance (400e18), reverting beneficiary's valid claim!
        vm.expectRevert();
        buggy.claim();

        // GREEN on fixed: vestedAmount() stays frozen at 400e18, beneficiary claims exact 400e18 cleanly!
        assertEq(fixedVest.claim(), 400e18);
        assertEq(fixedVest.poolBalance(), 0);
    }

    function invariant_ExactAllocationConservation() public view {
        assertEq(
            fixedVest.claimed() + fixedVest.refunded() + fixedVest.poolBalance(),
            fixedVest.totalAllocation()
        );
        assertGe(fixedVest.poolBalance(), fixedVest.vestedAmount() - fixedVest.claimed());
    }
}
