#include <cassert>
#include <cstddef>
#include <cstdint>
#include <fuzzer/FuzzedDataProvider.h>
#include <limits>

class MonotonicTimestampFilter {
public:
    explicit MonotonicTimestampFilter(int64_t max_forward_jump);
    int64_t observe(int64_t raw_ts);
};

extern "C" int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size) {
    FuzzedDataProvider fdp(data, size);
    int64_t max_jump = fdp.ConsumeIntegralInRange<int64_t>(1, int64_t{1'000'000'000});
    MonotonicTimestampFilter filter(max_jump);

    bool has_prev = false;
    int64_t prev = 0;

    uint32_t count = fdp.ConsumeIntegralInRange<uint32_t>(1, 128);
    for (uint32_t i = 0; i < count && fdp.remaining_bytes() > 0; ++i) {
        int64_t sample = 0;
        uint8_t mode = fdp.ConsumeIntegralInRange<uint8_t>(0, 3);
        if (mode == 0) sample = std::numeric_limits<int64_t>::min();
        else if (mode == 1) sample = std::numeric_limits<int64_t>::max();
        else sample = fdp.ConsumeIntegral<int64_t>();

        int64_t smoothed = filter.observe(sample);
        if (has_prev) {
