use proptest::prelude::*;
use std::collections::HashMap;

// Target API:
// impl RoutingLpmTable {
//     pub fn new() -> Self;
//     pub fn insert(&mut self, addr: u32, prefix_len: u8, nexthop: u32);
//     pub fn lookup(&self, dst: u32) -> Option<u32>;
// }

fn prefix_mask(plen: u8) -> u32 {
    if plen == 0 {
        0
    } else {
        u32::MAX << (32 - plen)
    }
}

fn ref_lpm_lookup(routes: &HashMap<(u32, u8), u32>, dst: u32) -> Option<u32> {
    for plen in (0_u8..=32_u8).rev() {
        let net = dst & prefix_mask(plen);
        if let Some(&nh) = routes.get(&(net, plen)) {
            return Some(nh);
        }
    }
    None
}

