        let mut oracle: HashMap<(u32, u8), u32> = HashMap::new();

        for (raw_ip, plen, nh) in entries {
            sut.insert(raw_ip, plen, nh);
            oracle.insert((raw_ip & prefix_mask(plen), plen), nh);
