from hypothesis import strategies as st
from hypothesis.stateful import RuleBasedStateMachine, initialize, invariant, rule
import pytest

PATHS = ["/etc.cfg", "/data.bin", "/index.db", "/notes.txt"]


class QuotaFsMachine(RuleBasedStateMachine):
    def __init__(self) -> None:
        super().__init__()
        self.quota = 128
        self.fs = None
        self.model: dict[str, bytes] = {}

    @initialize(quota=st.integers(min_value=32, max_value=160))
    def init_fs(self, quota: int) -> None:
        self.quota = quota
        self.fs = QuotaMemFs(quota_bytes=quota)
        self.model.clear()

    @rule(path=st.sampled_from(PATHS), content=st.binary(min_size=0, max_size=96))
    def write_file(self, path: str, content: bytes) -> None:
        old_len = len(self.model.get(path, b""))
        cur_used = sum(len(v) for v in self.model.values())
        projected = cur_used - old_len + len(content)

        if projected > self.quota:
            with pytest.raises(BufferError):
                self.fs.write_file(path, content)
            # Failed overwrite MUST leave previous content untouched!
            assert self.fs.read_file(path) == self.model.get(path)
        else:
            self.fs.write_file(path, content)
            self.model[path] = content

    @rule(path=st.sampled_from(PATHS))
    def unlink_file(self, path: str) -> None:
        removed_sut = self.fs.unlink(path)
        removed_mod = self.model.pop(path, None) is not None
        assert removed_sut == removed_mod

    @invariant()
    def usage_and_contents_match_oracle_within_quota(self) -> None:
        if self.fs is None:
            return
        expected_used = sum(len(v) for v in self.model.values())
        assert self.fs.used_bytes() == expected_used
        assert self.fs.used_bytes() <= self.quota
        for p in PATHS:
            assert self.fs.read_file(p) == self.model.get(p)


TestQuotaMemFs = QuotaFsMachine.TestCase
