import {Test} from "forge-std/Test.sol";
import {StdInvariant} from "forge-std/StdInvariant.sol";
import {IERC20} from "forge-std/interfaces/IERC20.sol";

interface ISubscriptionLedger {
    function treasuryBalance() external view returns (uint256);
    function prepaidOf(address user) external view returns (uint256);
    function pendingChargeOf(address user) external view returns (uint256);
    function depositPrepaid(uint256 amount) external;
    function subscribe(uint256 ratePerSec) external;
    function settle(address user) external returns (uint256 charged);
    function cancelSubscription() external;
}

interface IMintSubToken is IERC20 {
    function mint(address to, uint256 amount) external;
}

contract SubscriptionHandler is Test {
    ISubscriptionLedger public immutable ledger;
    IMintSubToken public immutable token;
    address[] public subscribers;
    uint256 public ghost_totalDeposited;

    constructor(ISubscriptionLedger _ledger, IMintSubToken _token) {
        ledger = _ledger;
        token = _token;
        subscribers.push(makeAddr("sub1"));
        subscribers.push(makeAddr("sub2"));
        subscribers.push(makeAddr("sub3"));
    }

    function subCount() external view returns (uint256) {
        return subscribers.length;
    }

    function topUp(uint256 seed, uint256 amount) external {
        address u = subscribers[seed % subscribers.length];
        amount = bound(amount, 1e6, 50_000 ether);
        token.mint(u, amount);
        vm.startPrank(u);
        token.approve(address(ledger), amount);
        ledger.depositPrepaid(amount);
        vm.stopPrank();
        ghost_totalDeposited += amount;
    }

    function subscribe(uint256 seed, uint256 rate) external {
        address u = subscribers[seed % subscribers.length];
        if (ledger.prepaidOf(u) == 0) return;
        rate = bound(rate, 1, 1 ether);
        vm.prank(u);
        ledger.subscribe(rate);
    }

    function settle(uint256 seed) external {
        address u = subscribers[seed % subscribers.length];
        ledger.settle(u);
    }

    function cancel(uint256 seed) external {
        address u = subscribers[seed % subscribers.length];
        // Must ALWAYS succeed even when elapsed * rate vastly exceeds prepaid balance!
        vm.prank(u);
        ledger.cancelSubscription();
    }

    function warp(uint256 dt) external {
        dt = bound(dt, 1, 60 days);
        vm.warp(block.timestamp + dt);
    }
}

contract SubscriptionLedgerInvariantTest is StdInvariant, Test {
    ISubscriptionLedger internal ledger;
    IMintSubToken internal token;
    SubscriptionHandler internal handler;

    function setUp() public {
        (ledger, token) = deploySubscriptionLedger();
        handler = new SubscriptionHandler(ledger, token);
        targetContract(address(handler));
    }

    function deploySubscriptionLedger() internal virtual returns (ISubscriptionLedger, IMintSubToken);

    function invariant_prepaidPlusTreasuryEqualsDepositedAndChargesCapped() public view {
        uint256 sumPrepaid = 0;
        for (uint256 i = 0; i < handler.subCount(); ++i) {
            address u = handler.subscribers(i);
            uint256 prep = ledger.prepaidOf(u);
            assertLe(ledger.pendingChargeOf(u), prep);
            sumPrepaid += prep;
        }
        uint256 accounted = sumPrepaid + ledger.treasuryBalance();
        assertEq(accounted, handler.ghost_totalDeposited());
        assertEq(token.balanceOf(address(ledger)), accounted);
    }
}
