    IMintTokenPair public immutable collat;
    IMintTokenPair public immutable dai;
    address public immutable keeper;

    mapping(uint256 => uint256) public ghost_initialLot;
    mapping(uint256 => uint256) public ghost_soldLot;
    mapping(uint256 => uint256) public ghost_refundedLot;

