        uint256 maxCost = ((maxSlice * price) / 1e18) + 1e6;
        if (maxCost > tabPre + 1e6) maxCost = tabPre + 1e6;

        uint256 usrPreBal = collat.balanceOf(usr);
        dai.mint(keeper, maxCost);
