        vm.stopPrank();

        ghost_soldLot[id] += taken;
        ghost_refundedLot[id] += (collat.balanceOf(usr) - usrPreBal);
    }

    function warp(uint256 dt) external {
        dt = bound(dt, 10, 2 hours);
        vm.warp(block.timestamp + dt);
