#include <cassert>
#include <cstddef>
#include <cstdint>
#include <fuzzer/FuzzedDataProvider.h>
#include <span>
#include <vector>

struct PgpHeader {
    uint8_t tag = 0; // 1..63
    bool is_partial = false;
    uint64_t body_len = 0;
};

bool parse_openpgp_header(std::span<const uint8_t> buf, PgpHeader& out, size_t& header_bytes);
std::vector<uint8_t> encode_new_format_header(uint8_t tag, uint32_t body_len);

extern "C" int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size) {
    FuzzedDataProvider fdp(data, size);

    if (fdp.ConsumeBool()) {
        std::vector<uint8_t> raw = fdp.ConsumeRemainingBytes<uint8_t>();
        PgpHeader hdr{};
        size_t consumed = 0;
        if (parse_openpgp_header(raw, hdr, consumed)) {
            assert(!raw.empty());
            // RFC 4880 §4.2: bit 7 of first packet tag octet MUST be 1
            assert((raw[0] & 0x80) != 0);
            assert(hdr.tag >= 1 && hdr.tag <= 63);
            assert(consumed >= 2 && consumed <= 6 && consumed <= raw.size());
            if (hdr.is_partial) {
                // Partial body length is 1 << (b & 0x1f) for b in 224..254 => power of two in [1, 2^30]
                assert(hdr.body_len >= 1 && hdr.body_len <= (uint64_t{1} << 30));
                assert((hdr.body_len & (hdr.body_len - 1)) == 0);
            }
        }
    } else {
        uint8_t tag = fdp.ConsumeIntegralInRange<uint8_t>(1, 63);
        uint32_t body_len = fdp.ConsumeIntegral<uint32_t>();
        std::vector<uint8_t> wire = encode_new_format_header(tag, body_len);

        PgpHeader parsed{};
        size_t hdr_sz = 0;
        assert(parse_openpgp_header(wire, parsed, hdr_sz));
        assert(hdr_sz == wire.size());
        assert(parsed.tag == tag);
        assert(!parsed.is_partial);
        assert(parsed.body_len == body_len);
    }
    return 0;
}
