#include <algorithm>
#include <cassert>
#include <cstddef>
#include <cstdint>
#include <fuzzer/FuzzedDataProvider.h>
#include <map>
#include <optional>
#include <utility>
#include <vector>

template <typename K, typename V, size_t Order>
class BPlusTreeMap {
public:
    void upsert(K key, V val);
    bool erase(const K& key);
    std::optional<V> find(const K& key) const;
    std::vector<std::pair<K, V>> range_scan(const K& lo_inc, const K& hi_inc) const;
    size_t size() const;
};

extern "C" int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size) {
    FuzzedDataProvider fdp(data, size);
    BPlusTreeMap<int64_t, int64_t, 4> sut;
    std::map<int64_t, int64_t> oracle;

    uint32_t steps = fdp.ConsumeIntegralInRange<uint32_t>(1, 140);
    for (uint32_t i = 0; i < steps && fdp.remaining_bytes() > 0; ++i) {
        int64_t k = fdp.ConsumeIntegralInRange<int64_t>(-48, 48);
        uint8_t op = fdp.ConsumeIntegralInRange<uint8_t>(0, 2);
        if (op == 0) {
            int64_t v = fdp.ConsumeIntegral<int64_t>();
            sut.upsert(k, v);
            oracle[k] = v;
        } else if (op == 1) {
            bool er_sut = sut.erase(k);
            bool er_mod = oracle.erase(k) > 0;
            assert(er_sut == er_mod);
        } else {
            int64_t k2 = fdp.ConsumeIntegralInRange<int64_t>(-48, 48);
            auto [lo, hi] = std::minmax(k, k2);
            auto got = sut.range_scan(lo, hi);
            std::vector<std::pair<int64_t, int64_t>> want;
            for (auto it = oracle.lower_bound(lo); it != oracle.end() && it->first <= hi; ++it) {
                want.emplace_back(it->first, it->second);
            }
            assert(got == want);
        }
        assert(sut.size() == oracle.size());
        auto hit = sut.find(k);
        auto it = oracle.find(k);
        if (it == oracle.end()) assert(!hit.has_value());
        else assert(hit.has_value() && *hit == it->second);
    }
    return 0;
}
