std::vector<uint8_t> slip_encode_frame(std::span<const uint8_t> payload);

class SlipFrameDecoder {
public:
    explicit SlipFrameDecoder(size_t max_mtu);
    void feed(std::span<const uint8_t> chunk, std::vector<std::vector<uint8_t>>& out_frames);
