        SlipFrameDecoder dec(256);
        std::vector<std::vector<uint8_t>> got;
        size_t off = 0;
        while (off < wire.size()) {
            size_t step = std::min(wire.size() - off, fdp.ConsumeIntegralInRange<size_t>(1, 7));
            dec.feed({wire.data() + off, step}, got);
            off += step;
