use proptest::prelude::*;
use std::collections::BTreeSet;

fn arb_sparse_bit() -> impl Strategy<Value = u32> {
    prop_oneof![
        0_u32..=128_u32,
        4090_u32..=4102_u32,
        (u32::MAX - 64)..=u32::MAX,
        any::<u32>(),
    ]
