from hypothesis.stateful import RuleBasedStateMachine, invariant, rule

KEYS = ["db-shard-0", "db-shard-1"]
OWNERS = ["worker-a", "worker-b", "worker-c"]


class LeaseLockMachine(RuleBasedStateMachine):
    def __init__(self) -> None:
        super().__init__()
        self.now = 500.0
        self.sut = LeaseLockManager(clock=lambda: self.now)
        # key -> (owner, token, expires_at)
        self.active: dict[str, tuple[str, int, float]] = {}
        self.highest_token_seen = 0
        self.stale_tokens: list[tuple[str, str, int]] = []

    def _expire_model(self) -> None:
