            assert self.sut.renew(key, old_owner, old_tok, ttl) is False
            assert self.sut.release(key, old_owner, old_tok) is False

    @rule(key=st.sampled_from(KEYS))
    def release_current_lock(self, key: str) -> None:
        self._expire_model()
        if key not in self.active:
            return
        owner, tok, _ = self.active.pop(key)
        assert self.sut.release(key, owner, tok) is True
        self.stale_tokens.append((key, owner, tok))

