use proptest::prelude::*;

#[derive(Debug, PartialEq, Eq)]
pub enum MsgPackErr {
    Truncated,
    TrailingBytes,
    DepthExceeded,
    UnsupportedTag,
}

pub fn validate_msgpack_iterative(buf: &[u8], max_depth: usize) -> Result<(), MsgPackErr> {
    if buf.is_empty() {
        return Err(MsgPackErr::Truncated);
    }
    let mut pending: Vec<usize> = vec![1];
    let mut pos = 0;

    while let Some(top) = pending.last_mut() {
        if *top == 0 {
            pending.pop();
            continue;
        }
        *top -= 1;
        if pos >= buf.len() {
            return Err(MsgPackErr::Truncated);
        }
        let tag = buf[pos];
        pos += 1;
        match tag {
            0x00..=0x7F | 0xC0 | 0xC2 | 0xC3 | 0xE0..=0xFF => {}
            0xCC | 0xD0 => {
                if pos + 1 > buf.len() { return Err(MsgPackErr::Truncated); }
                pos += 1;
            }
            0xA0..=0xBF => {
                let slen = (tag & 0x1F) as usize;
                if pos + slen > buf.len() { return Err(MsgPackErr::Truncated); }
                pos += slen;
            }
            0x90..=0x9F => {
                let count = (tag & 0x0F) as usize;
                if pending.len() > max_depth {
                    return Err(MsgPackErr::DepthExceeded);
                }
                pending.push(count);
            }
            0x80..=0x8F => {
                let pairs = (tag & 0x0F) as usize;
                if pending.len() > max_depth {
                    return Err(MsgPackErr::DepthExceeded);
                }
                pending.push(pairs * 2);
            }
            _ => return Err(MsgPackErr::UnsupportedTag),
        }
    }

    if pos != buf.len() {
        return Err(MsgPackErr::TrailingBytes);
    }
    Ok(())
}

