        assert_eq!(validate_msgpack_iterative(&[0x81, 0x01], 4), Err(MsgPackErr::Truncated));

        let mut bomb = vec![0x91_u8; 5000];
        bomb.push(0x00);
        assert_eq!(validate_msgpack_iterative(&bomb, 32), Err(MsgPackErr::DepthExceeded));

        let mut exact_two = vec![0x91, 0x91, 0x07];
        assert_eq!(validate_msgpack_iterative(&exact_two, 2), Ok(()));
        assert_eq!(validate_msgpack_iterative(&exact_two, 1), Err(MsgPackErr::DepthExceeded));
        exact_two.push(0x00);
