use proptest::prelude::*;
use std::collections::BTreeMap;

#[derive(Debug, Clone)]
enum HeapAction {
    InsertOrDecrease { id: usize, dist: u64 },
    PopMin,
}

fn arb_action(max_ids: usize) -> impl Strategy<Value = HeapAction> {
    prop_oneof![
        3 => (0_usize..max_ids, 0_u64..1000_u64)
            .prop_map(|(id, dist)| HeapAction::InsertOrDecrease { id, dist }),
        1 => Just(HeapAction::PopMin),
    ]
}

proptest! {
    #[test]
    fn indexed_min_heap_preserves_bijection_and_min_order(
        actions in prop::collection::vec(arb_action(24), 1..=120)
    ) {
        let mut sut = IndexedMinHeap::with_max_ids(24);
        let mut oracle: BTreeMap<usize, u64> = BTreeMap::new();

        for act in actions {
            match act {
                HeapAction::InsertOrDecrease { id, dist } => {
                    let updated = sut.insert_or_decrease(id, dist);
                    let should_update = oracle.get(&id).map_or(true, |&old| dist < old);
                    prop_assert_eq!(updated, should_update);
                    if should_update {
                        oracle.insert(id, dist);
                    }
                }
                HeapAction::PopMin => {
                    let got = sut.pop_min();
                    if oracle.is_empty() {
                        prop_assert_eq!(got, None);
                    } else {
                        let min_dist = *oracle.values().min().unwrap();
                        let (got_id, got_dist) = got.expect("non-empty heap must pop");
                        prop_assert_eq!(got_dist, min_dist);
                        prop_assert_eq!(oracle.remove(&got_id), Some(min_dist));
                    }
                }
            }
            prop_assert!(sut.check_heap_invariants());
            for id in 0..24 {
                prop_assert_eq!(sut.peek_dist(id), oracle.get(&id).copied());
            }
        }
    }
}
