from hypothesis import strategies as st
from hypothesis.stateful import RuleBasedStateMachine, invariant, precondition, rule


class MerkleAuditLogMachine(RuleBasedStateMachine):
    def __init__(self) -> None:
        super().__init__()
        self.log = MerkleAuditLog()
        self.entries: list[bytes] = []
        self.roots_by_size: dict[int, bytes] = {}

    @rule(payload=st.binary(min_size=0, max_size=64))
    def append_leaf(self, payload: bytes) -> None:
        idx = self.log.append(payload)
        assert idx == len(self.entries)
        self.entries.append(payload)
        sz = len(self.entries)
        self.roots_by_size[sz] = self.log.root_at(sz)

    @precondition(lambda self: len(self.entries) >= 1)
    @rule(idx_seed=st.integers(min_value=0, max_value=200), sz_seed=st.integers(min_value=0, max_value=200))
    def check_inclusion_proof(self, idx_seed: int, sz_seed: int) -> None:
        sz = 1 + (sz_seed % len(self.entries))
        idx = idx_seed % sz
        root = self.roots_by_size[sz]
        proof = self.log.prove_inclusion(idx, sz)
        assert self.log.verify_inclusion(idx, sz, self.entries[idx], root, proof) is True
        # Tampered leaf payload must fail verification
        assert self.log.verify_inclusion(idx, sz, self.entries[idx] + b"!", root, proof) is False

