import fc from "fast-check";
import { describe, expect, it } from "vitest";
import { LwwSet } from "./lwwSet";

const opListArb = fc.array(
  fc.record({
    kind: fc.constantFrom("add" as const, "remove" as const),
    item: fc.constantFrom("k1", "k2", "k3", "k4"),
    // Small timestamp range [1..6] intentionally forces frequent concurrent equal-ts ties!
    ts: fc.integer({ min: 1, max: 6 }),
  }),
  { maxLength: 16 }
);

function buildReplica(ops: Array<{ kind: "add" | "remove"; item: string; ts: number }>): LwwSet {
  const s = new LwwSet();
  for (const op of ops) {
    if (op.kind === "add") s.add(op.item, op.ts);
    else s.remove(op.item, op.ts);
  }
  return s;
}

describe("CRDT LwwSet join-semilattice algebraic laws", () => {
  it("satisfies idempotence, commutativity, associativity, and add-wins tie-breaking", () => {
