      fc.property(opListArb, opListArb, opListArb, (opsA, opsB, opsC) => {
        const a = buildReplica(opsA);
        const b = buildReplica(opsB);
        const c = buildReplica(opsC);

        // 1. Idempotence: A ⊔ A == A
        expect(a.merge(a).elements().sort()).toEqual(a.elements().sort());

        // 2. Commutativity: A ⊔ B == B ⊔ A (catches arrival-order tie bugs on equal timestamps!)
        const ab = a.merge(b);
        const ba = b.merge(a);
        expect(ab.elements().sort()).toEqual(ba.elements().sort());

        // 3. Associativity: (A ⊔ B) ⊔ C == A ⊔ (B ⊔ C)
        const leftAssoc = a.merge(b).merge(c);
        const rightAssoc = a.merge(b.merge(c));
        expect(leftAssoc.elements().sort()).toEqual(rightAssoc.elements().sort());
      }),
      { numRuns: 600 }
    );
  });
});
