        if (st != IDisputeBondEscrow.GameStatus.Open) return;
        if (block.timestamp >= created + escrow.CHALLENGE_WINDOW()) return;

        address c = actors[actorSeed % actors.length];
        uint256 bond = escrow.BOND_SIZE();
        vm.deal(c, bond);
        vm.prank(c);
        escrow.challenge{value: bond}(id);
        ghost_bondsPosted += bond;
    }

    function finalizeUnchallenged(uint256 idSeed) external {
        uint256 n = escrow.gameCount();
        if (n == 0) return;
        uint256 id = idSeed % n;
        (, , uint64 created, IDisputeBondEscrow.GameStatus st) = escrow.games(id);
        if (st != IDisputeBondEscrow.GameStatus.Open) return;
        if (block.timestamp < created + escrow.CHALLENGE_WINDOW()) {
            vm.expectRevert();
            escrow.resolveUnchallenged(id);
            return;
