        if (n == 0) return;
        uint256 id = idSeed % n;
        (, , , IDisputeBondEscrow.GameStatus st) = escrow.games(id);
        if (st != IDisputeBondEscrow.GameStatus.Challenged) return;

        vm.prank(oracleJudge);
        escrow.adjudicateDispute(id, challengerWon);
    }

    function withdraw(uint256 seed) external {
        address a = actors[seed % actors.length];
        if (escrow.claimableOf(a) == 0) return;
        vm.prank(a);
        ghost_bondsWithdrawn += escrow.withdrawBonds();
