        for (uint256 id = 0; id < n; ++id) {
            (, , , IDisputeBondEscrow.GameStatus st) = escrow.games(id);
            if (st == IDisputeBondEscrow.GameStatus.Open) lockedInGames += bond;
            else if (st == IDisputeBondEscrow.GameStatus.Challenged) lockedInGames += 2 * bond;
        }

        uint256 sumClaimable = 0;
        for (uint256 i = 0; i < handler.actorCount(); ++i) {
            sumClaimable += escrow.claimableOf(handler.actors(i));
        }

        assertEq(address(escrow).balance, lockedInGames + sumClaimable);
        assertEq(address(escrow).balance + handler.ghost_bondsWithdrawn(), handler.ghost_bondsPosted());
    }
}
