#include <cassert>
#include <cstddef>
#include <cstdint>
#include <optional>
#include <vector>

std::optional<uint64_t> decode_der_buggy(const uint8_t* p, size_t n) {
    if (n < 3 || p[0] != 0x02) return std::nullopt;
    size_t len = p[1];
    size_t idx = 2;
    if (len == 0x81 && n >= 4) { len = p[2]; idx = 3; }
    if (len == 0 || len > 9 || idx + len != n) return std::nullopt;
    uint64_t v = 0;
    for (size_t i = 0; i < len; ++i) v = (v << 8) | p[idx + i];
    return v;
}

std::vector<uint8_t> encode_der_u64_canonical(uint64_t v) {
    std::vector<uint8_t> body;
    if (v == 0) {
        body.push_back(0x00);
    } else {
        uint64_t tmp = v;
        while (tmp > 0) {
            body.insert(body.begin(), static_cast<uint8_t>(tmp & 0xFF));
            tmp >>= 8;
        }
        if ((body[0] & 0x80) != 0) {
            body.insert(body.begin(), 0x00);
        }
    }
    std::vector<uint8_t> out = {0x02, static_cast<uint8_t>(body.size())};
    out.insert(out.end(), body.begin(), body.end());
    return out;
}

std::optional<uint64_t> decode_der_u64_strict(const uint8_t* p, size_t n) {
    if (n < 3 || p[0] != 0x02) return std::nullopt;
    uint8_t len = p[1];
    if (len < 1 || len > 9 || static_cast<size_t>(2 + len) != n) return std::nullopt;
    const uint8_t* body = p + 2;
    if ((body[0] & 0x80) != 0) return std::nullopt;
    if (len > 1 && body[0] == 0x00 && (body[1] & 0x80) == 0) {
        return std::nullopt;
    }
    uint64_t val = 0;
    for (uint8_t i = 0; i < len; ++i) {
        if (i == 0 && len == 9 && body[0] != 0x00) return std::nullopt;
        val = (val << 8) | body[i];
    }
    return val;
}

void red_green_der_malleability_proof() {
    const uint8_t kLongLen[] = {0x02, 0x81, 0x01, 0x05};
    const uint8_t kRedundantZero[] = {0x02, 0x02, 0x00, 0x7F};
    const uint8_t kNegativeOneByte[] = {0x02, 0x01, 0x80};
