pub fn find_crlf_buggy(buf: &[u8]) -> Option<usize> {
    let mut base = 0;
    for chunk in buf.chunks_exact(8) {
        if let Some(rel) = chunk.windows(2).position(|w| w == b"\r\n") {
            return Some(base + rel);
