            _, exp_k = heapq.heappop(self.heap)
            self.store.pop(exp_k, None)
        rec = self.store.get(k)
        return rec[0] if (rec and rec[1] > now) else None

class FixedTTLCache:
    def __init__(self):
        self.seq = 0
        self.store: dict[str, tuple[int, int, int]] = {}
        self.heap: list[tuple[int, int, str]] = []

    def put(self, k: str, v: int, now: int, ttl: int) -> None:
        if ttl <= 0:
            self.store.pop(k, None)
            return
        self.seq += 1
        exp = now + ttl
        self.store[k] = (v, exp, self.seq)
        heapq.heappush(self.heap, (exp, self.seq, k))

    def get(self, k: str, now: int) -> int | None:
        while self.heap and self.heap[0][0] <= now:
            _, gen, exp_k = heapq.heappop(self.heap)
            cur = self.store.get(exp_k)
            if cur is not None and cur[2] == gen:
                del self.store[exp_k]
        rec = self.store.get(k)
        if rec is None or rec[1] <= now:
            return None
        return rec[0]

def test_red_green_stale_heap_tombstone_deletes_live_key():
    buggy = BuggyTTLCache()
    fixed = FixedTTLCache()
    buggy.put("session", 1, now=0, ttl=10)
    buggy.put("session", 2, now=5, ttl=100)
    fixed.put("session", 1, now=0, ttl=10)
    fixed.put("session", 2, now=5, ttl=100)

    # RED on buggy: pops (10, 'session') at t=12 and wipes the live refreshed value!
    assert buggy.get("session", now=12) is None
    # GREEN on fixed: generation mismatch ignores stale heap entry, returns 2!
    assert fixed.get("session", now=12) == 2
    assert fixed.get("session", now=105) is None

class TTLCacheStateMachine(RuleBasedStateMachine):
    def __init__(self):
        super().__init__()
        self.now = 0
        self.sut = FixedTTLCache()
        self.oracle: dict[str, tuple[int, int]] = {}

    @rule(k=st.sampled_from(["a", "b", "c"]), v=st.integers(1, 999), ttl=st.integers(0, 20))
    def op_put(self, k: str, v: int, ttl: int):
        self.sut.put(k, v, self.now, ttl)
        if ttl <= 0:
            self.oracle.pop(k, None)
        else:
            self.oracle[k] = (v, self.now + ttl)

    @rule(dt=st.integers(0, 10))
    def op_tick(self, dt: int):
        self.now += dt

    @rule(k=st.sampled_from(["a", "b", "c", "missing"]))
    def op_assert_get(self, k: str):
        rec = self.oracle.get(k)
        expected = rec[0] if (rec is not None and rec[1] > self.now) else None
        assert self.sut.get(k, self.now) == expected

def test_stateful_ttl_cache():
    run_state_machine_as_test(TTLCacheStateMachine, settings=settings(max_examples=50, stateful_step_count=25))
