export function parseCookieBuggy(raw: string): Record<string, string> {
  const out: Record<string, string> = {};
  for (const part of raw.split(';')) {
    const [k, v] = part.trim().split('=');
    if (k && v !== undefined) {
      out[k] = decodeURIComponent(v);
