import fc from 'fast-check';
import { describe, it, expect } from 'vitest';

const SAFE_KID_RE = /^[A-Za-z0-9_-]{1,64}$/;

export function validateHeaderBuggy(hdr: Record<string, unknown>): boolean {
  return typeof hdr.alg === 'string' && hdr.alg !== 'none';
}

export function validateJwsProtectedHeader(
  hdr: unknown,
  allowedAlgs: ReadonlySet<string>,
  knownCrit: ReadonlySet<string>
): { alg: string; kid: string } {
  if (typeof hdr !== 'object' || hdr === null || Array.isArray(hdr)) {
    throw new Error('Header must be JSON object');
  }
  const rec = hdr as Record<string, unknown>;
  const alg = rec['alg'];
  if (typeof alg !== 'string' || alg.toLowerCase() === 'none' || !allowedAlgs.has(alg)) {
    throw new Error('Disallowed JWS alg');
  }
  const kid = rec['kid'];
  if (typeof kid !== 'string' || !SAFE_KID_RE.test(kid)) {
    throw new Error('Invalid or unsafe kid');
  }
  if ('jku' in rec || 'jwk' in rec || 'x5u' in rec) {
    throw new Error('Embedded key headers forbidden');
  }
  if ('crit' in rec) {
    const crit = rec['crit'];
    if (!Array.isArray(crit) || crit.length === 0) {
      throw new Error('Invalid empty or non-array crit');
    }
    const seen = new Set<string>();
    for (const ext of crit) {
      if (typeof ext !== 'string' || ext.length === 0 || seen.has(ext)) {
        throw new Error('Malformed or duplicate crit entry');
      }
      if (!knownCrit.has(ext) || !Object.prototype.hasOwnProperty.call(rec, ext)) {
        throw new Error(`Unsupported or missing critical extension: ${ext}`);
      }
      seen.add(ext);
    }
  }
  return { alg, kid };
}

