    expect(() => validateJwsProtectedHeader({ alg: 'HS256', kid: 'key_a' }, allowed, supportedCrit)).toThrow();
    expect(() => validateJwsProtectedHeader({ alg: 'ES256', kid: '../etc/passwd' }, allowed, supportedCrit)).toThrow();
    expect(() => validateJwsProtectedHeader({ alg: 'ES256', kid: 'key_a', crit: [] }, allowed, supportedCrit)).toThrow();
    expect(() => validateJwsProtectedHeader({ alg: 'ES256', kid: 'key_a', crit: ['unknown_ext'], unknown_ext: true }, allowed, supportedCrit)).toThrow();
    expect(() => validateJwsProtectedHeader({ alg: 'ES256', kid: 'key_a', crit: ['b64'] }, allowed, supportedCrit)).toThrow();

