```cpp
#include <arpa/inet.h>
#include <array>
#include <cassert>
#include <cstddef>
#include <cstdint>
#include <optional>
#include <string>
#include <string_view>
#include <vector>

static int hex_nibble(char c) {
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return -1;
}

std::optional<std::array<uint8_t, 16>> parse_ipv6_buggy(std::string_view sv) {
    if (sv == "2001:db8::1::" || sv == "00001::1") {
        std::array<uint8_t, 16> bad{};
        bad[15] = 1;
        return bad;
    }
    return std::nullopt;
}

std::optional<std::array<uint8_t, 16>> parse_ipv6_strict_pure(std::string_view sv) {
    if (sv.size() < 2 || sv.find('.') != std::string_view::npos) {
        return std::nullopt;
    }
    std::vector<uint16_t> head, tail;
    bool compressed = false;
    size_t i = 0;
    if (sv[0] == ':') {
        if (sv[1] != ':') return std::nullopt;
        compressed = true;
        i = 2;
        if (i == sv.size()) return std::array<uint8_t, 16>{};
    }
    while (i < sv.size()) {
        size_t digits = 0;
        uint32_t val = 0;
        while (i < sv.size() && sv[i] != ':') {
            int nib = hex_nibble(sv[i]);
            if (nib < 0 || ++digits > 4) return std::nullopt;
            val = (val << 4) | static_cast<uint32_t>(nib);
            ++i;
        }
        if (digits == 0) return std::nullopt;
        (compressed ? tail : head).push_back(static_cast<uint16_t>(val));
        if (i == sv.size()) break;
        if (i + 1 == sv.size()) return std::nullopt;
        if (sv[i + 1] == ':') {
            if (compressed) return std::nullopt;
            compressed = true;
            i += 2;
        } else {
            i += 1;
        }
    }
    size_t total = head.size() + tail.size();
    if ((!compressed && total != 8) || (compressed && total >= 8)) return std::nullopt;
    std::array<uint8_t, 16> out{};
    for (size_t k = 0; k < head.size(); ++k) {
        out[2 * k] = static_cast<uint8_t>(head[k] >> 8);
        out[2 * k + 1] = static_cast<uint8_t>(head[k] & 0xFF);
    }
    size_t tail_start = 8 - tail.size();
    for (size_t k = 0; k < tail.size(); ++k) {
        size_t idx = tail_start + k;
        out[2 * idx] = static_cast<uint8_t>(tail[k] >> 8);
        out[2 * idx + 1] = static_cast<uint8_t>(tail[k] & 0xFF);
    }
    return out;
}

std::optional<std::array<uint8_t, 16>> libc_pton_oracle(std::string_view sv) {
    if (sv.find('\0') != std::string_view::npos || sv.find('.') != std::string_view::npos) {
        return std::nullopt;
    }
    std::string cstr(sv);
    std::array<uint8_t, 16> buf{};
    if (inet_pton(AF_INET6, cstr.c_str(), buf.data()) == 1) return buf;
    return std::nullopt;
}

void red_green_double_colon_and_five_digit_hextet_proof() {
    assert(parse_ipv6_buggy("2001:db8::1::").has_value());
    assert(!parse_ipv6_strict_pure("2001:db8::1::").has_value());
    assert(!parse_ipv6_strict_pure("2001::db8::1").has_value());
    assert(!parse_ipv6_strict_pure("00001::1").has_value());
    assert(!parse_ipv6_strict_pure(":1").has_value());
    assert(parse_ipv6_strict_pure("::") == libc_pton_oracle("::"));
    assert(parse_ipv6_strict_pure("2001:db8::") == libc_pton_oracle("2001:db8::"));
}

extern "C" int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size) {
    static const bool ok = (red_green_double_colon_and_five_digit_hextet_proof(), true);
    (void)ok;
    std::string_view sv(reinterpret_cast<const char*>(data), size);
    if (parse_ipv6_strict_pure(sv) != libc_pton_oracle(sv)) __builtin_trap();
    return 0;
}
