```cpp
#include <cassert>
#include <cstddef>
#include <cstdint>
#include <deque>
#include <optional>
#include <vector>
#include <fuzzer/FuzzedDataProvider.h>

class RingFrameQueue {
public:
    explicit RingFrameQueue(size_t cap, bool fix_wrap = true)
        : buf_(cap, 0xAA), cap_(cap), fix_(fix_wrap) {}

    bool push_frame(const uint8_t* payload, uint16_t len) {
        size_t needed = 2 + static_cast<size_t>(len);
        if (needed > cap_ - used_) return false;
        write_byte(static_cast<uint8_t>(len >> 8));
        write_byte(static_cast<uint8_t>(len & 0xFF));
        for (uint16_t i = 0; i < len; ++i) write_byte(payload[i]);
        return true;
    }

    std::optional<std::vector<uint8_t>> pop_frame() {
        if (used_ < 2) return std::nullopt;
        uint8_t hi = buf_[rpos_];
        uint8_t lo = fix_ ? buf_[(rpos_ + 1) % cap_] : ((rpos_ + 1 < cap_) ? buf_[rpos_ + 1] : 0xFF);
        uint16_t len = static_cast<uint16_t>((static_cast<uint16_t>(hi) << 8) | lo);
        if (used_ < 2 + static_cast<size_t>(len)) return std::nullopt;
        advance_read(2);
        std::vector<uint8_t> out(len);
        for (uint16_t i = 0; i < len; ++i) {
            out[i] = buf_[rpos_];
            advance_read(1);
        }
        return out;
    }

private:
    void write_byte(uint8_t b) {
        buf_[wpos_] = b;
        wpos_ = (wpos_ + 1) % cap_;
        ++used_;
    }
    void advance_read(size_t n) {
        rpos_ = (rpos_ + n) % cap_;
        used_ -= n;
    }
    std::vector<uint8_t> buf_;
    size_t cap_;
    size_t rpos_ = 0;
    size_t wpos_ = 0;
    size_t used_ = 0;
    bool fix_;
};

void red_green_header_wraparound_straddle_proof() {
    const uint8_t kFive[5] = {1, 2, 3, 4, 5};
    const uint8_t kTwo[2] = {9, 8};

    RingFrameQueue buggy(8, false);
    assert(buggy.push_frame(kFive, 5));
    assert(buggy.pop_frame().has_value());
    assert(buggy.push_frame(kTwo, 2));
    assert(!buggy.pop_frame().has_value());

    RingFrameQueue fixed(8, true);
    assert(fixed.push_frame(kFive, 5));
    assert(fixed.pop_frame().has_value());
    assert(fixed.push_frame(kTwo, 2));
    auto got = fixed.pop_frame();
    assert(got.has_value() && got->size() == 2 && (*got)[0] == 9 && (*got)[1] == 8);
}

extern "C" int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size) {
    static const bool ok = (red_green_header_wraparound_straddle_proof(), true);
    (void)ok;
    FuzzedDataProvider fdp(data, size);
    size_t cap = fdp.ConsumeIntegralInRange<size_t>(4, 32);
    RingFrameQueue sut(cap, true);
    std::deque<std::vector<uint8_t>> model;
    size_t model_bytes = 0;

    while (fdp.remaining_bytes() > 0) {
        if (fdp.ConsumeBool()) {
            auto payload = fdp.ConsumeBytes<uint8_t>(fdp.ConsumeIntegralInRange<size_t>(0, 16));
            bool pushed = sut.push_frame(payload.data(), static_cast<uint16_t>(payload.size()));
            bool should_fit = (2 + payload.size() <= cap - model_bytes);
            if (pushed != should_fit) __builtin_trap();
            if (pushed) {
                model_bytes += 2 + payload.size();
                model.push_back(payload);
            }
        } else {
            auto popped = sut.pop_frame();
            if (model.empty()) {
                if (popped.has_value()) __builtin_trap();
            } else {
                if (!popped.has_value() || *popped != model.front()) __builtin_trap();
                model_bytes -= (2 + model.front().size());
                model.pop_front();
            }
        }
    }
    return 0;
}
