use std::path::{Component, Path, PathBuf};
use proptest::prelude::*;

#[derive(Debug, PartialEq, Eq)]
pub enum JailErr {
    ForbiddenByte,
    AbsoluteOrRooted,
    EscapesJail,
    EmptyTarget,
}

pub fn check_jail_buggy(jail: &str, candidate_full: &str) -> bool {
    candidate_full.starts_with(jail)
}

pub fn resolve_jailed_path(jail_root: &Path, untrusted_rel: &str) -> Result<PathBuf, JailErr> {
    if untrusted_rel.is_empty() {
        return Err(JailErr::EmptyTarget);
    }
    if untrusted_rel.contains('\0') || untrusted_rel.contains('\\') {
        return Err(JailErr::ForbiddenByte);
    }
    let rel_path = Path::new(untrusted_rel);
    let mut rel_stack: Vec<&std::ffi::OsStr> = Vec::new();

    for comp in rel_path.components() {
        match comp {
            Component::CurDir => {}
            Component::Normal(seg) => rel_stack.push(seg),
            Component::ParentDir => {
                if rel_stack.pop().is_none() {
                    return Err(JailErr::EscapesJail);
                }
            }
            Component::RootDir | Component::Prefix(_) => {
                return Err(JailErr::AbsoluteOrRooted);
            }
        }
    }
    if rel_stack.is_empty() {
        return Err(JailErr::EmptyTarget);
    }
    let mut out = jail_root.to_path_buf();
    for seg in rel_stack {
        out.push(seg);
    }
    Ok(out)
}

