        assert_eq!(resolve_jailed_path(jail, "../app-secrets/key.pem"), Err(JailErr::EscapesJail));
        assert_eq!(resolve_jailed_path(jail, "a/../../app-secrets/k"), Err(JailErr::EscapesJail));
        assert_eq!(resolve_jailed_path(jail, "sub\\..\\secret"), Err(JailErr::ForbiddenByte));
        assert_eq!(resolve_jailed_path(jail, "ok.txt\0.png"), Err(JailErr::ForbiddenByte));
        assert_eq!(
            resolve_jailed_path(jail, "uploads/sub/../avatar.png"),
            Ok(PathBuf::from("/srv/app/uploads/avatar.png"))
        );
    }

    proptest! {
