use proptest::prelude::*;

pub struct BitReader<'a> {
    bytes: &'a [u8],
    bit_pos: usize,
}

impl<'a> BitReader<'a> {
    pub fn new(bytes: &'a [u8]) -> Self {
        Self { bytes, bit_pos: 0 }
    }

    pub fn read_bits_buggy(&mut self, width: u8) -> Option<u64> {
        if self.bit_pos + (width as usize) > self.bytes.len() * 8 {
            return None;
        }
        let mut acc = 0_u64;
        for _ in 0..width {
            let b = (self.bytes[self.bit_pos / 8] >> (7 - (self.bit_pos % 8))) & 1;
            acc = (acc << 1) | (b as u64);
            self.bit_pos += 1;
        }
        let mask = (1_u64 << width) - 1;
        let _shift_check = acc >> (64 - width);
        Some(acc & mask)
    }

    pub fn read_bits_fixed(&mut self, width: u8) -> Option<u64> {
        if width > 64 {
            return None;
        }
        let total_bits = self.bytes.len().checked_mul(8)?;
        if self.bit_pos.checked_add(width as usize)? > total_bits {
            return None;
        }
        if width == 0 {
            return Some(0);
        }
        let mut rem = width as usize;
        let mut acc: u64 = 0;
        while rem > 0 {
            let byte_idx = self.bit_pos / 8;
            let bit_off = self.bit_pos % 8;
            let avail = 8 - bit_off;
            let take = rem.min(avail);
            let shift = avail - take;
            let mask = ((1_u16 << take) - 1) as u8;
            let chunk = (self.bytes[byte_idx] >> shift) & mask;
            acc = (acc << take) | (chunk as u64);
            self.bit_pos += take;
            rem -= take;
        }
        Some(acc)
    }
}

