import pytest
from hypothesis import given, strategies as st

INT64_MIN = -(1 << 63)
INT64_MAX = (1 << 63) - 1
MASK64 = 0xFFFFFFFFFFFFFFFF

def encode_int64_varint_buggy(n: int, max_iters: int = 20) -> bytes:
    out = bytearray()
    steps = 0
    while n > 0x7F or n < 0:
        out.append((n & 0x7F) | 0x80)
        n >>= 7
        steps += 1
        if steps >= max_iters:
            raise RuntimeError("infinite sign-extension loop")
    out.append(n & 0x7F)
    return bytes(out)

def encode_int64_varint_fixed(n: int) -> bytes:
    if isinstance(n, bool) or not (INT64_MIN <= n <= INT64_MAX):
        raise OverflowError("int64 out of bounds")
    u = n & MASK64
    out = bytearray()
    while u > 0x7F:
        out.append((u & 0x7F) | 0x80)
        u >>= 7
    out.append(u)
    return bytes(out)

def decode_int64_varint_fixed(buf: bytes) -> int:
    u = 0
    for i, b in enumerate(buf):
        if i == 9 and b > 0x01:
            raise ValueError("varint64 overflow on tenth byte")
        if i >= 10:
            raise ValueError("varint64 exceeds 10 bytes")
        u |= (b & 0x7F) << (i * 7)
        if (b & 0x80) == 0:
            if i != len(buf) - 1:
                raise ValueError("trailing bytes")
            return u - (1 << 64) if (u & (1 << 63)) else u
    raise ValueError("truncated varint64")

def encode_sint64_zigzag(n: int) -> bytes:
    if isinstance(n, bool) or not (INT64_MIN <= n <= INT64_MAX):
        raise OverflowError("sint64 out of bounds")
    zz = ((n << 1) ^ (n >> 63)) & MASK64
    out = bytearray()
    while zz > 0x7F:
        out.append((zz & 0x7F) | 0x80)
        zz >>= 7
    out.append(zz)
    return bytes(out)

def decode_sint64_zigzag(buf: bytes) -> int:
    u = 0
    for i, b in enumerate(buf):
        if i == 9 and b > 0x01:
            raise ValueError("sint64 overflow")
        if i >= 10:
            raise ValueError("sint64 too long")
        u |= (b & 0x7F) << (i * 7)
        if (b & 0x80) == 0:
            if i != len(buf) - 1:
                raise ValueError("trailing bytes")
            return (u >> 1) ^ -(u & 1)
    raise ValueError("truncated sint64")

def test_red_green_negative_sign_extension_and_bounds():
    with pytest.raises(RuntimeError, match="infinite"):
        encode_int64_varint_buggy(-1)

    wire_neg = encode_int64_varint_fixed(-1)
    assert wire_neg == b"\xff\xff\xff\xff\xff\xff\xff\xff\xff\x01"
    assert decode_int64_varint_fixed(wire_neg) == -1
    assert encode_sint64_zigzag(-1) == b"\x01"
    assert decode_sint64_zigzag(encode_sint64_zigzag(INT64_MIN)) == INT64_MIN
    with pytest.raises(OverflowError):
        encode_sint64_zigzag(INT64_MIN - 1)

@given(st.one_of(st.sampled_from([INT64_MIN, INT64_MIN + 1, -1, 0, 1, INT64_MAX]), st.integers(INT64_MIN, INT64_MAX)))
def test_int64_and_sint64_roundtrip_and_wire_size(n: int):
    w_tc = encode_int64_varint_fixed(n)
    w_zz = encode_sint64_zigzag(n)
    assert 1 <= len(w_tc) <= 10 and 1 <= len(w_zz) <= 10
    assert decode_int64_varint_fixed(w_tc) == n
    assert decode_sint64_zigzag(w_zz) == n
