import re
from hypothesis import given, strategies as st

QVAL_RE = re.compile(r"^(?:0(?:\.\d{1,3})?|1(?:\.0{1,3})?)$")

def select_media_buggy(accept_hdr: str, offered: list[str]) -> str | None:
    prefs = {}
