def select_media_fixed(accept_hdr: str, offered: list[str]) -> str | None:
    if not accept_hdr.strip():
        return None
    rules: dict[str, int] = {}
    for raw_item in accept_hdr.split(","):
        parts = [p.strip() for p in raw_item.split(";") if p.strip()]
