    best_mime = None
    best_score = 0
    for m in offered:
        ml = m.lower()
        if ml in rules:
            q = rules[ml]
        elif "*/*" in rules:
            q = rules["*/*"]
        else:
            q = 0
        if q > best_score:
            best_score = q
            best_mime = ml
    return best_mime

def test_red_green_q_zero_exclusion_and_nan_poison():
    assert select_media_buggy("text/html;q=0", ["text/html"]) == "text/html"

    assert select_media_fixed("text/html;q=0, */*;q=0.8", ["text/html"]) is None
    assert select_media_fixed("text/html;q=0, */*;q=0.8", ["text/html", "application/json"]) == "application/json"

    for invalid_q in ("text/html;q=NaN", "text/html;q=1.001", "text/html;q=-0.1", "text/html;q=0.1234"):
        try:
            select_media_fixed(invalid_q, ["text/html"])
