import fc from 'fast-check';
import { describe, it, expect } from 'vitest';

function parseOctetsStrict(ip: string): [number, number, number, number] | null {
  const parts = ip.split('.');
  if (parts.length !== 4) return null;
  const nums: number[] = [];
  for (const p of parts) {
    if (!/^(?:0|[1-9]\d{0,2})$/.test(p)) return null;
    const n = Number(p);
    if (n > 255) return null;
    nums.push(n);
  }
  return nums as [number, number, number, number];
}

export function ip_in_cidr_buggy(ip: string, cidr: string): boolean {
  const [netStr, pStr] = cidr.split('/');
  const a = parseOctetsStrict(ip)!;
  const b = parseOctetsStrict(netStr)!;
  const prefix = Number(pStr);
  const ipInt = (a[0] << 24) | (a[1] << 16) | (a[2] << 8) | a[3];
  const netInt = (b[0] << 24) | (b[1] << 16) | (b[2] << 8) | b[3];
  const mask = ~0 << (32 - prefix);
  return (ipInt & mask) === (netInt & mask);
}

export function ip_to_uint32(ip: string): number {
  const o = parseOctetsStrict(ip);
  if (!o) throw new Error(`Invalid IP: ${ip}`);
  return (((o[0] << 24) | (o[1] << 16) | (o[2] << 8) | o[3]) >>> 0);
}

export function ip_in_cidr_fixed(ip: string, cidr: string): boolean {
  const parts = cidr.split('/');
  if (parts.length !== 2 || !/^(?:0|[1-9]\d?)$/.test(parts[1])) {
    throw new Error(`Invalid CIDR: ${cidr}`);
  }
  const prefix = Number(parts[1]);
  if (prefix < 0 || prefix > 32) throw new Error('Prefix out of range');
  const ipU = ip_to_uint32(ip);
  const netU = ip_to_uint32(parts[0]);
  const mask = prefix === 0 ? 0 : ((0xffffffff << (32 - prefix)) >>> 0);
  return ((ipU & mask) >>> 0) === ((netU & mask) >>> 0);
}

function bitStringOracle(ip: string, net: string, prefix: number): boolean {
  const toBits = (s: string) =>
    parseOctetsStrict(s)!
      .map((n) => n.toString(2).padStart(8, '0'))
      .join('');
  return toBits(ip).slice(0, prefix) === toBits(net).slice(0, prefix);
}

