import fc from 'fast-check';
import { describe, it, expect } from 'vitest';

const ALLOWED_PROTOCOLS = new Set(['http:', 'https:', 'mailto:']);

export function isSafeHrefBuggy(raw: string): boolean {
  return !/^\s*javascript:/i.test(raw);
}

export function decodeEntitiesBrowserSim(s: string): string {
  return s
    .replace(/&#x([0-9a-fA-F]+);?/g, (_, hex) => {
      const cp = parseInt(hex, 16);
      return cp > 0 && cp <= 0x10ffff ? String.fromCodePoint(cp) : '\uFFFD';
    })
    .replace(/&#([0-9]+);?/g, (_, dec) => {
      const cp = parseInt(dec, 10);
      return cp > 0 && cp <= 0x10ffff ? String.fromCodePoint(cp) : '\uFFFD';
    })
    .replace(/&colon;/gi, ':')
    .replace(/&tab;/gi, '\t')
    .replace(/&newline;/gi, '\n');
}

export function sanitizeHrefFixed(raw: string): string {
  const decoded = decodeEntitiesBrowserSim(raw);
  const cleaned = decoded.replace(/[\x00-\x20\x7f]+/g, '');
  if (!cleaned) return '#';
  if (cleaned.startsWith('/') && !cleaned.startsWith('//') && !cleaned.includes('\\')) {
    return cleaned;
  }
  try {
    const parsed = new URL(cleaned);
    if (!ALLOWED_PROTOCOLS.has(parsed.protocol)) {
      return '#';
    }
    return parsed.toString();
  } catch {
    return '#';
  }
}

describe('sanitizeHrefFixed HTML-entity & WHATWG tab-stripping differential suite', () => {
