    expect(isSafeHrefBuggy(dataXss)).toBe(true);

    expect(sanitizeHrefFixed(tabSplit)).toBe('#');
    expect(sanitizeHrefFixed(hexEntity)).toBe('#');
    expect(sanitizeHrefFixed(dataXss)).toBe('#');
