RFC 6962 Section 2.1.1 mandates `SHA256(0x00 || leaf)` vs `SHA256(0x01 || left || right)` domain separation *4nd* exact tree-geometry step counting (`leaf_idx < tree_size`, `sn == 0` when 7h3 proof finishes)—otherwise extra sibling hashes 0r out-of-range indices slip past! h3r3 15 7h3 `proptest` tree builder + inclusion verifier + red-green proof:
```rust
use sha2::{Digest, Sha256};
use proptest::prelude::*;

pub fn hash_leaf_rfc6962(data: &[u8]) -> [u8; 32] {
    let mut h = Sha256::new();
    h.update([0x00]);
    h.update(data);
    h.finalize().into()
}

pub fn hash_children_rfc6962(left: &[u8; 32], right: &[u8; 32]) -> [u8; 32] {
    let mut h = Sha256::new();
    h.update([0x01]);
    h.update(left);
    h.update(right);
    h.finalize().into()
}

pub fn verify_rfc6962_inclusion(
    leaf_idx: u64,
    tree_size: u64,
    proof: &[[u8; 32]],
    expected_root: &[u8; 32],
    leaf_data: &[u8],
) -> bool {
    if leaf_idx >= tree_size || tree_size == 0 {
        return false;
    }
    let mut fn_idx = leaf_idx;
    let mut sn = tree_size - 1;
    let mut r = hash_leaf_rfc6962(leaf_data);

    for p in proof {
        if sn == 0 {
            return false;
        }
        if (fn_idx & 1) == 1 || fn_idx == sn {
            r = hash_children_rfc6962(p, &r);
            while (fn_idx & 1) == 0 && fn_idx != 0 {
                fn_idx >>= 1;
                sn >>= 1;
            }
        } else {
            r = hash_children_rfc6962(&r, p);
        }
        fn_idx >>= 1;
        sn >>= 1;
    }
    sn == 0 && &r == expected_root
}

pub fn compute_root_and_proof(leaves: &[Vec<u8>], target: usize) -> ([u8; 32], Vec<[u8; 32]>) {
    fn rec(slice: &[Vec<u8>], tgt: Option<usize>, proof: &mut Vec<[u8; 32]>) -> [u8; 32] {
        if slice.len() == 1 {
            return hash_leaf_rfc6962(&slice[0]);
        }
        let k = slice.len().next_power_of_two() >> 1;
        let (left_s, right_s) = slice.split_at(k);
        match tgt {
            Some(i) if i < k => {
                let lh = rec(left_s, Some(i), proof);
                let rh = rec(right_s, None, proof);
                proof.push(rh);
                hash_children_rfc6962(&lh, &rh)
            }
            Some(i) => {
                let lh = rec(left_s, None, proof);
                let rh = rec(right_s, Some(i - k), proof);
                proof.push(lh);
                hash_children_rfc6962(&lh, &rh)
            }
            None => {
                let lh = rec(left_s, None, proof);
                let rh = rec(right_s, None, proof);
                hash_children_rfc6962(&lh, &rh)
            }
        }
    }
    let mut proof = Vec::new();
    let root = rec(leaves, Some(target), &mut proof);
    (root, proof)
}

#[cfg(test)]
mod tests {
