    #[test]
    fn red_green_domain_separation_and_out_of_bounds_index_proof() {
        let leaves = vec![b"a".to_vec(), b"b".to_vec(), b"c".to_vec()];
        let (root, proof_zero) = compute_root_and_proof(&leaves, 0);
        assert!(verify_rfc6962_inclusion(0, 3, &proof_zero, &root, b"a"));

        let ha = hash_leaf_rfc6962(b"a");
        let hb = hash_leaf_rfc6962(b"b");
        let mut forged = Vec::with_capacity(64);
        forged.extend_from_slice(&ha);
        forged.extend_from_slice(&hb);
        let hc = hash_leaf_rfc6962(b"c");
        assert!(!verify_rfc6962_inclusion(0, 2, &[hc], &root, &forged));

        assert!(!verify_rfc6962_inclusion(3, 3, &proof_zero, &root, b"a"));
        let (root_single, _) = compute_root_and_proof(&[b"only".to_vec()], 0);
        assert!(verify_rfc6962_inclusion(0, 1, &[], &root_single, b"only"));
        assert!(!verify_rfc6962_inclusion(0, 1, &[ha], &root_single, b"only"));
    }

    proptest! {
