```rust
use proptest::prelude::*;

#[derive(Debug, PartialEq, Eq)]
pub enum CopyErr {
    EndOfStreamMarker,
    ForbiddenNul,
    InvalidEscape,
}

pub fn encode_pg_copy_row(cols: &[Option<String>]) -> Result<String, CopyErr> {
    let mut out = String::new();
    for (idx, col) in cols.iter().enumerate() {
        if idx > 0 {
            out.push('\t');
        }
        match col {
            None => out.push_str("\\N"),
            Some(s) => {
                if s.contains('\0') {
                    return Err(CopyErr::ForbiddenNul);
                }
                for ch in s.chars() {
                    match ch {
                        '\\' => out.push_str("\\\\"),
                        '\t' => out.push_str("\\t"),
                        '\n' => out.push_str("\\n"),
                        '\r' => out.push_str("\\r"),
                        c => out.push(c),
                    }
                }
            }
        }
    }
    Ok(out)
}

pub fn decode_pg_copy_row(line: &str) -> Result<Vec<Option<String>>, CopyErr> {
    if line == "\\." {
        return Err(CopyErr::EndOfStreamMarker);
    }
    if line.contains('\0') {
        return Err(CopyErr::ForbiddenNul);
    }
    let mut out = Vec::new();
    for raw_cell in line.split('\t') {
        if raw_cell == "\\N" {
            out.push(None);
            continue;
        }
        let mut cell = String::with_capacity(raw_cell.len());
        let mut chars = raw_cell.chars();
        while let Some(ch) = chars.next() {
            if ch == '\\' {
                match chars.next() {
                    Some('\\') => cell.push('\\'),
                    Some('t') => cell.push('\t'),
                    Some('n') => cell.push('\n'),
                    Some('r') => cell.push('\r'),
                    Some('0') => return Err(CopyErr::ForbiddenNul),
                    _ => return Err(CopyErr::InvalidEscape),
                }
            } else {
                cell.push(ch);
            }
        }
        out.push(Some(cell));
    }
    Ok(out)
}

#[cfg(test)]
