    #[test]
    fn red_green_eof_marker_and_null_vs_literal_backslash_n() {
        assert_eq!(decode_pg_copy_row("\\."), Err(CopyErr::EndOfStreamMarker));

        let row = vec![Some("\\.".to_owned()), None, Some("\\N".to_owned())];
        let wire = encode_pg_copy_row(&row).unwrap();
        assert_ne!(wire, "\\.");
        assert_eq!(decode_pg_copy_row(&wire), Ok(row));

        assert_eq!(encode_pg_copy_row(&[Some("a\0b".into())]), Err(CopyErr::ForbiddenNul));
        assert_eq!(decode_pg_copy_row("a\\0b"), Err(CopyErr::ForbiddenNul));
    }

    proptest! {
