import fc from 'fast-check';
import { describe, it, expect } from 'vitest';

const DECIMAL_RE = /^(-?)(?:0|[1-9]\d*)(?:\.(\d+))?$/;

export function parseUnitsBuggy(text: string, decimals: number): bigint {
  const [intStr, fracStr = ''] = text.split('.');
  const whole = BigInt(intStr);
  const scale = 10n ** BigInt(decimals);
  const frac = BigInt(fracStr.padEnd(decimals, '0').slice(0, decimals));
  return whole < 0n ? whole * scale - frac : whole * scale + frac;
}

export function parseSignedUnitsFixed(text: string, decimals: number): bigint {
  const m = DECIMAL_RE.exec(text);
  if (!m) {
    throw new Error(`Invalid decimal syntax: ${text}`);
  }
  const isNeg = m[1] === '-';
  const fracRaw = m[2] ?? '';
  if (fracRaw.length > decimals) {
    throw new Error(`Fractional precision ${fracRaw.length} exceeds ${decimals}`);
  }
  const unsignedText = isNeg ? text.slice(1) : text;
  const [intPart, fracPart = ''] = unsignedText.split('.');
  const scale = 10n ** BigInt(decimals);
  const fracScaled = fracPart.length === 0 ? 0n : BigInt(fracPart.padEnd(decimals, '0'));
  const mag = BigInt(intPart) * scale + fracScaled;
  return isNeg ? -mag : mag;
}

export function formatSignedUnits(units: bigint, decimals: number): string {
  const isNeg = units < 0n;
  const mag = isNeg ? -units : units;
  if (decimals === 0) return (isNeg ? '-' : '') + mag.toString();
  const scale = 10n ** BigInt(decimals);
  const whole = mag / scale;
  const frac = (mag % scale).toString().padStart(decimals, '0').replace(/0+$/, '');
  const sign = isNeg ? '-' : '';
  return frac.length > 0 ? `${sign}${whole}.${frac}` : `${sign}${whole}`;
}

describe('parseSignedUnitsFixed negative sub-unit -0.xx sign-loss fuzzing', () => {
