    expect(parseSignedUnitsFixed('-0.000001', 6)).toBe(-1n);
    expect(parseSignedUnitsFixed('-0.0', 6)).toBe(0n);
    expect(() => parseSignedUnitsFixed('-0.1234567', 6)).toThrow(/precision/);
