use proptest::prelude::*;

#[derive(Debug, PartialEq, Eq)]
pub enum SplitErr {
    EmptyRecipients,
    ZeroTotalWeight,
}

pub fn split_fee_buggy(total_fee: u128, shares: &[u64]) -> Vec<u128> {
    let sum: u128 = shares.iter().map(|&s| s as u128).sum();
    shares.iter().map(|&s| (total_fee * (s as u128)) / sum).collect()
}

pub fn split_fee_exact(total_fee: u128, shares: &[u64]) -> Result<Vec<u128>, SplitErr> {
    if shares.is_empty() {
        return Err(SplitErr::EmptyRecipients);
    }
    let sum: u128 = shares.iter().map(|&s| s as u128).sum();
    if sum == 0 {
        return Err(SplitErr::ZeroTotalWeight);
    }
    let whole_per_w = total_fee / sum;
    let rem_fee = total_fee % sum;

    let mut out = Vec::with_capacity(shares.len());
    let mut rems: Vec<(u128, usize)> = Vec::with_capacity(shares.len());
    let mut distributed: u128 = 0;

    for (i, &s) in shares.iter().enumerate() {
        let su = s as u128;
        let base = whole_per_w * su + (rem_fee * su) / sum;
        let sub_rem = (rem_fee * su) % sum;
        out.push(base);
        distributed += base;
        rems.push((sub_rem, i));
    }
    let dust = (total_fee - distributed) as usize;
    rems.sort_by(|a, b| b.0.cmp(&a.0).then_with(|| a.1.cmp(&b.1)));
    for &(_, idx) in rems.iter().take(dust) {
        out[idx] += 1;
    }
    Ok(out)
}

