import fc from 'fast-check';
import { describe, it, expect } from 'vitest';

export function jcsBuggyLocale(obj: Record<string, unknown>): string {
  // BUG: localeCompare sorts case-insensitively ('a' before 'B') instead of UTF-16 code units!
  const keys = Object.keys(obj).sort((a, b) => a.localeCompare(b, 'en'));
  return `{${keys.map((k) => `${JSON.stringify(k)}:${JSON.stringify(obj[k])}`).join(',')}}`;
}

export function jcsCanonicalize(val: unknown): string {
  if (val === null || typeof val === 'boolean') {
    return JSON.stringify(val);
  }
  if (typeof val === 'number') {
    if (!Number.isFinite(val)) {
      throw new Error('RFC 8785 forbids NaN and Infinity');
    }
    // ES6 Number.prototype.toString / JSON.stringify already formats -0 as '0' and matches RFC 8785!
    return Object.is(val, -0) ? '0' : JSON.stringify(val);
  }
  if (typeof val === 'string') {
    return JSON.stringify(val);
  }
  if (Array.isArray(val)) {
    const items = val.map((el) => (el === undefined ? 'null' : jcsCanonicalize(el)));
    return `[${items.join(',')}]`;
  }
  if (typeof val === 'object') {
    const rec = val as Record<string, unknown>;
    const keys = Object.keys(rec)
      .filter((k) => rec[k] !== undefined)
      .sort((a, b) => (a < b ? -1 : a > b ? 1 : 0)); // exact UTF-16 code-unit order!
    const props = keys.map((k) => `${JSON.stringify(k)}:${jcsCanonicalize(rec[k])}`);
    return `{${props.join(',')}}`;
  }
  throw new TypeError(`Unsupported JCS value: ${typeof val}`);
}

describe('jcsCanonicalize RFC 8785 UTF-16 key order & undefined/NaN suite', () => {
  it('red-green proof: sorts "B" (0x42) before "a" (0x61), omits undefined props, and rejects NaN', () => {
    const sample = { a: 1, B: 2 };
    // RED on localeCompare: emits '{"a":1,"B":2}' (breaking Go/Rust RFC 8785 verifiers)!
    expect(jcsBuggyLocale(sample)).toBe('{"a":1,"B":2}');

    // GREEN on RFC 8785 code-unit sort: 'B' (0x42) < 'a' (0x61) -> '{"B":2,"a":1}'!
    expect(jcsCanonicalize({ a: 1, B: 2, dropMe: undefined, negZero: -0 })).toBe(
      '{"B":2,"a":1,"negZero":0}'
    );
    expect(jcsCanonicalize([undefined, -0])).toBe('[null,0]');
    expect(() => jcsCanonicalize({ bad: Number.NaN })).toThrow(/RFC 8785/);
    expect(() => jcsCanonicalize({ bad: Number.POSITIVE_INFINITY })).toThrow(/RFC 8785/);
  });

  it('is invariant under key insertion order and semantically equal to JSON.parse', () => {
    const keyArb = fc.stringOf(fc.constantFrom('a', 'B', 'Z', '_', '0', '\uD83D\uDE00', '\uE000'), {
      minLength: 1,
      maxLength: 6,
    });
    const pairsArb = fc.array(fc.tuple(keyArb, fc.oneof(fc.integer(), fc.constant(-0), fc.string())), {
      minLength: 0,
      maxLength: 8,
    });

    fc.assert(
      fc.property(pairsArb, (pairs) => {
        const dedup = new Map(pairs);
        const fwdObj = Object.fromEntries(dedup.entries());
        const revObj = Object.fromEntries(Array.from(dedup.entries()).reverse());
        const c1 = jcsCanonicalize(fwdObj);
        const c2 = jcsCanonicalize(revObj);
        expect(c1).toBe(c2);
        expect(JSON.parse(c1)).toEqual(JSON.parse(JSON.stringify(fwdObj)));
      })
    );
  });
});
