import fc from 'fast-check';
import { describe, it, expect } from 'vitest';

// RFC 2046 bchars: DIGIT / ALPHA / "'()+_,-./:=?" and SPACE (except space may not be last char)
const BCHARS_RE = /^[A-Za-z0-9'()+_,\-./:=? ]{1,70}$/;
const TOKEN_RE = /^[!#$%&'*+.^_`|~0-9A-Za-z-]{1,70}$/;

export function extractBoundaryBuggy(ct: string): string | null {
  for (const part of ct.split(';').slice(1)) {
    const [k, v] = part.trim().split('=');
    if (k?.toLowerCase() === 'boundary' && v) {
      return v.replace(/^"|"$/g, '');
    }
  }
  return null;
}

function splitHeaderParamsQuoted(s: string): string[] {
  const parts: string[] = [];
  let cur = '';
  let inQ = false;
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (inQ) {
      if (c === '\\' && i + 1 < s.length) {
        cur += c + s[i + 1];
        i++;
      } else {
        if (c === '"') inQ = false;
        cur += c;
      }
    } else if (c === '"') {
      inQ = true;
      cur += c;
    } else if (c === ';') {
      parts.push(cur);
      cur = '';
    } else {
      cur += c;
    }
  }
  if (inQ) throw new Error('Unterminated quoted-string in Content-Type');
  parts.push(cur);
  return parts;
}

export function extractMultipartBoundary(contentType: string): string {
  const segments = splitHeaderParamsQuoted(contentType);
  const mediaType = segments[0].trim().toLowerCase();
  if (!mediaType.startsWith('multipart/')) {
    throw new Error('Not a multipart Content-Type');
  }
  let found: string | null = null;
  for (const rawParam of segments.slice(1)) {
    const p = rawParam.trim();
    if (!p) continue;
    const eq = p.indexOf('=');
    if (eq <= 0) throw new Error('Malformed parameter');
    const name = p.slice(0, eq).trim().toLowerCase();
    let val = p.slice(eq + 1).trim();
    if (name !== 'boundary') continue;
    if (found !== null) throw new Error('Duplicate boundary parameter');

    if (val.startsWith('"')) {
      if (!val.endsWith('"') || val.length < 2) throw new Error('Malformed quoted boundary');
      val = val.slice(1, -1).replace(/\\(.)/g, '$1');
    } else if (!TOKEN_RE.test(val)) {
      throw new Error('Unquoted boundary contains non-token chars');
    }
    if (!BCHARS_RE.test(val) || val.endsWith(' ')) {
      throw new Error('Invalid RFC 2046 boundary value or length > 70');
    }
    found = val;
  }
  if (found === null) throw new Error('Missing boundary parameter');
  return found;
}

describe('extractMultipartBoundary RFC 2046 quoted delimiter & 70-char cap suite', () => {
  it('red-green proof: parses quoted boundary with = and spaces, rejects >70 chars and trailing space', () => {
    const ct = 'multipart/form-data; charset=utf-8; boundary="gc0p: part=1"';
    // RED on buggy split(';') + split('='): truncates at ':' / '=' and returns '"gc0p: part'!
    expect(extractBoundaryBuggy(ct)).toBe('"gc0p: part');

    // GREEN on RFC 2046 parser:
    expect(extractMultipartBoundary(ct)).toBe('gc0p: part=1');
    expect(() => extractMultipartBoundary(`multipart/mixed; boundary=${'a'.repeat(71)}`)).toThrow(/70/);
    expect(() => extractMultipartBoundary('multipart/mixed; boundary="trailing "')).toThrow();
    expect(() => extractMultipartBoundary('multipart/mixed; boundary=a; boundary=b')).toThrow(/Duplicate/);
  });

  it('round-trips all valid 1..70 char RFC 2046 boundaries when quoted', () => {
    const bcharArb = fc
      .stringOf(fc.constantFrom('a', 'Z', '0', '-', '_', ':', '=', '/', ' '), { minLength: 1, maxLength: 70 })
      .filter((s) => !s.endsWith(' '));

    fc.assert(
      fc.property(bcharArb, (b) => {
        const hdr = `multipart/mixed; boundary="${b}"; charset=utf-8`;
        expect(extractMultipartBoundary(hdr)).toBe(b);
      })
    );
  });
});
```
