library CrossDecimalPricer {
    function convertBuggySubUnderflow(uint256 amtIn, uint8 decIn, uint8 decOut, uint256 priceE18)
        internal
        pure
        returns (uint256)
    {
        // BUG 1: decOut - decIn panics whenever decOut < decIn (e.g. WETH 18 -> USDC 6)!
        return (amtIn * priceE18 * (10 ** uint256(decOut - decIn))) / 1e18;
