using Limbs4 = std::array<uint64_t, 4>;

uint64_t sub_u256_buggy(const Limbs4& a, const Limbs4& b, Limbs4& out) {
    uint64_t borrow = 0;
    for (size_t i = 0; i < 4; ++i) {
        uint64_t rhs = b[i] + borrow;
        borrow = (a[i] < rhs) ? 1 : 0;
        out[i] = a[i] - rhs;
    }
    return borrow;
}

uint64_t sub_u256_fixed(const Limbs4& a, const Limbs4& b, Limbs4& out) {
