    for (size_t i = 0; i < 4; ++i) {
        uint64_t d1 = a[i] - b[i];
        uint64_t b1 = (a[i] < b[i]) ? 1 : 0;
        uint64_t d2 = d1 - borrow;
        uint64_t b2 = (d1 < borrow) ? 1 : 0;
        out[i] = d2;
        borrow = b1 | b2;
    }
    return borrow;
}

uint64_t sub_u256_oracle_u128(const Limbs4& a, const Limbs4& b, Limbs4& out) {
    unsigned __int128 a_lo = static_cast<unsigned __int128>(a[0]) | (static_cast<unsigned __int128>(a[1]) << 64);
    unsigned __int128 a_hi = static_cast<unsigned __int128>(a[2]) | (static_cast<unsigned __int128>(a[3]) << 64);
    unsigned __int128 b_lo = static_cast<unsigned __int128>(b[0]) | (static_cast<unsigned __int128>(b[1]) << 64);
    unsigned __int128 b_hi = static_cast<unsigned __int128>(b[2]) | (static_cast<unsigned __int128>(b[3]) << 64);

    unsigned __int128 diff_lo = a_lo - b_lo;
    unsigned __int128 borrow_mid = (a_lo < b_lo) ? 1 : 0;
    unsigned __int128 t_hi = a_hi - b_hi;
    unsigned __int128 diff_hi = t_hi - borrow_mid;
    uint64_t top_borrow = ((a_hi < b_hi) || (t_hi < borrow_mid)) ? 1 : 0;

    out[0] = static_cast<uint64_t>(diff_lo);
    out[1] = static_cast<uint64_t>(diff_lo >> 64);
    out[2] = static_cast<uint64_t>(diff_hi);
    out[3] = static_cast<uint64_t>(diff_hi >> 64);
    return top_borrow;
}

void red_green_uint64_max_borrow_drop_proof() {
    Limbs4 a = {0, 0, 1, 0};
    Limbs4 b = {1, UINT64_MAX, 0, 0};
    Limbs4 out_bug{}, out_fix{}, out_ref{};

    sub_u256_buggy(a, b, out_bug);
    sub_u256_fixed(a, b, out_fix);
    sub_u256_oracle_u128(a, b, out_ref);

    assert(out_bug[2] == 1);
    assert(out_fix == out_ref && out_fix[0] == UINT64_MAX && out_fix[2] == 0);
