extern "C" int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size) {
    static const bool once = (red_green_uint64_max_borrow_drop_proof(), true);
    (void)once;
    if (size < 64) return 0;
    Limbs4 a{}, b{}, got{}, ref{};
    std::memcpy(a.data(), data, 32);
    std::memcpy(b.data(), data + 32, 32);
    uint64_t bw_got = sub_u256_fixed(a, b, got);
    uint64_t bw_ref = sub_u256_oracle_u128(a, b, ref);
    if (bw_got != bw_ref || got != ref) __builtin_trap();
