#[derive(Debug, PartialEq, Eq)]
pub enum StatsErr {
    Empty,
    NonFinite,
}

pub fn median_buggy(values: &[f64]) -> f64 {
    let mut v = values.to_vec();
    v.sort_unstable_by(|a, b| a.partial_cmp(b).unwrap());
    let mid = v.len() / 2;
    if v.len() % 2 == 1 { v[mid] } else { (v[mid - 1] + v[mid]) / 2.0 }
}

pub fn median_finite_fixed(values: &[f64]) -> Result<f64, StatsErr> {
    if values.is_empty() {
        return Err(StatsErr::Empty);
    }
    if values.iter().any(|x| !x.is_finite()) {
        return Err(StatsErr::NonFinite);
    }
