use proptest::prelude::*;

#[derive(Debug, PartialEq, Eq)]
pub enum FrameErr {
    FrameTooLarge(u32),
}

pub struct SafeFrameDecoder {
    max_frame: usize,
    buf: Vec<u8>,
}

impl SafeFrameDecoder {
    pub fn new(max_frame: usize) -> Self {
        Self { max_frame, buf: Vec::new() }
    }

    pub fn feed(&mut self, mut input: &[u8], out: &mut Vec<Vec<u8>>) -> Result<(), FrameErr> {
        while !input.is_empty() {
            if self.buf.len() < 4 {
                let need = 4 - self.buf.len();
                let take = need.min(input.len());
                self.buf.extend_from_slice(&input[..take]);
                input = &input[take..];
                if self.buf.len() < 4 {
                    return Ok(());
                }
            }
            let hdr: [u8; 4] = self.buf[..4].try_into().unwrap();
            let body_len_u32 = u32::from_be_bytes(hdr);
            let body_len = body_len_u32 as usize;
            if body_len > self.max_frame {
                self.buf.clear();
                return Err(FrameErr::FrameTooLarge(body_len_u32));
            }
            let target_total = 4 + body_len;
            let rem = target_total - self.buf.len();
            let take = rem.min(input.len());
            self.buf.extend_from_slice(&input[..take]);
            input = &input[take..];

            if self.buf.len() == target_total {
                out.push(self.buf[4..].to_vec());
                self.buf.clear();
            }
        }
        Ok(())
    }

    pub fn buffered_capacity(&self) -> usize {
        self.buf.capacity()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn red_green_four_byte_oom_header_rejected_with_tiny_capacity() {
        let mut dec = SafeFrameDecoder::new(1024);
        let mut frames = Vec::new();
        let res = dec.feed(&[0xFF, 0xFF, 0xFF, 0xFF], &mut frames);
        assert_eq!(res, Err(FrameErr::FrameTooLarge(u32::MAX)));
        assert!(dec.buffered_capacity() <= 16);
    }

    proptest! {
        #[test]
        fn reassembles_multi_frame_streams_across_arbitrary_cuts(
            frames_in in prop::collection::vec(prop::collection::vec(any::<u8>(), 0..80), 1..8),
            cuts in prop::collection::vec(1_usize..13_usize, 1..20),
        ) {
            let mut wire = Vec::new();
            for f in &frames_in {
                wire.extend_from_slice(&(f.len() as u32).to_be_bytes());
                wire.extend_from_slice(f);
            }
            let mut dec = SafeFrameDecoder::new(128);
            let mut decoded = Vec::new();
            let mut pos = 0;
            let mut step = 0;
            while pos < wire.len() {
                let n = cuts[step % cuts.len()].min(wire.len() - pos);
                dec.feed(&wire[pos..pos + n], &mut decoded).unwrap();
                prop_assert!(dec.buffered_capacity() <= 256);
                pos += n;
                step += 1;
            }
            prop_assert_eq!(decoded, frames_in);
        }
    }
}
