import { describe, it, expect } from 'vitest';

export function readHeaderBuggy(view: Uint8Array): { magic: number; seq: bigint } {
  if (view.byteLength < 12) throw new RangeError('Truncated header');
  const dv = new DataView(view.buffer);
  return {
