export function readHeaderFixed(view: Uint8Array): { magic: number; seq: bigint } {
  if (view.byteLength < 12) {
    throw new RangeError('Truncated 12-byte frame header');
  }
  const dv = new DataView(view.buffer, view.byteOffset, view.byteLength);
