using Grid = std::vector<std::vector<std::string>>;

class StreamingCsvParser {
public:
    bool feed(std::string_view chunk) {
        for (char c : chunk) {
            any_seen_ = true;
            if (pending_cr_) {
                pending_cr_ = false;
                if (c == '\n') continue;
            }
            if (state_ == State::AfterQuoteInQuoted) {
                if (c == '"') {
                    cell_.push_back('"');
                    state_ = State::InQuoted;
                    continue;
                }
                state_ = State::Unquoted;
                if (c == ',') {
                    row_.push_back(std::move(cell_));
                    cell_.clear();
                    continue;
                }
                if (c == '\r' || c == '\n') {
                    if (c == '\r') pending_cr_ = true;
                    row_.push_back(std::move(cell_));
                    cell_.clear();
                    rows_.push_back(std::move(row_));
                    row_.clear();
                    continue;
                }
                return false;
            }
            if (state_ == State::InQuoted) {
                if (c == '"') state_ = State::AfterQuoteInQuoted;
                else cell_.push_back(c);
            } else {
                if (c == '"') {
                    if (!cell_.empty()) return false;
                    state_ = State::InQuoted;
                } else if (c == ',') {
                    row_.push_back(std::move(cell_));
                    cell_.clear();
                } else if (c == '\r' || c == '\n') {
                    if (c == '\r') pending_cr_ = true;
                    row_.push_back(std::move(cell_));
                    cell_.clear();
                    rows_.push_back(std::move(row_));
                    row_.clear();
                } else {
                    cell_.push_back(c);
                }
            }
        }
        return true;
    }

    std::optional<Grid> finish() {
        if (!any_seen_) return Grid{};
        if (state_ == State::InQuoted) return std::nullopt;
        if (state_ == State::AfterQuoteInQuoted || !cell_.empty() || !row_.empty()) {
            row_.push_back(std::move(cell_));
            rows_.push_back(std::move(row_));
        }
        return std::move(rows_);
    }

private:
    enum class State { Unquoted, InQuoted, AfterQuoteInQuoted };
    State state_ = State::Unquoted;
    bool pending_cr_ = false;
    bool any_seen_ = false;
    std::string cell_;
    std::vector<std::string> row_;
    Grid rows_;
};

