```rust
use proptest::prelude::*;

#[derive(Debug, PartialEq, Eq)]
pub enum RleErr {
    OddWireLength,
    ZeroRunCount,
    NonCanonicalAdjacentRun,
    OutputCapExceeded,
}

pub fn rle_encode(raw: &[u8]) -> Vec<u8> {
    let mut out = Vec::new();
    let mut i = 0;
    while i < raw.len() {
        let val = raw[i];
        let mut run: usize = 1;
        while i + run < raw.len() && raw[i + run] == val && run < 255 {
            run += 1;
        }
        out.push(run as u8);
        out.push(val);
        i += run;
    }
    out
}

pub fn rle_decode_bounded(wire: &[u8], max_len: usize) -> Result<Vec<u8>, RleErr> {
    if wire.len() % 2 != 0 {
        return Err(RleErr::OddWireLength);
    }
    let mut out = Vec::new();
    let mut prev: Option<(u8, u8)> = None;

    for pair in wire.chunks_exact(2) {
        let cnt = pair[0];
        let val = pair[1];
        if cnt == 0 {
            return Err(RleErr::ZeroRunCount);
        }
        if let Some((prev_cnt, prev_val)) = prev {
            if prev_val == val && prev_cnt < 255 {
                return Err(RleErr::NonCanonicalAdjacentRun);
            }
        }
        let c_usize = cnt as usize;
        if c_usize > max_len - out.len() {
            return Err(RleErr::OutputCapExceeded);
        }
        out.resize(out.len() + c_usize, val);
        prev = Some((cnt, val));
    }
    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn red_green_zero_run_unmerged_adjacent_and_cap_proof() {
        assert_eq!(rle_decode_bounded(&[0, b'X'], 100), Err(RleErr::ZeroRunCount));
        assert_eq!(rle_decode_bounded(&[2, b'X', 3, b'X'], 100), Err(RleErr::NonCanonicalAdjacentRun));
        assert_eq!(rle_decode_bounded(&[255, b'X', 5, b'X'], 300).unwrap().len(), 260);
        assert_eq!(rle_decode_bounded(&[255, b'X', 5, b'X'], 259), Err(RleErr::OutputCapExceeded));
    }

    proptest! {
        #[test]
        fn canonical_bijection_and_cap_enforcement(
            raw in prop::collection::vec(prop_oneof![Just(0_u8), Just(1_u8), any::<u8>()], 0..400),
            fuzzed_wire in prop::collection::vec(any::<u8>(), 0..64),
        ) {
            let wire = rle_encode(&raw);
            prop_assert_eq!(rle_decode_bounded(&wire, raw.len()), Ok(raw));

            if let Ok(decoded) = rle_decode_bounded(&fuzzed_wire, 512) {
                prop_assert!(decoded.len() <= 512);
                prop_assert_eq!(rle_encode(&decoded), fuzzed_wire);
            }
        }
    }
}
