import fc from 'fast-check';
import { describe, it, expect } from 'vitest';

export function matchPermBuggy(pattern: string, action: string): boolean {
  const re = new RegExp('^' + pattern.replace('*', '.*') + '$');
  return re.test(action);
}

export function matchPermissionFixed(pattern: string, action: string): boolean {
  let p = 0;
  let s = 0;
  let starIdx = -1;
  let matchAfterStar = 0;

  while (s < action.length) {
    if (p < pattern.length && (pattern[p] === '?' || pattern[p] === action[s])) {
      p++;
      s++;
    } else if (p < pattern.length && pattern[p] === '*') {
      starIdx = p;
      matchAfterStar = s;
      p++;
    } else if (starIdx !== -1) {
      p = starIdx + 1;
      matchAfterStar++;
      s = matchAfterStar;
    } else {
      return false;
    }
  }
  while (p < pattern.length && pattern[p] === '*') {
    p++;
  }
  return p === pattern.length;
}

function dpGlobOracle(pat: string, str: string): boolean {
  const m = pat.length;
  const n = str.length;
  const dp: boolean[][] = Array.from({ length: m + 1 }, () => Array(n + 1).fill(false));
  dp[0][0] = true;
  for (let i = 1; i <= m; i++) {
    if (pat[i - 1] === '*') dp[i][0] = dp[i - 1][0];
  }
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (pat[i - 1] === '*') {
        dp[i][j] = dp[i - 1][j] || dp[i][j - 1];
      } else if (pat[i - 1] === '?' || pat[i - 1] === str[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1];
      }
    }
  }
  return dp[m][n];
}

describe('matchPermissionFixed multi-star & regex-metachar differential suite', () => {
