    expect(matchPermBuggy('iam:*Role*', 'iam:PassRoleAdmin')).toBe(false);
    expect(matchPermBuggy('org.read', 'orgXread')).toBe(true);

    expect(matchPermissionFixed('iam:*Role*', 'iam:PassRoleAdmin')).toBe(true);
    expect(matchPermissionFixed('org.read', 'orgXread')).toBe(false);
    expect(matchPermissionFixed('org.read', 'org.read')).toBe(true);
