```ts
import fc from 'fast-check';
import { describe, it, expect } from 'vitest';

export interface SseEvent {
  event: string;
  data: string;
  lastEventId: string;
}

export function parseSseBuggy(raw: string): SseEvent[] {
  const events: SseEvent[] = [];
  let data: string[] = [];
  let lastId = '';
  for (const line of raw.split('\n')) {
    if (line === '') {
      if (data.length) { events.push({ event: 'message', data: data.join('\n'), lastEventId: lastId }); data = []; }
    } else if (line.startsWith('data:')) {
      data.push(line.slice(5).trim());
    } else if (line.startsWith('id:')) {
      lastId = line.slice(3).trim();
    }
  }
  return events;
}

export function parseSseWhatwg(raw: string): SseEvent[] {
  const lines = raw.split(/\r\n|\r|\n/);
  const out: SseEvent[] = [];
  let eventType = '';
  let dataBuf: string[] = [];
  let lastEventId = '';

  const limit = raw.endsWith('\n') || raw.endsWith('\r') ? lines.length - 1 : lines.length;
  for (let i = 0; i < limit; i++) {
    const line = lines[i];
    if (line === '') {
      if (dataBuf.length > 0) {
        out.push({
          event: eventType || 'message',
          data: dataBuf.join('\n'),
          lastEventId,
        });
      }
      eventType = '';
      dataBuf = [];
      continue;
    }
    if (line.startsWith(':')) continue;
    const colon = line.indexOf(':');
    const field = colon === -1 ? line : line.slice(0, colon);
    let val = colon === -1 ? '' : line.slice(colon + 1);
    if (val.startsWith(' ')) val = val.slice(1);

    if (field === 'event') {
      eventType = val;
    } else if (field === 'data') {
      dataBuf.push(val);
    } else if (field === 'id') {
      if (!val.includes('\0')) {
        lastEventId = val;
      }
    }
  }
  return out;
}

describe('parseSseWhatwg line-ending, single-space & NUL-id conformance', () => {
  it('red-green proof: handles bare CR, preserves second leading space, and ignores NUL id', () => {
    const stream = 'id: clean\rid: bad\0.id\rdata:  two_spaces \r\r';
    expect(parseSseBuggy(stream)).toEqual([]);

    expect(parseSseWhatwg(stream)).toEqual([
      { event: 'message', data: ' two_spaces ', lastEventId: 'clean' },
    ]);
  });

  it('produces identical events across CRLF, LF, and bare CR line terminators', () => {
    const dataLineArb = fc.stringOf(fc.constantFrom('a', ' ', '\t', ':'), { minLength: 0, maxLength: 12 });
    const idArb = fc.constantFrom('1', 'a\0b', '');

    fc.assert(
      fc.property(fc.array(dataLineArb, { minLength: 1, maxLength: 4 }), idArb, (dLines, idVal) => {
        const build = (eol: string) =>
          `id: ${idVal}${eol}` + dLines.map((d) => `data: ${d}${eol}`).join('') + eol;

        const rLf = parseSseWhatwg(build('\n'));
        const rCrlf = parseSseWhatwg(build('\r\n'));
        const rCr = parseSseWhatwg(build('\r'));

        expect(rCrlf).toEqual(rLf);
        expect(rCr).toEqual(rLf);
        expect(rLf[0].data).toBe(dLines.join('\n'));
        expect(rLf[0].lastEventId.includes('\0')).toBe(false);
      })
    );
  });
});
