```cpp
#include <cassert>
#include <cstddef>
#include <cstdint>
#include <optional>
#include <vector>

std::optional<std::vector<uint8_t>> lz4_block_decompress_fixed(
    const uint8_t* src,
    size_t src_len,
    size_t max_out
) {
    std::vector<uint8_t> out;
    size_t ip = 0;

    while (ip < src_len) {
        uint8_t token = src[ip++];
        size_t lit_len = token >> 4;
        if (lit_len == 15) {
            while (true) {
                if (ip >= src_len) return std::nullopt;
                uint8_t ext = src[ip++];
                if (ext > max_out - lit_len) return std::nullopt;
                lit_len += ext;
                if (ext != 255) break;
            }
        }
        if (lit_len > src_len - ip || lit_len > max_out - out.size()) {
            return std::nullopt;
        }
        out.insert(out.end(), src + ip, src + ip + lit_len);
        ip += lit_len;
        if (ip == src_len) {
            return out;
        }

        if (src_len - ip < 2) return std::nullopt;
        uint16_t offset = static_cast<uint16_t>(src[ip]) | (static_cast<uint16_t>(src[ip + 1]) << 8);
        ip += 2;
        if (offset == 0 || offset > out.size()) {
            return std::nullopt;
        }

        size_t match_len = static_cast<size_t>(token & 0x0F) + 4;
        if ((token & 0x0F) == 15) {
            while (true) {
                if (ip >= src_len) return std::nullopt;
                uint8_t ext = src[ip++];
                if (ext > max_out - match_len) return std::nullopt;
                match_len += ext;
                if (ext != 255) break;
            }
        }
        if (match_len > max_out - out.size()) {
            return std::nullopt;
        }
        for (size_t k = 0; k < match_len; ++k) {
            uint8_t b = out[out.size() - offset];
            out.push_back(b);
        }
    }
    return out;
}

void red_green_zero_offset_and_overlap_rle_proof() {
    const uint8_t kZeroOffset[] = {0x10, 'A', 0x00, 0x00};
    assert(!lz4_block_decompress_fixed(kZeroOffset, sizeof(kZeroOffset), 1024).has_value());

    const uint8_t kOverlapRle[] = {0x12, 'Z', 0x01, 0x00};
    auto rle = lz4_block_decompress_fixed(kOverlapRle, sizeof(kOverlapRle), 1024);
    assert(rle.has_value() && rle->size() == 7 && (*rle)[6] == 'Z');

    assert(!lz4_block_decompress_fixed(kOverlapRle, sizeof(kOverlapRle), 6).has_value());
}

extern "C" int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size) {
    static const bool once = (red_green_zero_offset_and_overlap_rle_proof(), true);
    (void)once;
    auto res = lz4_block_decompress_fixed(data, size, 4096);
    if (res.has_value() && res->size() > 4096) __builtin_trap();
    return 0;
}
