```cpp
#include <cassert>
#include <cstddef>
#include <cstdint>
#include <optional>
#include <string>
#include <string_view>
#include <utility>
#include <fuzzer/FuzzedDataProvider.h>

static std::optional<uint64_t> parse_digits_saturating(std::string_view s) {
    if (s.empty()) return std::nullopt;
    uint64_t acc = 0;
    for (char c : s) {
        if (c < '0' || c > '9') return std::nullopt;
        uint64_t d = static_cast<uint64_t>(c - '0');
        if (acc > (UINT64_MAX - d) / 10) {
            acc = UINT64_MAX;
        } else {
            acc = acc * 10 + d;
        }
    }
    return acc;
}

std::optional<std::pair<uint64_t, uint64_t>> resolve_byte_range_fixed(
    std::string_view hdr,
    uint64_t file_len
) {
    constexpr std::string_view kPfx = "bytes=";
    if (file_len == 0 || hdr.substr(0, kPfx.size()) != kPfx) return std::nullopt;
    std::string_view spec = hdr.substr(kPfx.size());
    size_t dash = spec.find('-');
    if (dash == std::string_view::npos || spec.find('-', dash + 1) != std::string_view::npos) {
        return std::nullopt;
    }
    std::string_view lhs = spec.substr(0, dash);
    std::string_view rhs = spec.substr(dash + 1);

    if (lhs.empty()) {
        auto suffix = parse_digits_saturating(rhs);
        if (!suffix.has_value() || *suffix == 0) return std::nullopt;
        uint64_t take = (*suffix >= file_len) ? file_len : *suffix;
        return std::make_pair(file_len - take, file_len - 1);
    }

    auto first = parse_digits_saturating(lhs);
    if (!first.has_value() || *first >= file_len) return std::nullopt;
    if (rhs.empty()) {
        return std::make_pair(*first, file_len - 1);
    }
    auto last = parse_digits_saturating(rhs);
    if (!last.has_value() || *last < *first) return std::nullopt;
    uint64_t clamped_last = (*last >= file_len) ? (file_len - 1) : *last;
    return std::make_pair(*first, clamped_last);
}

void red_green_empty_file_zero_suffix_and_huge_end_proof() {
    assert(!resolve_byte_range_fixed("bytes=0-0", 0).has_value());
    assert(!resolve_byte_range_fixed("bytes=-0", 100).has_value());
    assert(!resolve_byte_range_fixed("bytes=50-10", 100).has_value());
    auto r = resolve_byte_range_fixed("bytes=10-999999999999999999999999", 100);
    assert(r == std::make_pair(static_cast<uint64_t>(10), static_cast<uint64_t>(99)));
