use std::cmp::Ordering;
use proptest::prelude::*;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum PreId {
    Numeric(u64),
    AlphaNum(String),
}

impl Ord for PreId {
    fn cmp(&self, other: &Self) -> Ordering {
        match (self, other) {
            (PreId::Numeric(a), PreId::Numeric(b)) => a.cmp(b),
            (PreId::Numeric(_), PreId::AlphaNum(_)) => Ordering::Less,
            (PreId::AlphaNum(_), PreId::Numeric(_)) => Ordering::Greater,
            (PreId::AlphaNum(a), PreId::AlphaNum(b)) => a.cmp(b),
        }
    }
}
impl PartialOrd for PreId {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> { Some(self.cmp(other)) }
}

#[derive(Debug, Clone)]
pub struct SemVer {
    pub major: u64,
    pub minor: u64,
    pub patch: u64,
    pub pre: Vec<PreId>,
    pub build: Vec<String>,
}

fn parse_core_num(s: &str) -> Option<u64> {
    if s.is_empty() || (s.len() > 1 && s.starts_with('0')) || !s.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    s.parse().ok()
}

impl SemVer {
    pub fn parse_strict(raw: &str) -> Option<Self> {
        let (no_build, build_opt) = match raw.split_once('+') {
            Some((l, b)) => (l, Some(b)),
            None => (raw, None),
        };
        let (core, pre_opt) = match no_build.split_once('-') {
            Some((c, p)) => (c, Some(p)),
            None => (no_build, None),
        };
        let mut cparts = core.split('.');
        let major = parse_core_num(cparts.next()?)?;
        let minor = parse_core_num(cparts.next()?)?;
        let patch = parse_core_num(cparts.next()?)?;
        if cparts.next().is_some() { return None; }

        let mut pre = Vec::new();
        if let Some(p_str) = pre_opt {
            if p_str.is_empty() { return None; }
            for id in p_str.split('.') {
                if id.is_empty() || !id.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'-') {
                    return None;
                }
                if id.bytes().all(|b| b.is_ascii_digit()) {
                    pre.push(PreId::Numeric(parse_core_num(id)?));
                } else {
                    pre.push(PreId::AlphaNum(id.to_owned()));
                }
            }
        }

        let mut build = Vec::new();
        if let Some(b_str) = build_opt {
            if b_str.is_empty() { return None; }
            for id in b_str.split('.') {
                if id.is_empty() || !id.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'-') {
                    return None;
                }
                build.push(id.to_owned());
            }
        }
        Some(Self { major, minor, patch, pre, build })
    }
}

impl PartialEq for SemVer {
    fn eq(&self, o: &Self) -> bool {
        (self.major, self.minor, self.patch, &self.pre) == (o.major, o.minor, o.patch, &o.pre)
    }
}
impl Eq for SemVer {}
impl Ord for SemVer {
    fn cmp(&self, o: &Self) -> Ordering {
        (self.major, self.minor, self.patch)
            .cmp(&(o.major, o.minor, o.patch))
            .then_with(|| match (self.pre.is_empty(), o.pre.is_empty()) {
                (true, true) => Ordering::Equal,
                (true, false) => Ordering::Greater,
                (false, true) => Ordering::Less,
                (false, false) => self.pre.cmp(&o.pre),
            })
    }
}
impl PartialOrd for SemVer {
    fn partial_cmp(&self, o: &Self) -> Option<Ordering> { Some(self.cmp(o)) }
}

