use proptest::prelude::*;

#[derive(Debug, PartialEq, Eq)]
pub enum LikeErr {
    DanglingEscape,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Tok {
    Star,
    AnyOne,
    Lit(char),
}

pub fn sql_like_buggy_bytes(text: &str, pat: &str) -> bool {
    if pat == "_" && !text.is_empty() {
        return text[1..].is_empty();
    }
    text == pat
}

pub fn sql_like_utf8(text: &str, pat: &str) -> Result<bool, LikeErr> {
    let mut toks = Vec::new();
    let mut pchars = pat.chars();
    while let Some(c) = pchars.next() {
        match c {
            '\\' => {
                let escaped = pchars.next().ok_or(LikeErr::DanglingEscape)?;
                toks.push(Tok::Lit(escaped));
            }
            '%' => {
                if toks.last() != Some(&Tok::Star) {
                    toks.push(Tok::Star);
                }
            }
            '_' => toks.push(Tok::AnyOne),
            lit => toks.push(Tok::Lit(lit)),
        }
    }

    let tchars: Vec<char> = text.chars().collect();
    let (mut ti, mut pi) = (0_usize, 0_usize);
    let mut star_pi: Option<usize> = None;
    let mut star_ti: usize = 0;

    while ti < tchars.len() {
        if pi < toks.len() && (toks[pi] == Tok::AnyOne || toks[pi] == Tok::Lit(tchars[ti])) {
            ti += 1;
            pi += 1;
        } else if pi < toks.len() && toks[pi] == Tok::Star {
            star_pi = Some(pi);
            star_ti = ti;
            pi += 1;
        } else if let Some(sp) = star_pi {
            pi = sp + 1;
            star_ti += 1;
            ti = star_ti;
        } else {
            return Ok(false);
        }
    }
    while pi < toks.len() && toks[pi] == Tok::Star {
        pi += 1;
    }
    Ok(pi == toks.len())
}

fn regex_like_oracle(text: &str, pat: &str) -> Result<bool, LikeErr> {
    let mut rx = String::from("(?s)^(?:");
    let mut it = pat.chars();
    while let Some(c) = it.next() {
        match c {
            '\\' => {
                let nxt = it.next().ok_or(LikeErr::DanglingEscape)?;
                rx.push_str(&regex::escape(&nxt.to_string()));
            }
            '%' => rx.push_str(".*"),
            '_' => rx.push('.'),
            other => rx.push_str(&regex::escape(&other.to_string())),
        }
    }
    rx.push_str(")$");
    Ok(regex::Regex::new(&rx).unwrap().is_match(text))
}

