        assert_eq!(sql_like_utf8("🦀", "_"), Ok(true));
        assert_eq!(sql_like_utf8("🦀🦀", "_"), Ok(false));
        assert_eq!(sql_like_utf8("abc", "abc\\"), Err(LikeErr::DanglingEscape));
        assert_eq!(sql_like_utf8("100%", "100\\%"), Ok(true));
        assert_eq!(sql_like_utf8("1000", "100\\%"), Ok(false));
    }

    proptest! {
