import pytest
from hypothesis import given, strategies as st

IDENT_RE = re.compile(r"^[0-9A-Za-z-]+$")

def semver_cmp_buggy(a: str, b: str) -> int:
    def key(s: str):
        core, _, rest = s.partition("-")
        return (*map(int, core.split(".")), rest)
    ka, kb = key(a), key(b)
    return -1 if ka < kb else (1 if ka > kb else 0)

def _parse_semver_key(raw: str):
    base, has_build, build = raw.partition("+")
    if has_build:
        if not build or any(not IDENT_RE.fullmatch(p) for p in build.split(".")):
            raise ValueError(f"Invalid build metadata in {raw!r}")
    core, has_pre, pre = base.partition("-")
    cparts = core.split(".")
    if len(cparts) != 3:
        raise ValueError(f"Invalid core version in {raw!r}")
    nums = []
    for p in cparts:
        if not p.isdigit() or (len(p) > 1 and p.startswith("0")):
            raise ValueError(f"Invalid numeric component {p!r}")
        nums.append(int(p))

    if not has_pre:
        return (*nums, 1, ())
    if not pre:
        raise ValueError("Empty prerelease")
    pre_key = []
    for tok in pre.split("."):
        if not IDENT_RE.fullmatch(tok):
            raise ValueError(f"Invalid prerelease identifier {tok!r}")
        if tok.isdigit():
            if len(tok) > 1 and tok.startswith("0"):
                raise ValueError(f"Leading zero in numeric prerelease {tok!r}")
            pre_key.append((0, int(tok)))
        else:
            pre_key.append((1, tok))
    return (*nums, 0, tuple(pre_key))

def semver_compare_fixed(a: str, b: str) -> int:
    ka = _parse_semver_key(a)
    kb = _parse_semver_key(b)
    return -1 if ka < kb else (1 if ka > kb else 0)

def test_red_green_release_above_prerelease_and_build_metadata():
