    chain = [
        "1.0.0-alpha",
        "1.0.0-alpha.1",
        "1.0.0-alpha.beta",
        "1.0.0-beta",
        "1.0.0-beta.2",
        "1.0.0-beta.11",
        "1.0.0-rc.1",
        "1.0.0",
    ]
    for lo, hi in zip(chain, chain[1:]):
        assert semver_compare_fixed(lo, hi) == -1
        assert semver_compare_fixed(hi, lo) == 1

    assert semver_compare_fixed("1.0.0+sha.aaa", "1.0.0+sha.bbb") == 0
    with pytest.raises(ValueError):
        semver_compare_fixed("1.0.0-01", "1.0.0")

ver_strat = st.builds(
    lambda maj, pre, bld: f"{maj}.0.0" + (f"-{pre}" if pre else "") + (f"+{bld}" if bld else ""),
    st.integers(0, 3),
    st.sampled_from(["", "1", "2", "10", "alpha", "alpha.1", "rc.1"]),
    st.sampled_from(["", "exp.1", "20261122"]),
)

@given(ver_strat, ver_strat, ver_strat)
def test_antisymmetry_transitivity_and_build_stripping(x: str, y: str, z: str):
    assert semver_compare_fixed(x, x.split("+")[0]) == 0
    assert semver_compare_fixed(x, y) == -semver_compare_fixed(y, x)
    if semver_compare_fixed(x, y) <= 0 and semver_compare_fixed(y, z) <= 0:
