import pytest
from hypothesis import settings, strategies as st
from hypothesis.stateful import RuleBasedStateMachine, invariant, rule, run_state_machine_as_test

class IdempotencyConflictError(Exception):
    pass

class InsufficientFundsError(Exception):
    pass

class BuggyLedger:
    def __init__(self, init_balances: dict[str, int]):
        self.bal = dict(init_balances)
        self.seen: dict[str, int] = {}
        self.seq = 0

    def transfer(self, idem_key: str, src: str, dst: str, amount: int) -> int:
        if idem_key in self.seen:
            return self.seen[idem_key]
        self.bal[src] -= amount
        self.bal[dst] += amount
        self.seq += 1
        self.seen[idem_key] = self.seq
        return self.seq

class FixedIdempotentLedger:
    def __init__(self, init_balances: dict[str, int]):
        self.bal = dict(init_balances)
        self.records: dict[str, tuple[tuple[str, str, int], int]] = {}
        self.seq = 0

    def transfer(self, idem_key: str, src: str, dst: str, amount: int) -> int:
        if isinstance(amount, bool) or amount <= 0:
            raise ValueError("amount must be positive integer")
        fingerprint = (src, dst, amount)
        if idem_key in self.records:
            orig_fp, tx_id = self.records[idem_key]
            if orig_fp != fingerprint:
                raise IdempotencyConflictError("Idempotency key reused with mutated payload")
            return tx_id

        if self.bal.get(src, 0) < amount:
            raise InsufficientFundsError(src)
        if src != dst:
            self.bal[src] -= amount
            self.bal[dst] = self.bal.get(dst, 0) + amount
        self.seq += 1
        self.records[idem_key] = (fingerprint, self.seq)
        return self.seq

def test_red_green_mutated_payload_on_replayed_idempotency_key():
    buggy = BuggyLedger({"alice": 1000, "bob": 0})
    tx_first = buggy.transfer("k_one", "alice", "bob", 10)
    assert buggy.transfer("k_one", "alice", "bob", 500) == tx_first

    fixed = FixedIdempotentLedger({"alice": 1000, "bob": 0})
    ftx = fixed.transfer("k_one", "alice", "bob", 10)
    assert fixed.transfer("k_one", "alice", "bob", 10) == ftx
    assert fixed.bal == {"alice": 990, "bob": 10}
    with pytest.raises(IdempotencyConflictError):
        fixed.transfer("k_one", "alice", "bob", 500)

class LedgerStateMachine(RuleBasedStateMachine):
    def __init__(self):
        super().__init__()
        self.ledger = FixedIdempotentLedger({"a": 500, "b": 500, "c": 500})
        self.committed: dict[str, tuple[str, str, int, int]] = {}

    @rule(
        key=st.sampled_from(["k_a", "k_b", "k_c", "k_d"]),
        src=st.sampled_from(["a", "b", "c"]),
        dst=st.sampled_from(["a", "b", "c"]),
        amt=st.integers(1, 300),
    )
    def op_transfer(self, key: str, src: str, dst: str, amt: int):
        if key in self.committed:
            osrc, odst, oamt, otx = self.committed[key]
            if (osrc, odst, oamt) == (src, dst, amt):
                assert self.ledger.transfer(key, src, dst, amt) == otx
            else:
                with pytest.raises(IdempotencyConflictError):
                    self.ledger.transfer(key, src, dst, amt)
        else:
            try:
                tx = self.ledger.transfer(key, src, dst, amt)
                self.committed[key] = (src, dst, amt, tx)
            except InsufficientFundsError:
                pass

    @invariant()
    def total_money_conserved_and_non_negative(self):
        assert sum(self.ledger.bal.values()) == 1500
        assert all(v >= 0 for v in self.ledger.bal.values())

def test_stateful_idempotent_ledger():
    run_state_machine_as_test(LedgerStateMachine, settings=settings(max_examples=50, stateful_step_count=25))
