// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "forge-std/Test.sol";

contract DustSafeCDP {
    uint256 public constant MIN_DEBT = 100e18;
    bool public immutable enforceDustFloor;
    mapping(address => uint256) public debtOf;
    mapping(address => bool) public isUnderwater;

    error BelowMinDebtFloor();
    error NotLiquidatable();

    constructor(bool _fix) { enforceDustFloor = _fix; }

    function borrow(uint256 amount) external {
        uint256 next = debtOf[msg.sender] + amount;
        if (next < MIN_DEBT) revert BelowMinDebtFloor();
        debtOf[msg.sender] = next;
    }

    function flagUnderwater(address user, bool status) external {
        isUnderwater[user] = status;
    }

    function repay(uint256 amount) external {
        uint256 cur = debtOf[msg.sender];
        uint256 next = cur - amount;
        if (enforceDustFloor && next > 0 && next < MIN_DEBT) revert BelowMinDebtFloor();
        debtOf[msg.sender] = next;
    }

    function liquidate(address user, uint256 repayAmt) external {
        if (!isUnderwater[user]) revert NotLiquidatable();
        uint256 cur = debtOf[user];
        uint256 next = cur - repayAmt;
        if (enforceDustFloor && next > 0 && next < MIN_DEBT) revert BelowMinDebtFloor();
        debtOf[user] = next;
        if (next == 0) isUnderwater[user] = false;
    }
}

contract CdpHandler is Test {
    DustSafeCDP public cdp;
    address[] public users;

    constructor(DustSafeCDP _c) {
        cdp = _c;
        users.push(address(0xA11CE));
        users.push(address(0xB0B));
    }

    function actionBorrow(uint8 uIdx, uint96 rawAmt) external {
        address u = users[uIdx % users.length];
        uint256 amt = bound(uint256(rawAmt), 1e18, 500e18);
        vm.prank(u);
        try cdp.borrow(amt) {} catch {}
    }

    function actionRepay(uint8 uIdx, uint96 rawAmt) external {
        address u = users[uIdx % users.length];
        uint256 d = cdp.debtOf(u);
        if (d == 0) return;
        uint256 amt = bound(uint256(rawAmt), 1, d);
        vm.prank(u);
        try cdp.repay(amt) {} catch {}
    }

    function actionLiquidate(uint8 uIdx, uint96 rawAmt) external {
        address u = users[uIdx % users.length];
        uint256 d = cdp.debtOf(u);
        if (d == 0) return;
        cdp.flagUnderwater(u, true);
        uint256 amt = bound(uint256(rawAmt), 1, d);
        try cdp.liquidate(u, amt) {} catch {}
    }
}

contract CdpDustFloorInvariantTest is Test {
