class BoundedLogBuf {
public:
    explicit BoundedLogBuf(size_t cap) : buf_(cap, '\0'), cap_(cap) {}

    void append_kv(const char* k, const char* v) {
        if (cap_ == 0 || pos_ >= cap_ - 1) return;
        size_t rem = cap_ - pos_;
        int n = std::snprintf(buf_.data() + pos_, rem, "%s=%s;", k, v);
        if (n < 0) {
