            return;
        }
        if (static_cast<size_t>(n) >= rem) {
            pos_ = cap_ - 1;
        } else {
            pos_ += static_cast<size_t>(n);
        }
    }

    std::string_view view() const { return std::string_view(buf_.data(), pos_); }
    size_t cursor() const { return pos_; }

