#include <cassert>
#include <cstddef>
#include <cstdint>
#include <optional>
#include <string>
#include <string_view>

static std::optional<size_t> parse_bstr_slice(std::string_view buf, size_t pos, std::string_view* out_str) {
    if (pos >= buf.size() || buf[pos] < '0' || buf[pos] > '9') return std::nullopt;
    size_t colon = buf.find(':', pos);
    if (colon == std::string_view::npos) return std::nullopt;
    std::string_view num = buf.substr(pos, colon - pos);
    if (num.size() > 1 && num[0] == '0') return std::nullopt;
    size_t len = 0;
    for (char c : num) {
        if (c < '0' || c > '9') return std::nullopt;
        size_t d = static_cast<size_t>(c - '0');
        if (len > (buf.size() - d) / 10) return std::nullopt;
        len = len * 10 + d;
    }
    if (len > buf.size() - (colon + 1)) return std::nullopt;
    *out_str = buf.substr(colon + 1, len);
    return colon + 1 + len;
}

static std::optional<size_t> validate_node(std::string_view buf, size_t pos, size_t depth, size_t max_depth) {
    if (depth > max_depth || pos >= buf.size()) return std::nullopt;
    char tag = buf[pos];
    if (tag == 'i') {
        size_t end = buf.find('e', pos + 1);
        if (end == std::string_view::npos) return std::nullopt;
        std::string_view raw = buf.substr(pos + 1, end - (pos + 1));
        if (raw.empty() || raw == "-" || raw == "-0") return std::nullopt;
        size_t start = (raw[0] == '-') ? 1 : 0;
        if (raw.size() - start > 1 && raw[start] == '0') return std::nullopt;
        for (size_t i = start; i < raw.size(); ++i) {
            if (raw[i] < '0' || raw[i] > '9') return std::nullopt;
        }
        return end + 1;
    }
    if (tag == 'l') {
        size_t cur = pos + 1;
        while (cur < buf.size() && buf[cur] != 'e') {
            auto nxt = validate_node(buf, cur, depth + 1, max_depth);
            if (!nxt.has_value()) return std::nullopt;
            cur = *nxt;
        }
        if (cur >= buf.size()) return std::nullopt;
        return cur + 1;
    }
    if (tag == 'd') {
        size_t cur = pos + 1;
        std::optional<std::string_view> prev_key;
        while (cur < buf.size() && buf[cur] != 'e') {
            std::string_view key;
            auto after_key = parse_bstr_slice(buf, cur, &key);
            if (!after_key.has_value()) return std::nullopt;
            if (prev_key.has_value() && key <= *prev_key) return std::nullopt;
            prev_key = key;
            auto after_val = validate_node(buf, *after_key, depth + 1, max_depth);
            if (!after_val.has_value()) return std::nullopt;
            cur = *after_val;
        }
        if (cur >= buf.size()) return std::nullopt;
        return cur + 1;
    }
    std::string_view dummy;
    return parse_bstr_slice(buf, pos, &dummy);
}

bool validate_bencode_canonical(std::string_view buf, size_t max_depth) {
    auto end = validate_node(buf, 0, 0, max_depth);
    return end.has_value() && *end == buf.size();
}

void red_green_bencode_canonical_vectors_proof() {
    assert(!validate_bencode_canonical("i-0e", 16));
    assert(!validate_bencode_canonical("i04e", 16));
    assert(!validate_bencode_canonical("03:abc", 16));
    assert(!validate_bencode_canonical("di8e1:xe", 16));
    assert(!validate_bencode_canonical("d1:z1:x1:a1:ye", 16));
    assert(!validate_bencode_canonical(std::string(50000, 'l'), 32));
    assert(validate_bencode_canonical("d1:a3:foo1:bi-42ee", 16));
}

