use std::collections::VecDeque;
use proptest::prelude::*;

pub fn sliding_max_buggy_values(nums: &[i64], k: usize) -> Vec<i64> {
    let mut q: VecDeque<i64> = VecDeque::new();
    let mut out = Vec::new();
    for i in 0..nums.len() {
        while q.back().map_or(false, |&b| b <= nums[i]) {
            q.pop_back();
        }
        q.push_back(nums[i]);
        if i >= k && q.front() == Some(&nums[i - k]) {
            q.pop_front();
        }
        if i + 1 >= k {
            out.push(*q.front().unwrap());
        }
    }
    out
}

pub fn sliding_max_fixed(nums: &[i64], k: usize) -> Vec<i64> {
    if k == 0 || nums.is_empty() || k > nums.len() {
        return Vec::new();
    }
    let mut q: VecDeque<(usize, i64)> = VecDeque::with_capacity(k);
    let mut out = Vec::with_capacity(nums.len() - k + 1);

    for (i, &x) in nums.iter().enumerate() {
        if let Some(&(front_idx, _)) = q.front() {
            if i >= k && front_idx <= i - k {
                q.pop_front();
            }
        }
        while q.back().map_or(false, |&(_, back_val)| back_val <= x) {
            q.pop_back();
        }
        q.push_back((i, x));
        if i + 1 >= k {
            out.push(q.front().unwrap().1);
        }
    }
    out
}

