pub fn apply_batch_buggy(state: &mut BTreeMap<String, Option<String>>, batch: &[LogOp]) {
    for op in batch {
        match &op.kind {
            OpKind::Delete => { state.insert(op.key.clone(), None); }
            OpKind::Put(v) => { state.insert(op.key.clone(), Some(v.clone())); }
