import bisect
import hashlib
import pytest
from hypothesis import given, strategies as st

def _ring_hash(raw: str) -> int:
    return int.from_bytes(hashlib.blake2b(raw.encode("utf-8"), digest_size=8).digest(), "big")

class BuggyRing:
    def __init__(self, nodes: list[str]):
        self.ring = sorted((_ring_hash(n), n) for n in nodes)
        self.hashes = [h for h, _ in self.ring]

    def route_raw_hash(self, h: int) -> str:
        idx = bisect.bisect_left(self.hashes, h)
        return self.ring[idx][1]

class ConsistentRing:
    def __init__(self, vnodes: int = 8):
        self.vnodes = vnodes
        self.ring: list[tuple[int, str]] = []
        self.hashes: list[int] = []

    def add_node(self, node: str) -> None:
