        for v in range(self.vnodes):
            h = _ring_hash(f"{node}#{v}")
            ins = bisect.bisect_left(self.ring, (h, node))
            self.ring.insert(ins, (h, node))
        self.hashes = [h for h, _ in self.ring]

    def remove_node(self, node: str) -> None:
        self.ring = [(h, n) for h, n in self.ring if n != node]
        self.hashes = [h for h, _ in self.ring]

    def route_hash(self, h: int) -> str:
        if not self.ring:
            raise LookupError("ConsistentRing is empty")
        idx = bisect.bisect_left(self.hashes, h) % len(self.ring)
        return self.ring[idx][1]

