import fc from 'fast-check';
import { describe, it, expect } from 'vitest';

const IDENT_RE = /^[a-z_][a-z0-9_]{0,62}$/;
const PG_MAX_PARAMS = 65535;

export function buildInBuggy(col: string, items: readonly unknown[], params: unknown[]): string {
  const placeholders = items.map((_, i) => `$${i + 1}`).join(', ');
  params.push(...items);
  return `${col} IN (${placeholders})`;
}

export function appendWhereInFixed(
  col: string,
  items: readonly unknown[],
  params: unknown[]
): string {
  if (!IDENT_RE.test(col)) {
    throw new Error(`Unsafe SQL column identifier: ${col}`);
  }
  if (items.length === 0) {
    return 'FALSE';
  }
  if (params.length + items.length > PG_MAX_PARAMS) {
    throw new RangeError(`PostgreSQL bind parameter limit (${PG_MAX_PARAMS}) exceeded`);
  }
  const startIdx = params.length + 1;
  const slots: string[] = new Array(items.length);
  for (let i = 0; i < items.length; i++) {
    slots[i] = `$${startIdx + i}`;
    params.push(items[i]);
  }
  return `${col} IN (${slots.join(', ')})`;
}

describe('appendWhereInFixed empty-list, parameter-offset & 65535-cap suite', () => {
  it('red-green proof: offsets $2,$3 after tenant $1, emits FALSE on [], and blocks >65535 binds', () => {
    expect(buildInBuggy('status', [], [])).toBe('status IN ()');
    const badParams: unknown[] = ['org_acme'];
    expect(buildInBuggy('id', [10, 20], badParams)).toBe('id IN ($1, $2)');

    const okParams: unknown[] = ['org_acme'];
    expect(appendWhereInFixed('status', [], okParams)).toBe('FALSE');
    expect(okParams).toEqual(['org_acme']);

    expect(appendWhereInFixed('id', [10, 20], okParams)).toBe('id IN ($2, $3)');
    expect(okParams).toEqual(['org_acme', 10, 20]);

    const nearMax = new Array<unknown>(65534).fill(1);
    expect(() => appendWhereInFixed('id', [2, 3], nearMax)).toThrow(RangeError);
    expect(() => appendWhereInFixed('id; DROP TABLE users--', [1], [])).toThrow(/Unsafe/);
  });

  it('maps every emitted $k placeholder 1-to-1 to params[k - 1] across chained clauses', () => {
    fc.assert(
      fc.property(
        fc.array(fc.string(), { minLength: 0, maxLength: 5 }),
        fc.array(fc.integer(), { minLength: 0, maxLength: 10 }),
        (initialBinds, inItems) => {
          const params: unknown[] = [...initialBinds];
          const sql = appendWhereInFixed('item_id', inItems, params);

          if (inItems.length === 0) {
            expect(sql).toBe('FALSE');
            expect(params).toEqual(initialBinds);
          } else {
            const matches = Array.from(sql.matchAll(/\$(\d+)/g), (m) => Number(m[1]));
            expect(matches.length).toBe(inItems.length);
            const resolved = matches.map((idx1) => params[idx1 - 1]);
            expect(resolved).toEqual(inItems);
          }
        }
      )
    );
  });
});
