use std::collections::HashSet;
use std::net::IpAddr;
use proptest::prelude::*;

pub fn parse_xff_hop(raw: &str) -> Option<IpAddr> {
    let s = raw.trim();
    if s.is_empty() {
        return None;
    }
    if let Some(rest) = s.strip_prefix('[') {
        let (v6_str, tail) = rest.split_once(']')?;
        if !tail.is_empty() {
            let port_str = tail.strip_prefix(':')?;
            let _: u16 = port_str.parse().ok()?;
        }
        return v6_str.parse::<IpAddr>().ok().filter(IpAddr::is_ipv6);
    }
    if let Ok(ip) = s.parse::<IpAddr>() {
        return Some(ip);
    }
    let (host, port_str) = s.split_once(':')?;
    if port_str.contains(':') {
        return None;
    }
    let _: u16 = port_str.parse().ok()?;
    host.parse::<IpAddr>().ok().filter(IpAddr::is_ipv4)
