pub fn extract_ip_buggy_leftmost(xff: &str, peer: IpAddr) -> IpAddr {
    xff.split(',')
        .next()
        .and_then(|s| s.trim().split(':').next())
        .and_then(|s| s.parse().ok())
        .unwrap_or(peer)
}

pub fn real_client_ip(
    xff_opt: Option<&str>,
    peer_ip: IpAddr,
    trusted: &HashSet<IpAddr>,
) -> IpAddr {
