use proptest::prelude::*;

pub fn mul_wide_buggy(a: u128, b: u128) -> (u128, u128) {
    let mask = u64::MAX as u128;
    let (a_lo, a_hi) = (a & mask, a >> 64);
    let (b_lo, b_hi) = (b & mask, b >> 64);

    let ll = a_lo * b_lo;
    let hh = a_hi * b_hi;
    let mid = (a_lo * b_hi).wrapping_add(a_hi * b_lo);
    let (lo, c) = ll.overflowing_add(mid << 64);
    let hi = hh + (mid >> 64) + (c as u128);
    (lo, hi)
}

pub fn mul_wide_fixed(a: u128, b: u128) -> (u128, u128) {
    let mask = u64::MAX as u128;
    let (a_lo, a_hi) = (a & mask, a >> 64);
    let (b_lo, b_hi) = (b & mask, b >> 64);

    let ll = a_lo * b_lo;
    let hh = a_hi * b_hi;
    let (mid, mid_overflow) = (a_lo * b_hi).overflowing_add(a_hi * b_lo);
    let (lo, lo_carry) = ll.overflowing_add(mid << 64);
    let hi = hh
        + (mid >> 64)
        + (lo_carry as u128)
        + ((mid_overflow as u128) << 64);
    (lo, hi)
}

fn mul_wide_oracle_limbs(a: u128, b: u128) -> (u128, u128) {
    let mut aa = [0_u64; 4];
    let mut bb = [0_u64; 4];
    for i in 0..4 {
        aa[i] = ((a >> (i * 32)) & 0xFFFF_FFFF) as u64;
        bb[i] = ((b >> (i * 32)) & 0xFFFF_FFFF) as u64;
    }
    let mut prod = [0_u64; 8];
    for i in 0..4 {
        let mut carry = 0_u64;
        for j in 0..4 {
            let t = prod[i + j] + aa[i] * bb[j] + carry;
            prod[i + j] = t & 0xFFFF_FFFF;
            carry = t >> 32;
        }
        prod[i + 4] += carry;
    }
    let mut lo = 0_u128;
    let mut hi = 0_u128;
    for i in 0..4 {
        lo |= (prod[i] as u128) << (i * 32);
        hi |= (prod[i + 4] as u128) << (i * 32);
    }
    (lo, hi)
}

