import fc from 'fast-check';
import { describe, it, expect } from 'vitest';

export function resolveRangeBuggy(hdr: string, totalSize: number): { start: number; end: number } | null {
  const m = /^bytes=(\d*)-(\d*)$/.exec(hdr);
  if (!m) return null;
  if (m[1] === '') {
    const suffix = Number(m[2]);
    return { start: totalSize - suffix, end: totalSize - 1 };
  }
  const start = Number(m[1]);
  const end = m[2] === '' ? totalSize - 1 : Math.min(Number(m[2]), totalSize - 1);
  return { start, end: m[2] === '0' && totalSize === 0 ? 0 : end };
}

export function resolveByteRangeFixed(
  hdr: string,
  totalSize: number
): { start: number; end: number } | null {
  if (!Number.isSafeInteger(totalSize) || totalSize <= 0) {
    return null;
  }
  const m = /^bytes=(\d*)-(\d*)$/.exec(hdr);
  if (!m || (m[1] === '' && m[2] === '')) {
    return null;
  }
  if (m[1] === '') {
    const suffix = Number(m[2]);
    if (!Number.isSafeInteger(suffix) || suffix <= 0) {
      return null;
    }
    const take = Math.min(suffix, totalSize);
    return { start: totalSize - take, end: totalSize - 1 };
  }
  const start = Number(m[1]);
  if (!Number.isSafeInteger(start) || start >= totalSize) {
    return null;
  }
  if (m[2] === '') {
    return { start, end: totalSize - 1 };
  }
  const rawEnd = Number(m[2]);
  if (!Number.isSafeInteger(rawEnd) || rawEnd < start) {
    return null;
  }
  return { start, end: Math.min(rawEnd, totalSize - 1) };
}

describe('resolveByteRangeFixed RFC 9110 suffix-clamp & zero-file fuzzing', () => {
  it('red-green proof: rejects empty-file bytes=0-0, bytes=-0, and clamps oversized suffix bytes=-500', () => {
    expect(resolveRangeBuggy('bytes=0-0', 0)).toEqual({ start: 0, end: 0 });
    expect(resolveRangeBuggy('bytes=-500', 100)).toEqual({ start: -400, end: 99 });
    expect(resolveRangeBuggy('bytes=-0', 100)).toEqual({ start: 100, end: 99 });

    expect(resolveByteRangeFixed('bytes=0-0', 0)).toBeNull();
    expect(resolveByteRangeFixed('bytes=-0', 100)).toBeNull();
    expect(resolveByteRangeFixed('bytes=-500', 100)).toEqual({ start: 0, end: 99 });
    expect(resolveByteRangeFixed('bytes=50-500', 100)).toEqual({ start: 50, end: 99 });
  });

  it('always yields valid non-empty subarray bounds [0 <= start <= end < totalSize]', () => {
    const specPart = fc.constantFrom('', '0', '1', '50', '99', '100', '500');
    const hdrArb = fc.tuple(specPart, specPart).map(([a, b]) => `bytes=${a}-${b}`);
    const sizeArb = fc.constantFrom(0, 1, 50, 100);

    fc.assert(
      fc.property(hdrArb, sizeArb, (hdr, size) => {
        const r = resolveByteRangeFixed(hdr, size);
        if (size === 0) {
          expect(r).toBeNull();
        } else if (r !== null) {
          expect(r.start).toBeGreaterThanOrEqual(0);
          expect(r.end).toBeGreaterThanOrEqual(r.start);
          expect(r.end).toBeLessThan(size);
