import fc from 'fast-check';
import { describe, it, expect } from 'vitest';

export interface RpcResponse {
  jsonrpc: '2.0';
  id: string | number | null;
  result?: unknown;
  error?: { code: number; message: string };
}

export function dispatchBuggy(req: Record<string, unknown>): RpcResponse | undefined {
  if (!req.id) return undefined;
  return { jsonrpc: '2.0', id: req.id as string | number, result: 'pong' };
}

function handleSingleRpc(item: unknown): RpcResponse | undefined {
  if (typeof item !== 'object' || item === null || Array.isArray(item)) {
    return { jsonrpc: '2.0', id: null, error: { code: -32600, message: 'Invalid Request' } };
  }
  const rec = item as Record<string, unknown>;
  const hasId = Object.prototype.hasOwnProperty.call(rec, 'id');
  const rawId = rec['id'];
  const validId =
    !hasId ||
    rawId === null ||
    typeof rawId === 'string' ||
    (typeof rawId === 'number' && Number.isFinite(rawId));

  if (rec['jsonrpc'] !== '2.0' || typeof rec['method'] !== 'string' || rec['method'] === '' || !validId) {
    const respId = hasId && (typeof rawId === 'string' || (typeof rawId === 'number' && Number.isFinite(rawId))) ? rawId : null;
    return { jsonrpc: '2.0', id: respId, error: { code: -32600, message: 'Invalid Request' } };
  }
  if (!hasId) {
    return undefined;
  }
  return {
    jsonrpc: '2.0',
    id: Object.is(rawId, -0) ? 0 : (rawId as string | number | null),
    result: `ok:${rec['method']}`,
  };
}

export function dispatchJsonRpcFixed(payload: unknown): RpcResponse | RpcResponse[] | undefined {
  if (Array.isArray(payload)) {
    if (payload.length === 0) {
      return { jsonrpc: '2.0', id: null, error: { code: -32600, message: 'Empty batch' } };
    }
    const responses: RpcResponse[] = [];
    for (const item of payload) {
      const r = handleSingleRpc(item);
      if (r !== undefined) responses.push(r);
    }
    return responses.length === 0 ? undefined : responses;
  }
  return handleSingleRpc(payload);
}

describe('dispatchJsonRpcFixed id=0, id="", id=null & empty-batch conformance', () => {
  it('red-green proof: responds to id=0, id="", id=null, rejects [], and silences pure-notification batches', () => {
    const reqZero = { jsonrpc: '2.0', method: 'ping', id: 0 };
    expect(dispatchBuggy(reqZero)).toBeUndefined();

    expect(dispatchJsonRpcFixed(reqZero)).toEqual({ jsonrpc: '2.0', id: 0, result: 'ok:ping' });
    expect(dispatchJsonRpcFixed({ jsonrpc: '2.0', method: 'ping', id: '' })).toEqual({
      jsonrpc: '2.0',
      id: '',
      result: 'ok:ping',
