// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "forge-std/Test.sol";

contract CanonicalRlpUint {
    error NonCanonicalRlp();

    function encodeUint(uint256 v) public pure returns (bytes memory) {
        if (v == 0) {
            return hex"80";
        }
        if (v < 0x80) {
            return abi.encodePacked(uint8(v));
        }
        uint256 tmp = v;
        uint256 byteLen = 0;
        while (tmp != 0) {
            byteLen++;
            tmp >>= 8;
        }
        bytes memory out = new bytes(1 + byteLen);
        out[0] = bytes1(uint8(0x80 + byteLen));
        tmp = v;
        for (uint256 i = byteLen; i > 0; i--) {
            out[i] = bytes1(uint8(tmp));
            tmp >>= 8;
        }
        return out;
    }

    function decodeBuggy(bytes calldata rlp) external pure returns (uint256 v) {
        if (rlp.length == 1 && uint8(rlp[0]) < 0x80) return uint8(rlp[0]);
        uint8 pfx = uint8(rlp[0]);
        uint256 len = pfx - 0x80;
        for (uint256 i = 0; i < len; i++) {
            v = (v << 8) | uint8(rlp[1 + i]);
        }
    }

    function decodeCanonical(bytes calldata rlp) public pure returns (uint256 v) {
        if (rlp.length == 0) revert NonCanonicalRlp();
        uint8 b0 = uint8(rlp[0]);
        if (b0 == 0x80) {
            if (rlp.length != 1) revert NonCanonicalRlp();
            return 0;
        }
        if (b0 < 0x80) {
            if (b0 == 0x00 || rlp.length != 1) revert NonCanonicalRlp();
            return uint256(b0);
        }
        if (b0 > 0xA0) {
            revert NonCanonicalRlp();
        }
        uint256 len = uint256(b0 - 0x80);
        if (rlp.length != 1 + len) revert NonCanonicalRlp();
        uint8 firstPayload = uint8(rlp[1]);
        if (firstPayload == 0) revert NonCanonicalRlp();
        if (len == 1 && firstPayload < 0x80) revert NonCanonicalRlp();

        for (uint256 i = 0; i < len; i++) {
            v = (v << 8) | uint8(rlp[1 + i]);
        }
    }
}

contract CanonicalRlpUintTest is Test {
