#include <cassert>
#include <cstddef>
#include <cstdint>
#include <limits>
#include <optional>
#include <vector>

std::vector<uint8_t> encode_ssh_mpint_i64(int64_t v) {
    if (v == 0) {
        return {0, 0, 0, 0};
    }
    uint64_t u = static_cast<uint64_t>(v);
    uint8_t raw[9];
    raw[0] = (v < 0) ? 0xFF : 0x00;
    for (int i = 0; i < 8; ++i) {
        raw[1 + i] = static_cast<uint8_t>((u >> ((7 - i) * 8)) & 0xFF);
    }
    size_t start = 0;
    while (start < 8) {
        if (raw[start] == 0x00 && (raw[start + 1] & 0x80) == 0) {
            ++start;
        } else if (raw[start] == 0xFF && (raw[start + 1] & 0x80) != 0) {
            ++start;
        } else {
            break;
        }
    }
    uint32_t len = static_cast<uint32_t>(9 - start);
    std::vector<uint8_t> out = {
        static_cast<uint8_t>(len >> 24),
        static_cast<uint8_t>(len >> 16),
        static_cast<uint8_t>(len >> 8),
        static_cast<uint8_t>(len)
    };
    out.insert(out.end(), raw + start, raw + 9);
    return out;
}

std::optional<int64_t> decode_ssh_mpint_fixed(const uint8_t* p, size_t n) {
    if (n < 4) return std::nullopt;
    uint32_t len = (static_cast<uint32_t>(p[0]) << 24)
                 | (static_cast<uint32_t>(p[1]) << 16)
                 | (static_cast<uint32_t>(p[2]) << 8)
                 | static_cast<uint32_t>(p[3]);
    if (len > 8 || static_cast<size_t>(4 + len) != n) return std::nullopt;
    if (len == 0) return static_cast<int64_t>(0);

    const uint8_t* b = p + 4;
    if (len == 1 && b[0] == 0x00) return std::nullopt;
    if (len > 1 && b[0] == 0x00 && (b[1] & 0x80) == 0) return std::nullopt;
    if (len > 1 && b[0] == 0xFF && (b[1] & 0x80) != 0) return std::nullopt;

    uint64_t acc = ((b[0] & 0x80) != 0) ? UINT64_MAX : 0;
    for (uint32_t i = 0; i < len; ++i) {
        acc = (acc << 8) | b[i];
    }
    return static_cast<int64_t>(acc);
}

void red_green_ssh_mpint_padding_proof() {
    const uint8_t kOneByteZero[] = {0, 0, 0, 1, 0x00};
    const uint8_t kRedundantPos[] = {0, 0, 0, 2, 0x00, 0x7F};
    const uint8_t kRedundantNeg[] = {0, 0, 0, 2, 0xFF, 0x80};
    assert(!decode_ssh_mpint_fixed(kOneByteZero, sizeof(kOneByteZero)).has_value());
    assert(!decode_ssh_mpint_fixed(kRedundantPos, sizeof(kRedundantPos)).has_value());
    assert(!decode_ssh_mpint_fixed(kRedundantNeg, sizeof(kRedundantNeg)).has_value());

    for (int64_t v : {int64_t(0), int64_t(128), int64_t(-128), std::numeric_limits<int64_t>::min(), std::numeric_limits<int64_t>::max()}) {
        auto w = encode_ssh_mpint_i64(v);
        assert(decode_ssh_mpint_fixed(w.data(), w.size()) == v);
    }
}

extern "C" int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size) {
    static const bool once = (red_green_ssh_mpint_padding_proof(), true);
    (void)once;
    auto dec = decode_ssh_mpint_fixed(data, size);
    if (dec.has_value()) {
        auto re = encode_ssh_mpint_i64(*dec);
