```rust
use std::collections::{BTreeMap, BTreeSet};
use proptest::prelude::*;

#[derive(Debug, Clone)]
pub enum Selection {
    Field { sub: Vec<Selection> },
    FragmentSpread(String),
}

#[derive(Debug, PartialEq, Eq)]
pub enum GqlLimitErr {
    UnknownFragment,
    FragmentCycle,
    MaxDepthExceeded,
    MaxFieldsExceeded,
}

pub fn validate_gql_limits(
    fragments: &BTreeMap<String, Vec<Selection>>,
    root: &[Selection],
    max_depth: usize,
    max_fields: usize,
) -> Result<usize, GqlLimitErr> {
    let mut total_fields = 0_usize;

    fn walk<'a>(
        frags: &'a BTreeMap<String, Vec<Selection>>,
        sels: &'a [Selection],
        depth: usize,
        max_d: usize,
        max_f: usize,
        active_frags: &mut BTreeSet<&'a str>,
        count: &mut usize,
    ) -> Result<(), GqlLimitErr> {
        for sel in sels {
            match sel {
                Selection::Field { sub } => {
                    let next_d = depth + 1;
                    if next_d > max_d {
                        return Err(GqlLimitErr::MaxDepthExceeded);
                    }
                    *count += 1;
                    if *count > max_f {
                        return Err(GqlLimitErr::MaxFieldsExceeded);
                    }
                    if !sub.is_empty() {
                        walk(frags, sub, next_d, max_d, max_f, active_frags, count)?;
                    }
                }
                Selection::FragmentSpread(name) => {
                    let body = frags.get(name).ok_or(GqlLimitErr::UnknownFragment)?;
                    if !active_frags.insert(name.as_str()) {
                        return Err(GqlLimitErr::FragmentCycle);
                    }
                    walk(frags, body, depth, max_d, max_f, active_frags, count)?;
                    active_frags.remove(name.as_str());
                }
            }
        }
        Ok(())
    }

    let mut active = BTreeSet::new();
    walk(fragments, root, 0, max_depth, max_fields, &mut active, &mut total_fields)?;
    Ok(total_fields)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn red_green_fragment_cycle_and_diamond_alias_bomb_proof() {
        let mut cyc = BTreeMap::new();
        cyc.insert("A".into(), vec![Selection::FragmentSpread("B".into())]);
        cyc.insert("B".into(), vec![Selection::FragmentSpread("A".into())]);
        let root = vec![Selection::FragmentSpread("A".into())];
        assert_eq!(validate_gql_limits(&cyc, &root, 10, 100), Err(GqlLimitErr::FragmentCycle));

        let mut diamond = BTreeMap::new();
        diamond.insert("F0".into(), vec![Selection::Field { sub: vec![] }]);
        for i in 1..=8 {
            let prev = format!("F{}", i - 1);
            diamond.insert(
                format!("F{i}"),
                vec![Selection::FragmentSpread(prev.clone()), Selection::FragmentSpread(prev)],
            );
        }
        let bomb_root = vec![Selection::FragmentSpread("F8".into())];
        assert_eq!(validate_gql_limits(&diamond, &bomb_root, 5, 50), Err(GqlLimitErr::MaxFieldsExceeded));
        assert_eq!(validate_gql_limits(&diamond, &bomb_root, 5, 300), Ok(256));
    }

    proptest! {
        #[test]
        fn never_hangs_on_arbitrary_fragment_wiring(
            edges in prop::collection::vec((0_usize..4_usize, 0_usize..4_usize), 0..8)
        ) {
            let names = ["F0", "F1", "F2", "F3"];
            let mut frags: BTreeMap<String, Vec<Selection>> = BTreeMap::new();
            for n in names {
                frags.insert(n.into(), vec![Selection::Field { sub: vec![] }]);
            }
            for (src, dst) in edges {
                frags.get_mut(names[src]).unwrap().push(Selection::FragmentSpread(names[dst].into()));
            }
            let root = vec![Selection::FragmentSpread("F0".into())];
            let res = validate_gql_limits(&frags, &root, 6, 32);
            if let Ok(cnt) = res {
                prop_assert!(cnt <= 32);
            }
        }
    }
}
