import pytest
from hypothesis import given, strategies as st

INT64_MIN = -(1 << 63)
INT64_MAX = (1 << 63) - 1
MASK64 = 0xFFFFFFFFFFFFFFFF

def _put_uvarint(out: bytearray, u: int) -> None:
    while u > 0x7F:
        out.append((u & 0x7F) | 0x80)
        u >>= 7
    out.append(u)

def _get_uvarint(buf: bytes, pos: int) -> tuple[int, int]:
    u = 0
    for i in range(10):
        if pos + i >= len(buf):
            raise ValueError("Truncated varint")
        b = buf[pos + i]
        if i == 9 and b > 0x01:
            raise ValueError("Varint64 overflow")
        u |= (b & 0x7F) << (i * 7)
        if (b & 0x80) == 0:
            return u, pos + i + 1
    raise ValueError("Unterminated varint")

def _zz_enc(n: int) -> int:
    if not (INT64_MIN <= n <= INT64_MAX):
        raise OverflowError("Delta exceeds int64")
    return ((n << 1) ^ (n >> 63)) & MASK64

def _zz_dec(u: int) -> int:
    return (u >> 1) ^ -(u & 1)

def encode_ts_buggy_unsigned(ts: list[int]) -> bytes:
    out = bytearray()
    prev = 0
    for t in ts:
        d = t - prev
        if d < 0:
            raise ValueError("negative delta unsupported")
        _put_uvarint(out, d)
        prev = t
    return bytes(out)

def encode_ts_deltas_fixed(ts: list[int]) -> bytes:
    out = bytearray()
    _put_uvarint(out, len(ts))
    prev = 0
    for t in ts:
        if isinstance(t, bool) or not (INT64_MIN // 2 <= t <= INT64_MAX // 2):
            raise ValueError("Timestamp out of safe delta bounds")
        _put_uvarint(out, _zz_enc(t - prev))
        prev = t
    return bytes(out)

def decode_ts_deltas_fixed(buf: bytes, max_items: int = 10000) -> list[int]:
    count, pos = _get_uvarint(buf, 0)
    if count > max_items:
        raise ValueError("Count exceeds max_items")
    out = []
    prev = 0
    for _ in range(count):
        u, pos = _get_uvarint(buf, pos)
        cur = prev + _zz_dec(u)
        out.append(cur)
        prev = cur
    if pos != len(buf):
        raise ValueError("Trailing bytes in compressed series")
    return out

def test_red_green_out_of_order_negative_delta_and_empty_series():
    jittered = [1_700_000_100, 1_700_000_098, 1_700_000_098, 1_700_000_105]
    with pytest.raises(ValueError, match="negative"):
        encode_ts_buggy_unsigned(jittered)

    assert decode_ts_deltas_fixed(encode_ts_deltas_fixed(jittered)) == jittered
    assert decode_ts_deltas_fixed(encode_ts_deltas_fixed([])) == []
    assert decode_ts_deltas_fixed(encode_ts_deltas_fixed([0])) == [0]
    assert encode_ts_deltas_fixed([]) != encode_ts_deltas_fixed([0])

@given(st.lists(st.integers(-10**12, 10**12), min_size=0, max_size=40))
def test_lossless_roundtrip_on_unordered_timestamps(series: list[int]):
    wire = encode_ts_deltas_fixed(series)
    assert decode_ts_deltas_fixed(wire) == series
