import fc from 'fast-check';
import { describe, it, expect } from 'vitest';

const ISO_DUR_RE = /^P(?:(\d+)D)?(?:T(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)(?:\.(\d{1,3}))?S)?)?$/;

export function parseDurationBuggy(iso: string): number {
  const m = ISO_DUR_RE.exec(iso);
  if (!m) throw new Error('Bad duration');
  const sec = Number(m[4] ?? 0);
  const ms = m[5] ? Number(String(parseInt(m[5], 10)).padEnd(3, '0')) : 0;
  return (
    Number(m[1] ?? 0) * 86_400_000 +
    Number(m[2] ?? 0) * 3_600_000 +
    Number(m[3] ?? 0) * 60_000 +
    sec * 1_000 +
    ms
  );
