export function parseIsoDurationMs(iso: string): number {
  if (iso.endsWith('T')) {
    throw new Error('Trailing empty T designator in ISO-8601 duration');
  }
  const m = ISO_DUR_RE.exec(iso);
  if (!m) {
    throw new Error(`Invalid ISO-8601 duration: ${iso}`);
  }
  if (m[1] === undefined && m[2] === undefined && m[3] === undefined && m[4] === undefined) {
    throw new Error('ISO-8601 duration must contain at least one component');
  }
  const days = Number(m[1] ?? 0);
  const hours = Number(m[2] ?? 0);
  const mins = Number(m[3] ?? 0);
  const secs = Number(m[4] ?? 0);
  const ms = m[5] !== undefined ? Number(m[5].padEnd(3, '0')) : 0;

  const total =
    days * 86_400_000 +
    hours * 3_600_000 +
    mins * 60_000 +
    secs * 1_000 +
    ms;
  if (!Number.isSafeInteger(total)) {
    throw new RangeError('Duration milliseconds exceed MAX_SAFE_INTEGER');
  }
  return total;
}

export function formatMsToIsoDuration(totalMs: number): string {
  if (totalMs === 0) return 'PT0S';
  let rem = totalMs;
  const d = Math.floor(rem / 86_400_000); rem %= 86_400_000;
  const h = Math.floor(rem / 3_600_000); rem %= 3_600_000;
  const m = Math.floor(rem / 60_000); rem %= 60_000;
  const s = Math.floor(rem / 1_000);
  const ms = rem % 1_000;

  let out = 'P';
  if (d > 0) out += `${d}D`;
  if (h > 0 || m > 0 || s > 0 || ms > 0) {
    out += 'T';
    if (h > 0) out += `${h}H`;
    if (m > 0) out += `${m}M`;
    if (ms > 0) {
      const frac = String(ms).padStart(3, '0').replace(/0+$/, '');
      out += `${s}.${frac}S`;
    } else if (s > 0) {
      out += `${s}S`;
    }
  }
  return out;
}

describe('parseIsoDurationMs leading-fractional-zero & empty-designator suite', () => {
  it('red-green proof: parses PT0.05S as 50 milliseconds and rejects bare P / PT / P8DT', () => {
    expect(parseDurationBuggy('PT0.05S')).toBe(500);
    expect(parseDurationBuggy('P')).toBe(0);

    expect(parseIsoDurationMs('PT0.5S')).toBe(500);
    expect(parseIsoDurationMs('PT0.05S')).toBe(50);
    expect(parseIsoDurationMs('PT0.005S')).toBe(5);
    expect(() => parseIsoDurationMs('P')).toThrow();
    expect(() => parseIsoDurationMs('PT')).toThrow();
    expect(() => parseIsoDurationMs('P8DT')).toThrow();
