#include <cassert>
#include <cstddef>
#include <cstdint>
#include <optional>
#include <string>
#include <string_view>
#include <vector>

struct Tok {
    enum Kind { Star, QMark, Lit } kind;
    char ch;
};

static std::optional<std::vector<Tok>> compile_glob_tokens(std::string_view pat) {
    std::vector<Tok> out;
    for (size_t i = 0; i < pat.size(); ++i) {
        if (pat[i] == '\\') {
            if (i + 1 >= pat.size()) return std::nullopt;
            out.push_back({Tok::Lit, pat[++i]});
        } else if (pat[i] == '*') {
            if (out.empty() || out.back().kind != Tok::Star) {
                out.push_back({Tok::Star, 0});
            }
        } else if (pat[i] == '?') {
            out.push_back({Tok::QMark, 0});
        } else {
            out.push_back({Tok::Lit, pat[i]});
        }
    }
    return out;
}

size_t recursive_buggy_steps(std::string_view pat, std::string_view txt, size_t pi, size_t ti, size_t* steps) {
    ++(*steps);
    if (pi == pat.size()) return ti == txt.size() ? 1 : 0;
    if (pat[pi] == '*') {
        for (size_t k = ti; k <= txt.size(); ++k) {
            if (recursive_buggy_steps(pat, txt, pi + 1, k, steps)) return 1;
        }
        return 0;
    }
    if (ti < txt.size() && (pat[pi] == '?' || pat[pi] == txt[ti])) {
        return recursive_buggy_steps(pat, txt, pi + 1, ti + 1, steps);
    }
    return 0;
}

std::optional<bool> glob_match_linear(std::string_view pat, std::string_view txt, size_t* steps_out = nullptr) {
    auto toks_opt = compile_glob_tokens(pat);
    if (!toks_opt.has_value()) return std::nullopt;
    const auto& toks = *toks_opt;

    size_t pi = 0, ti = 0;
    size_t star_pi = static_cast<size_t>(-1), star_ti = 0;
    size_t steps = 0;

    while (ti < txt.size()) {
        ++steps;
        if (pi < toks.size() && (toks[pi].kind == Tok::QMark || (toks[pi].kind == Tok::Lit && toks[pi].ch == txt[ti]))) {
            ++pi;
            ++ti;
        } else if (pi < toks.size() && toks[pi].kind == Tok::Star) {
            star_pi = pi;
            star_ti = ti;
            ++pi;
        } else if (star_pi != static_cast<size_t>(-1)) {
            pi = star_pi + 1;
            ti = ++star_ti;
        } else {
            if (steps_out) *steps_out = steps;
            return false;
        }
    }
    while (pi < toks.size() && toks[pi].kind == Tok::Star) ++pi;
    if (steps_out) *steps_out = steps;
    return pi == toks.size();
}

void red_green_exponential_dos_and_dangling_escape_proof() {
    constexpr std::string_view kEvilPat = "*a*a*a*a*a*a*b";
    constexpr std::string_view kEvilTxt = "aaaaaaaaaaaa";
    size_t bug_steps = 0, fix_steps = 0;
    assert(recursive_buggy_steps(kEvilPat, kEvilTxt, 0, 0, &bug_steps) == 0);
    auto got = glob_match_linear(kEvilPat, kEvilTxt, &fix_steps);
    assert(bug_steps > 5000);
    assert(got == false && fix_steps <= 30);

    assert(!glob_match_linear("abc\\", "abc").has_value());
    assert(glob_match_linear("a\\*b", "a*b") == true);
    assert(glob_match_linear("a\\*b", "axxxb") == false);
}

extern "C" int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size) {
    static const bool once = (red_green_exponential_dos_and_dangling_escape_proof(), true);
    (void)once;
    if (size < 2) return 0;
    size_t split = data[0] % size;
    std::string_view pat(reinterpret_cast<const char*>(data + 1), split > 0 ? split - 1 : 0);
    std::string_view txt(reinterpret_cast<const char*>(data + 1 + pat.size()), size - 1 - pat.size());

    size_t steps = 0;
    auto res = glob_match_linear(pat, txt, &steps);
    if (res.has_value() && steps > (pat.size() + 1) * (txt.size() + 1) + 2) {
        __builtin_trap();
    }
    return 0;
}
