#include <cassert>
#include <cstddef>
#include <cstdint>
#include <optional>
#include <vector>

std::optional<std::vector<uint8_t>> decode_openpgp_new_body(
    const uint8_t* p,
    size_t n,
    size_t max_body
) {
    if (n < 2 || (p[0] & 0xC0) != 0xC0) return std::nullopt;
    size_t pos = 1;
    std::vector<uint8_t> out;

    while (true) {
        if (pos >= n) return std::nullopt;
        uint8_t b0 = p[pos++];
        bool is_partial = false;
        uint64_t chunk_len = 0;

        if (b0 < 192) {
            chunk_len = b0;
        } else if (b0 <= 223) {
            if (pos >= n) return std::nullopt;
            uint8_t b1 = p[pos++];
            chunk_len = (static_cast<uint64_t>(b0 - 192) << 8) + b1 + 192;
        } else if (b0 < 255) {
            is_partial = true;
            chunk_len = static_cast<uint64_t>(1U) << (b0 & 0x1F);
        } else {
            if (n - pos < 4) return std::nullopt;
            chunk_len = (static_cast<uint64_t>(p[pos]) << 24)
                      | (static_cast<uint64_t>(p[pos + 1]) << 16)
                      | (static_cast<uint64_t>(p[pos + 2]) << 8)
                      | static_cast<uint64_t>(p[pos + 3]);
            pos += 4;
        }

        if (chunk_len > n - pos || chunk_len > max_body - out.size()) {
            return std::nullopt;
        }
        out.insert(out.end(), p + pos, p + pos + static_cast<size_t>(chunk_len));
        pos += static_cast<size_t>(chunk_len);

        if (!is_partial) {
            if (pos != n) return std::nullopt;
            return out;
        }
    }
}

