use proptest::prelude::*;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Edit {
    Keep(usize),
    Delete(String),
    Insert(String),
}

pub fn roundtrip_buggy_lines(old: &str, new_txt: &str) -> String {
    let _old_l: Vec<&str> = old.lines().collect();
    let new_l: Vec<&str> = new_txt.lines().collect();
    new_l.join("\n")
}

pub fn build_line_patch(old: &str, new_txt: &str) -> Vec<Edit> {
    let a: Vec<&str> = old.split_inclusive('\n').collect();
    let b: Vec<&str> = new_txt.split_inclusive('\n').collect();

    let mut prefix = 0;
    while prefix < a.len() && prefix < b.len() && a[prefix] == b[prefix] {
        prefix += 1;
    }
    let mut a_end = a.len();
    let mut b_end = b.len();
    while a_end > prefix && b_end > prefix && a[a_end - 1] == b[b_end - 1] {
        a_end -= 1;
        b_end -= 1;
    }

    let mut ops = Vec::new();
    if prefix > 0 {
        ops.push(Edit::Keep(prefix));
    }
    for &del in &a[prefix..a_end] {
        ops.push(Edit::Delete(del.to_owned()));
    }
    for &ins in &b[prefix..b_end] {
        ops.push(Edit::Insert(ins.to_owned()));
    }
    if a.len() - a_end > 0 {
        ops.push(Edit::Keep(a.len() - a_end));
    }
    ops
}

pub fn apply_line_patch(old: &str, patch: &[Edit]) -> Result<String, &'static str> {
    let a: Vec<&str> = old.split_inclusive('\n').collect();
    let mut cur = 0;
    let mut out = String::new();

    for op in patch {
        match op {
            Edit::Keep(n) => {
                if cur + n > a.len() { return Err("Keep OOB"); }
                for &seg in &a[cur..cur + n] { out.push_str(seg); }
                cur += n;
            }
            Edit::Delete(expected) => {
                if a.get(cur) != Some(&expected.as_str()) {
                    return Err("Context mismatch on Delete");
                }
                cur += 1;
            }
            Edit::Insert(s) => out.push_str(s),
        }
    }
    if cur != a.len() {
        return Err("Unconsumed source lines");
    }
    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn red_green_trailing_newline_and_crlf_fidelity_proof() {
        let orig = "line1\nline2";
        let target = "line1\nline2\n";

        assert_ne!(roundtrip_buggy_lines(orig, target), target);

        let patch = build_line_patch(orig, target);
        assert_eq!(apply_line_patch(orig, &patch), Ok(target.to_owned()));
        assert!(apply_line_patch("tampered\nline2", &patch).is_err());
    }

    proptest! {
        #[test]
        fn byte_exact_diff_apply_bijection(
            old in prop::collection::vec(prop::sample::select(vec!["a", "b", "\n", "\r\n", ""]), 0..10)
                .prop_map(|v| v.join("")),
            new_txt in prop::collection::vec(prop::sample::select(vec!["a", "b", "\n", "\r\n", ""]), 0..10)
                .prop_map(|v| v.join("")),
        ) {
            let p = build_line_patch(&old, &new_txt);
            prop_assert_eq!(apply_line_patch(&old, &p), Ok(new_txt));
        }
    }
}
