```rust
use proptest::prelude::*;

#[derive(Debug, PartialEq, Eq)]
pub enum BloomCfgErr {
    InvalidFalsePositiveRate,
}

pub struct BloomFilter {
    words: Vec<u64>,
    m_bits: u64,
    k_hashes: u32,
}

pub fn slot_buggy(h1: u64, h2: u64, i: u32, m_bits: u64) -> u64 {
    (h1 + (i as u64) * h2) % m_bits
}

impl BloomFilter {
    pub fn with_rate(expected_items: usize, fp_rate: f64) -> Result<Self, BloomCfgErr> {
        if !fp_rate.is_finite() || fp_rate <= 0.0 || fp_rate >= 1.0 {
            return Err(BloomCfgErr::InvalidFalsePositiveRate);
        }
        let n = expected_items.max(1) as f64;
        let ln2 = std::f64::consts::LN_2;
        let raw_m = (-n * fp_rate.ln() / (ln2 * ln2)).ceil();
        let m_bits = (raw_m as u64).clamp(64, 1 << 26);
        let raw_k = ((m_bits as f64 / n) * ln2).round();
        let k_hashes = (raw_k as u32).clamp(1, 32);
        let num_words = ((m_bits + 63) / 64) as usize;
        Ok(Self { words: vec![0_u64; num_words], m_bits, k_hashes })
    }

    fn bit_slot(&self, h1: u64, h2: u64, i: u32) -> (usize, u64) {
        let combined = h1.wrapping_add((i as u64).wrapping_mul(h2));
        let bit = combined % self.m_bits;
        ((bit / 64) as usize, 1_u64 << (bit % 64))
    }

    pub fn insert_hashes(&mut self, h1: u64, h2: u64) {
        for i in 0..self.k_hashes {
            let (w, mask) = self.bit_slot(h1, h2, i);
            self.words[w] |= mask;
        }
    }

    pub fn might_contain_hashes(&self, h1: u64, h2: u64) -> bool {
        for i in 0..self.k_hashes {
            let (w, mask) = self.bit_slot(h1, h2, i);
            if (self.words[w] & mask) == 0 {
                return false;
            }
        }
        true
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn red_green_wrapping_double_hash_and_zero_items_config_proof() {
        assert!(std::panic::catch_unwind(|| slot_buggy(u64::MAX, u64::MAX, 2, 128)).is_err());

        for bad_p in [0.0, 1.0, -0.1, f64::NAN, f64::INFINITY] {
            assert!(BloomFilter::with_rate(100, bad_p).is_err());
        }
        let mut bf = BloomFilter::with_rate(0, 0.01).unwrap();
        bf.insert_hashes(u64::MAX, u64::MAX);
        assert!(bf.might_contain_hashes(u64::MAX, u64::MAX));
    }

    proptest! {
        #[test]
        fn zero_false_negatives_across_extreme_hash_pairs(
            n_est in 0_usize..500_usize,
            rate in 1e-6_f64..0.99_f64,
            inserted in prop::collection::vec((any::<u64>(), any::<u64>()), 1..30),
        ) {
            let mut bf = BloomFilter::with_rate(n_est, rate).unwrap();
            for &(h1, h2) in &inserted {
                bf.insert_hashes(h1, h2);
            }
            for &(h1, h2) in &inserted {
                prop_assert!(bf.might_contain_hashes(h1, h2));
            }
        }
    }
}
