import net from 'node:net';
import fc from 'fast-check';
import { describe, it, expect } from 'vitest';

function expandIpv6To8Hextets(v6: string): number[] {
  const host = new URL(`http://[${v6}]/`).hostname.slice(1, -1);
  const [left, right] = host.split('::');
  const lParts = left ? left.split(':').map((h) => parseInt(h, 16)) : [];
  const rParts = right !== undefined && right !== '' ? right.split(':').map((h) => parseInt(h, 16)) : [];
  if (right === undefined) return lParts;
  const zeros = new Array(8 - lParts.length - rParts.length).fill(0);
  return [...lParts, ...zeros, ...rParts];
}

export function rateLimitKeyBuggy(rawIp: string): string {
  if (net.isIP(rawIp) === 4) return `v4:${rawIp}`;
  const hx = expandIpv6To8Hextets(rawIp);
  return `v6_64:${hx.slice(0, 4).map((x) => x.toString(16).padStart(4, '0')).join(':')}`;
}

export function rateLimitSubnetKeyFixed(rawIp: string): string {
  const kind = net.isIP(rawIp);
  if (kind === 4) {
    const canonV4 = new URL(`http://${rawIp}/`).hostname;
    return `v4:${canonV4}`;
  }
  if (kind === 6) {
    const hx = expandIpv6To8Hextets(rawIp);
    const is_mapped_v4 =
      hx[0] === 0 && hx[1] === 0 && hx[2] === 0 && hx[3] === 0 && hx[4] === 0 && hx[5] === 0xffff;
    if (is_mapped_v4) {
      const a = (hx[6] >> 8) & 0xff;
      const b = hx[6] & 0xff;
      const c = (hx[7] >> 8) & 0xff;
      const d = hx[7] & 0xff;
      return `v4:${a}.${b}.${c}.${d}`;
    }
    const pfx64 = hx
      .slice(0, 4)
      .map((x) => x.toString(16).padStart(4, '0'))
      .join(':');
    return `v6_64:${pfx64}`;
  }
  throw new Error(`Invalid IP address: ${rawIp}`);
}

