pragma solidity ^0.8.24;

import "forge-std/Test.sol";

contract WrappedRebaseVault {
    uint256 public rebaseIndex = 1e18;
    uint256 public underlyingSharesHeld;
    uint256 public totalWrapped;
    bool public immutable roundDownSafe;
    mapping(address => uint256) public wrappedOf;

    error ZeroMinted();
    constructor(bool _fix) { roundDownSafe = _fix; }

    function rebase(uint256 newIndex) external {
        require(newIndex >= 1e15 && newIndex <= 1e24, "BAD_INDEX");
        rebaseIndex = newIndex;
    }

    function vaultElasticBalance() public view returns (uint256) {
        return (underlyingSharesHeld * rebaseIndex) / 1e18;
    }

    function wrap(uint256 elasticIn) external returns (uint256 minted) {
        uint256 baseUnits = (elasticIn * 1e18) / rebaseIndex;
