        underlyingSharesHeld += baseUnits;
        totalWrapped += minted;
        wrappedOf[msg.sender] += minted;
    }

    function unwrap(uint256 sharesIn) external returns (uint256 elasticOut) {
        wrappedOf[msg.sender] -= sharesIn;
        totalWrapped -= sharesIn;
        underlyingSharesHeld -= sharesIn;
        elasticOut = (sharesIn * rebaseIndex) / 1e18;
    }
