```cpp
#include <cassert>
#include <cctype>
#include <cstddef>
#include <cstdint>
#include <string>
#include <string_view>

bool validate_sexp_buggy_naive(std::string_view sv) {
    int bal = 0;
    for (char c : sv) {
        if (c == '(') ++bal;
        else if (c == ')') { if (--bal < 0) return false; }
    }
    return bal == 0 && !sv.empty();
}

bool validate_sexp_bounded(std::string_view sv, size_t max_depth) {
    if (sv.find('\0') != std::string_view::npos) return false;
    size_t depth = 0;
    bool in_quote = false;
    bool esc = false;
    size_t top_exprs = 0;
    bool in_bare_atom = false;

    for (unsigned char c : sv) {
        if (in_quote) {
            if (c < 0x20) return false;
            if (esc) { esc = false; }
            else if (c == '\\') { esc = true; }
            else if (c == '"') { in_quote = false; }
            continue;
        }
        if (std::isspace(c)) {
            in_bare_atom = false;
            continue;
        }
        if (c == '(') {
            in_bare_atom = false;
            if (depth == 0) ++top_exprs;
            if (++depth > max_depth) return false;
        } else if (c == ')') {
            in_bare_atom = false;
            if (depth == 0) return false;
            --depth;
        } else if (c == '"') {
            if (in_bare_atom) return false;
            if (depth == 0) ++top_exprs;
            in_quote = true;
        } else {
            if (c < 0x21 || c > 0x7E) return false;
            if (!in_bare_atom) {
                if (depth == 0) ++top_exprs;
                in_bare_atom = true;
            }
        }
    }
    return !in_quote && !esc && depth == 0 && top_exprs == 1;
}

void red_green_sexp_quote_paren_and_nul_proof() {
    assert(validate_sexp_buggy_naive("(print \")\")") == false);
    assert(validate_sexp_bounded("(print \")\")", 8) == true);

    constexpr char kNul[] = "(allow \"admin\0\")";
    assert(!validate_sexp_bounded(std::string_view(kNul, sizeof(kNul) - 1), 8));
    std::string bomb(20000, '(');
    bomb.append(20000, ')');
    assert(!validate_sexp_bounded(bomb, 16));
}

extern "C" int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size) {
    static const bool once = (red_green_sexp_quote_paren_and_nul_proof(), true);
    (void)once;
    std::string_view sv(reinterpret_cast<const char*>(data), size);
    bool d_low = validate_sexp_bounded(sv, 2);
    bool d_high = validate_sexp_bounded(sv, 10);
    if (d_low && !d_high) __builtin_trap();
    return 0;
}
