#include <algorithm>
#include <array>
#include <cassert>
#include <cstddef>
#include <cstdint>
#include <optional>
#include <vector>
#include <fuzzer/FuzzedDataProvider.h>

static std::array<uint8_t, 64> keystream_block(uint32_t counter32) {
    std::array<uint8_t, 64> blk{};
    uint64_t x = (static_cast<uint64_t>(counter32) + 1) * 0x9E3779B97F4A7C15ULL;
    for (size_t i = 0; i < 64; ++i) {
        x ^= x >> 12; x ^= x << 25; x ^= x >> 27;
        blk[i] = static_cast<uint8_t>((x * 0x2545F4914F6CDD1DULL) >> 56);
    }
    return blk;
}

std::vector<uint8_t> seek_buggy(uint32_t init_ctr, uint64_t byte_off, size_t len) {
    uint32_t ctr = init_ctr + static_cast<uint32_t>(byte_off / 64);
    std::vector<uint8_t> out;
    while (out.size() < len) {
        auto blk = keystream_block(ctr++);
        size_t take = std::min<size_t>(64, len - out.size());
        out.insert(out.end(), blk.begin(), blk.begin() + take);
    }
    return out;
}

std::optional<std::vector<uint8_t>> seek_chacha_fixed(
    uint32_t init_ctr,
    uint64_t byte_off,
    size_t len
) {
    if (len == 0) return std::vector<uint8_t>{};
    if (byte_off > UINT64_MAX - (len - 1)) return std::nullopt;
    uint64_t first_blk = static_cast<uint64_t>(init_ctr) + (byte_off / 64);
    uint64_t last_byte = byte_off + (len - 1);
    uint64_t last_blk = static_cast<uint64_t>(init_ctr) + (last_byte / 64);
    if (first_blk > UINT32_MAX || last_blk > UINT32_MAX) {
        return std::nullopt;
    }

    std::vector<uint8_t> out;
    out.reserve(len);
    size_t intra = static_cast<size_t>(byte_off % 64);
    uint32_t cur_ctr = static_cast<uint32_t>(first_blk);

    while (out.size() < len) {
        auto blk = keystream_block(cur_ctr);
        size_t avail = 64 - intra;
        size_t take = (len - out.size() < avail) ? (len - out.size()) : avail;
        out.insert(out.end(), blk.begin() + intra, blk.begin() + intra + take);
        intra = 0;
        if (out.size() < len) ++cur_ctr;
    }
    return out;
}

void red_green_counter_wrap_and_subblock_seek_proof() {
    assert(seek_buggy(UINT32_MAX, 64, 16) == seek_buggy(0, 0, 16));
    assert(!seek_chacha_fixed(UINT32_MAX, 64, 16).has_value());
    assert(!seek_chacha_fixed(UINT32_MAX, 63, 2).has_value());
    assert(seek_chacha_fixed(UINT32_MAX, 63, 1).has_value());

    auto full = seek_chacha_fixed(1, 0, 128).value();
    auto sliced = seek_chacha_fixed(1, 13, 80).value();
    assert(std::vector<uint8_t>(full.begin() + 13, full.begin() + 93) == sliced);
}

extern "C" int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size) {
    static const bool once = (red_green_counter_wrap_and_subblock_seek_proof(), true);
    (void)once;
    FuzzedDataProvider fdp(data, size);
    uint32_t init_ctr = fdp.ConsumeBool() ? UINT32_MAX - fdp.ConsumeIntegralInRange<uint32_t>(0, 4) : fdp.ConsumeIntegral<uint32_t>();
    uint64_t off = fdp.ConsumeIntegralInRange<uint64_t>(0, 300);
    size_t len = fdp.ConsumeIntegralInRange<size_t>(0, 200);

    auto got = seek_chacha_fixed(init_ctr, off, len);
    auto whole = seek_chacha_fixed(init_ctr, 0, static_cast<size_t>(off) + len);
    if (len == 0) {
        if (!got.has_value() || !got->empty()) __builtin_trap();
