use proptest::prelude::*;

pub fn encode_cbor_tstr(s: &str) -> Vec<u8> {
    let b = s.as_bytes();
    let n = b.len();
    let mut out = Vec::with_capacity(9 + n);
    if n < 24 {
        out.push(0x60 | (n as u8));
    } else if n <= 0xFF {
        out.push(0x78);
        out.push(n as u8);
    } else if n <= 0xFFFF {
        out.push(0x79);
        out.extend_from_slice(&(n as u16).to_be_bytes());
    } else {
        out.push(0x7A);
        out.extend_from_slice(&(n as u32).to_be_bytes());
    }
    out.extend_from_slice(b);
    out
}

pub fn sort_keys_buggy_lex(keys: &[String]) -> Vec<String> {
    let mut out = keys.to_vec();
    out.sort();
    out
}

pub fn sort_keys_rfc8949(keys: &[String]) -> Vec<String> {
    let mut pairs: Vec<(Vec<u8>, String)> = keys
        .iter()
        .map(|k| (encode_cbor_tstr(k), k.clone()))
        .collect();
    pairs.sort_by(|a, b| a.0.cmp(&b.0));
    pairs.into_iter().map(|(_, k)| k).collect()
}

