            map in prop::collection::hash_map(".{0,40}", any::<u8>(), 0..16)
        ) {
            let keys: Vec<String> = map.keys().cloned().collect();
            let cbor_sorted = sort_keys_rfc8949(&keys);

            let mut length_first_oracle = keys;
            length_first_oracle.sort_by(|a, b| (a.len(), a.as_bytes()).cmp(&(b.len(), b.as_bytes())));
