use proptest::prelude::*;

pub fn truncate_buggy(s: &str, max_bytes: usize) -> String {
    if s.len() <= max_bytes {
        return s.to_owned();
    }
    format!("{}...", &s[..max_bytes - 3])
}

fn floor_boundary(s: &str, idx: usize) -> usize {
    let mut i = idx.min(s.len());
    while i > 0 && !s.is_char_boundary(i) {
        i -= 1;
    }
    i
}

pub fn truncate_ellipsis_utf8(s: &str, max_bytes: usize) -> String {
    if s.len() <= max_bytes {
        return s.to_owned();
    }
    if max_bytes < 3 {
        return ".".repeat(max_bytes);
    }
    let budget = max_bytes - 3;
    let cut = floor_boundary(s, budget);
    let mut out = String::with_capacity(cut + 3);
    out.push_str(&s[..cut]);
    out.push_str("...");
    out
