        .replace('"', '\\"')
        .replace("\n", "\\n")
        .replace("\r", "\\r")
    )
    return f'{key}="{escaped}"'

def parse_dotenv_line_fixed(raw_line: str) -> tuple[str, str] | None:
    if "\x00" in raw_line:
        raise ValueError("Embedded NUL byte forbidden in .env")
    s = raw_line.strip()
    if not s or s.startswith("#"):
        return None
    if s.startswith("export ") or s.startswith("export\t"):
        s = s[6:].lstrip()
    k, eq, rhs = s.partition("=")
    if not eq:
        raise ValueError("Missing '=' in .env assignment")
    key = k.strip()
    if not ENV_KEY_RE.fullmatch(key):
        raise ValueError(f"Invalid env key: {key!r}")

    rhs = rhs.lstrip(" \t")
    if not rhs:
        return key, ""
    if rhs[0] == '"':
        out = []
        i = 1
        closed = False
        while i < len(rhs):
            ch = rhs[i]
            if ch == '"':
                closed = True
                i += 1
                break
            if ch == "\\":
                if i + 1 >= len(rhs):
                    raise ValueError("Dangling escape")
                nxt = rhs[i + 1]
                mapping = {'"': '"', "\\": "\\", "n": "\n", "r": "\r", "t": "\t"}
                if nxt not in mapping:
                    raise ValueError(f"Unsupported escape \\{nxt}")
                out.append(mapping[nxt])
                i += 2
            else:
                out.append(ch)
                i += 1
        if not closed:
            raise ValueError("Unterminated double-quoted .env value")
        tail = rhs[i:].strip()
        if tail and not tail.startswith("#"):
            raise ValueError(f"Unexpected trailing tokens after closing quote: {tail!r}")
        return key, "".join(out)

    val_end = len(rhs)
    for idx, ch in enumerate(rhs):
        if ch == "#" and idx > 0 and rhs[idx - 1] in (" ", "\t"):
            val_end = idx
            break
    return key, rhs[:val_end].rstrip(" \t")

