    line = 'export DB_PASS="pa#ss=word" # prod db'
    assert parse_dotenv_buggy(line) != ("DB_PASS", "pa#ss=word")

    assert parse_dotenv_line_fixed(line) == ("DB_PASS", "pa#ss=word")
    assert parse_dotenv_line_fixed("PORT=8080 # http port") == ("PORT", "8080")
    assert parse_dotenv_line_fixed("TAG=release#hash") == ("TAG", "release#hash")
    with pytest.raises(ValueError):
        parse_dotenv_line_fixed('BAD="val\x00"')

secret_strat = st.text(
    alphabet=["#", "=", '"', "'", "\\", " ", "\n", "\r", "a", "9"],
    min_size=0,
    max_size=20,
