import fc from 'fast-check';
import { describe, it, expect } from 'vitest';

export class BuggyCasStore {
  private data = new Map<string, { val: string; ver: number }>();

  put(key: string, val: string, expectedVer?: number): number {
    const cur = this.data.get(key);
    if (expectedVer !== undefined && expectedVer !== 0 && cur?.ver !== expectedVer) {
      throw new Error('CAS mismatch');
    }
    const nextVer = (cur?.ver ?? 0) + 1;
    this.data.set(key, { val, ver: nextVer });
    return nextVer;
  }

  delete(key: string): void {
    this.data.delete(key);
  }
}

export class SafeCasStore {
  private rev = 0;
  private data = new Map<string, { val: string; ver: number }>();

  putCas(key: string, val: string, expectedVer: number): number {
    const cur = this.data.get(key);
    const actualVer = cur ? cur.ver : 0;
    if (actualVer !== expectedVer) {
      throw new Error(`CAS conflict: expected ${expectedVer}, got ${actualVer}`);
    }
    this.rev += 1;
    this.data.set(key, { val, ver: this.rev });
    return this.rev;
  }

  deleteCas(key: string, expectedVer: number): void {
    const cur = this.data.get(key);
    const actualVer = cur ? cur.ver : 0;
    if (actualVer === 0 || actualVer !== expectedVer) {
      throw new Error('CAS conflict on delete');
    }
    this.rev += 1;
    this.data.delete(key);
  }

  get(key: string): { val: string; ver: number } | undefined {
    return this.data.get(key);
  }
}

