    const buggy = new BuggyCasStore();
    const ver_initial = buggy.put('cfg', 'initial', 0);
    buggy.put('cfg', 'accidental_overwrite', 0);
    buggy.delete('cfg');
    buggy.put('cfg', 'recreated_fresh', 0);
    expect(() => buggy.put('cfg', 'stale_worker_clobber', ver_initial)).not.toThrow();

    const safe = new SafeCasStore();
    const sv_first = safe.putCas('cfg', 'initial', 0);
    expect(() => safe.putCas('cfg', 'second_create', 0)).toThrow(/CAS conflict/);
    safe.deleteCas('cfg', sv_first);
    const svRecreate = safe.putCas('cfg', 'recreated_fresh', 0);
    expect(svRecreate).toBeGreaterThan(sv_first);
    expect(() => safe.putCas('cfg', 'stale_worker_clobber', sv_first)).toThrow(/CAS conflict/);
    expect(safe.get('cfg')?.val).toBe('recreated_fresh');
