library WordBitRange {
    error OutOfWordBounds();

    function setRangeBuggy(uint256 word, uint8 offset, uint16 width) internal pure returns (uint256) {
        if (uint256(offset) + uint256(width) > 256) revert OutOfWordBounds();
        uint256 mask = ((uint256(1) << width) - 1) << offset;
