contract NftCollateralLocker {
    struct Loan {
        address borrower;
        address lender;
        uint64 dueTime;
        bool active;
    }

    bool public immutable strictDefaultBoundary;
    uint256 public activeLoans;
    uint256 public escrowedNfts;
