    function lockNft(uint256 tokenId, address lender, uint64 duration) external {
        require(!loans[tokenId].active && duration > 0, "BAD_LOAN");
        loans[tokenId] = Loan({
            borrower: msg.sender,
            lender: lender,
            dueTime: uint64(block.timestamp) + duration,
            active: true
