use std::collections::BTreeMap;
use proptest::prelude::*;

#[derive(Debug, PartialEq, Eq)]
pub enum IniErr {
    DanglingContinuation,
    MalformedLine,
    UnterminatedQuote,
    DuplicateKey(String),
}

pub fn parse_ini_buggy(line: &str) -> Option<(&str, &str)> {
    let without_comment = line.split(['#', ';']).next()?;
    let (k, v) = without_comment.split_once('=')?;
