}

pub fn parse_ini_kv_strict(text: &str) -> Result<BTreeMap<String, String>, IniErr> {
    let mut logical_lines: Vec<String> = Vec::new();
    let mut acc = String::new();
    let mut continuing = false;

    for raw in text.lines() {
        let trimmed_start = raw.trim_start();
        if !continuing && (trimmed_start.is_empty() || trimmed_start.starts_with('#') || trimmed_start.starts_with(';')) {
            continue;
        }
        let trailing_bs = raw.bytes().rev().take_while(|&b| b == b'\\').count();
        if trailing_bs % 2 == 1 {
            acc.push_str(&raw[..raw.len() - 1]);
            continuing = true;
        } else {
            acc.push_str(raw);
            logical_lines.push(std::mem::take(&mut acc));
            continuing = false;
        }
    }
    if continuing {
        return Err(IniErr::DanglingContinuation);
    }

    let mut map = BTreeMap::new();
    for line in logical_lines {
        let (raw_k, raw_rhs) = line.split_once('=').ok_or(IniErr::MalformedLine)?;
        let key = raw_k.trim();
        if key.is_empty() || !key.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'_') {
            return Err(IniErr::MalformedLine);
        }
        let rhs = raw_rhs.trim_start();
        let val = if let Some(after_open) = rhs.strip_prefix('"') {
            let mut out = String::new();
            let mut chars = after_open.chars();
            let mut closed = false;
            while let Some(c) = chars.next() {
                if c == '"' {
                    closed = true;
                    break;
                } else if c == '\\' {
                    let nxt = chars.next().ok_or(IniErr::UnterminatedQuote)?;
                    out.push(nxt);
                } else {
                    out.push(c);
                }
            }
            if !closed {
                return Err(IniErr::UnterminatedQuote);
            }
            let rest = chars.as_str().trim();
            if !rest.is_empty() && !rest.starts_with('#') && !rest.starts_with(';') {
                return Err(IniErr::MalformedLine);
            }
            out
        } else {
            let cut = rhs.find(['#', ';']).unwrap_or(rhs.len());
            rhs[..cut].trim_end().to_owned()
        };
        if map.insert(key.to_owned(), val).is_some() {
            return Err(IniErr::DuplicateKey(key.to_owned()));
        }
    }
    Ok(map)
}

