import { describe, it, expect } from 'vitest';

const DIRECTIVE_RE = /^[a-z0-9-]+$/;
const FORBIDDEN_SOURCE_CHAR_RE = /[;,\s\x00-\x1f\x7f]/;

export function mergeCspBuggy(base: string[], extra: string[], dir = 'script-src'): string {
  return `${dir} ${[...base, ...extra].join(' ')}`;
}

export function mergeCspUnion(
  baseSources: readonly string[],
  extraSources: readonly string[],
  directive = 'script-src'
): string {
  if (!DIRECTIVE_RE.test(directive)) {
    throw new Error(`Invalid CSP directive name: ${directive}`);
  }
  const active = new Set<string>();
  for (const raw of [...baseSources, ...extraSources]) {
    const tok = raw.trim();
    if (!tok) continue;
    if (FORBIDDEN_SOURCE_CHAR_RE.test(tok)) {
      throw new Error(`CSP injection character in source expression: ${tok}`);
    }
