      continue;
    }
    active.add(tok);
  }
  if (active.size === 0) {
    return `${directive} 'none'`;
  }
  const ordered = Array.from(active).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  return `${directive} ${ordered.join(' ')}`;
}

describe('mergeCspUnion W3C CSP3 none-singleton & directive-injection defense', () => {
  it('red-green proof: drops singleton none on union and blocks semicolon/comma/CRLF injection', () => {
