    expect(mergeCspUnion(["'none'"], ['https://cdn.example'])).toBe('script-src https://cdn.example');
    expect(mergeCspUnion(["'none'"], [])).toBe("script-src 'none'");
    expect(mergeCspUnion([], [])).toBe("script-src 'none'");
    expect(() => mergeCspUnion(["'self'"], ["https://a.example; script-src 'unsafe-eval'"])).toThrow(/injection/);
    expect(() => mergeCspUnion(["'self'"], ['https://a.example, default-src *'])).toThrow(/injection/);
