export class SafeLog2Histogram {
  readonly counts: number[];
  private total = 0;

  constructor(readonly maxBucket: number) {
    if (!Number.isInteger(maxBucket) || maxBucket < 1 || maxBucket > 52) {
      throw new RangeError('maxBucket must be in 1..52');
    }
    this.counts = new Array(maxBucket + 1).fill(0);
  }

  bucketFor(v: number): number {
    if (!Number.isFinite(v) || v < 0) {
      throw new RangeError(`Invalid negative or non-finite latency: ${v}`);
    }
    if (v < 1) {
      return 0;
    }
    let k = Math.floor(Math.log2(v));
    if (k <= 52 && v < 2 ** k) {
      k -= 1;
    }
    if (k + 1 <= 52 && v >= 2 ** (k + 1)) {
      k += 1;
    }
    return Math.min(this.maxBucket, k + 1);
  }

  record(v: number): number {
    const b = this.bucketFor(v);
    this.counts[b] += 1;
    this.total += 1;
    return b;
  }

  totalCount(): number {
    return this.total;
  }
}

