use proptest::prelude::*;

#[derive(Debug, PartialEq, Eq)]
pub enum TarHeaderErr {
    EmptyField,
    BinaryExtensionUnsupported,
    InvalidOctalByte,
    TrailingGarbageAfterTerminator,
    NumericOverflow,
}

pub fn parse_tar_octal_buggy(field: &[u8]) -> Option<u64> {
    let s = std::str::from_utf8(field).ok()?;
    let trimmed = s.trim_matches(|c| c == ' ' || c == '\0');
    u64::from_str_radix(trimmed, 8).ok()
}

pub fn parse_tar_octal_u64(field: &[u8]) -> Result<u64, TarHeaderErr> {
    if field.is_empty() {
        return Err(TarHeaderErr::EmptyField);
    }
    if (field[0] & 0x80) != 0 {
        return Err(TarHeaderErr::BinaryExtensionUnsupported);
    }
    let mut idx = 0;
    while idx < field.len() && field[idx] == b' ' {
        idx += 1;
    }
    let digits_start = idx;
    let mut acc: u64 = 0;
    while idx < field.len() && field[idx] != 0 && field[idx] != b' ' {
        let b = field[idx];
        if !(b'0'..=b'7').contains(&b) {
            return Err(TarHeaderErr::InvalidOctalByte);
        }
        acc = acc
            .checked_mul(8)
            .and_then(|v| v.checked_add(u64::from(b - b'0')))
            .ok_or(TarHeaderErr::NumericOverflow)?;
        idx += 1;
    }
    if idx == digits_start {
        return Err(TarHeaderErr::EmptyField);
    }
    while idx < field.len() {
        if field[idx] != 0 && field[idx] != b' ' {
            return Err(TarHeaderErr::TrailingGarbageAfterTerminator);
        }
        idx += 1;
    }
    Ok(acc)
}

pub fn encode_tar_octal_12(val: u64) -> Option<[u8; 12]> {
    if val > 0o777_7777_7777 {
        return None;
    }
    let mut out = [b'0'; 12];
    out[11] = 0;
    let mut rem = val;
    for slot in (0..11).rev() {
        out[slot] = b'0' + ((rem & 7) as u8);
        rem >>= 3;
    }
    Some(out)
}

