forgetting `.remove(&res_id)` b3f0r3 refunding 0n `abort` turns every cancelled request into 4 free-credit mint, 4nd computing `reserved - actual_used` in unsigned `u64` panics whenever an LLM stream overshoots its prompt estimate by 1 token! consume 7h3 reservation atomically via `BTreeMap::remove`, handle `actual_used > reserved` safely against `available` (or cap/error cleanly without losing state), 4nd verify exact conservation `available + in_flight + committed == capacity` w17h `proptest`:
```rust
use std::collections::BTreeMap;
use proptest::prelude::*;

#[derive(Debug, PartialEq, Eq)]
pub enum QuotaErr {
    UnknownOrFinalizedReservation,
    InsufficientOverageBudget,
}

pub struct BuggyLedger {
    pub available: u64,
    pub holds: BTreeMap<u64, u64>,
}

impl BuggyLedger {
    pub fn abort_buggy(&mut self, id: u64) {
        if let Some(&amt) = self.holds.get(&id) {
            self.available += amt; // Bug: forgot remove(), double-abort inflates available!
        }
    }
}

#[derive(Debug)]
pub struct QuotaLedger {
    capacity: u64,
    available: u64,
    in_flight: u64,
    committed: u64,
    next_id: u64,
    holds: BTreeMap<u64, u64>,
}

impl QuotaLedger {
    pub fn new(capacity: u64) -> Self {
        Self {
            capacity,
            available: capacity,
            in_flight: 0,
            committed: 0,
            next_id: 1,
            holds: BTreeMap::new(),
        }
    }

    pub fn reserve(&mut self, amount: u64) -> Option<u64> {
        if amount == 0 || amount > self.available {
            return None;
        }
        let id = self.next_id;
        self.next_id += 1;
        self.available -= amount;
        self.in_flight += amount;
        self.holds.insert(id, amount);
        Some(id)
    }

    pub fn abort(&mut self, id: u64) -> Result<(), QuotaErr> {
        let reserved = self.holds.remove(&id).ok_or(QuotaErr::UnknownOrFinalizedReservation)?;
        self.in_flight -= reserved;
        self.available += reserved;
        Ok(())
    }

    pub fn commit(&mut self, id: u64, actual_used: u64) -> Result<(), QuotaErr> {
        let reserved = *self.holds.get(&id).ok_or(QuotaErr::UnknownOrFinalizedReservation)?;
        if actual_used <= reserved {
            self.holds.remove(&id);
            let refund = reserved - actual_used;
            self.in_flight -= reserved;
            self.committed += actual_used;
            self.available += refund;
            Ok(())
        } else {
            let extra = actual_used - reserved;
            if extra > self.available {
                return Err(QuotaErr::InsufficientOverageBudget);
            }
            self.holds.remove(&id);
            self.in_flight -= reserved;
            self.available -= extra;
            self.committed += actual_used;
            Ok(())
        }
    }

    pub fn check_invariants(&self) -> bool {
        let hold_sum: u64 = self.holds.values().copied().sum();
        hold_sum == self.in_flight
            && self.available
                .checked_add(self.in_flight)
                .and_then(|x| x.checked_add(self.committed))
                == Some(self.capacity)
    }
}

#[derive(Debug, Clone)]
enum Op {
    Reserve(u64),
    Commit(usize, u64),
    Abort(usize),
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn red_green_double_abort_and_overage() {
        let mut buggy = BuggyLedger { available: 50, holds: BTreeMap::from([(1, 50)]) };
        buggy.abort_buggy(1);
        buggy.abort_buggy(1);
        assert_eq!(buggy.available, 150); // inflated above 100!

        let mut fixed = QuotaLedger::new(100);
        let id = fixed.reserve(50).unwrap();
        assert_eq!(fixed.abort(id), Ok(()));
        assert_eq!(fixed.abort(id), Err(QuotaErr::UnknownOrFinalizedReservation));
        let id2 = fixed.reserve(40).unwrap();
        assert_eq!(fixed.commit(id2, 55), Ok(()));
        assert!(fixed.check_invariants());
    }

    proptest! {
        #[test]
        fn conservation_holds_under_arbitrary_ops(
            cap in 1_u64..10_000_u64,
            ops in prop::collection::vec(
                prop_oneof![
                    (0_u64..500_u64).prop_map(Op::Reserve),
                    (0_usize..16_usize, 0_u64..500_u64).prop_map(|(i, u)| Op::Commit(i, u)),
                    (0_usize..16_usize).prop_map(Op::Abort),
                ],
                1..64
            )
        ) {
            let mut ledger = QuotaLedger::new(cap);
            let mut seen_ids = Vec::new();
            for op in ops {
                match op {
                    Op::Reserve(amt) => {
                        if let Some(id) = ledger.reserve(amt) {
                            seen_ids.push(id);
                        }
                    }
                    Op::Commit(idx, used) if !seen_ids.is_empty() => {
                        let id = seen_ids[idx % seen_ids.len()];
                        let _ = ledger.commit(id, used);
                    }
                    Op::Abort(idx) if !seen_ids.is_empty() => {
                        let id = seen_ids[idx % seen_ids.len()];
                        let _ = ledger.abort(id);
                    }
                    _ => {}
                }
                prop_assert!(ledger.check_invariants());
            }
        }
    }
}
