import pytest
from hypothesis import given, strategies as st

def escape_sql_like_buggy(literal: str, escape_char: str = "\\") -> str:
    s = literal.replace("%", escape_char + "%").replace("_", escape_char + "_")
    return s.replace(escape_char, escape_char + escape_char)  # Wrong order!

def escape_sql_like(literal: str, escape_char: str = "\\") -> str:
    if len(escape_char) != 1 or escape_char in ("%", "_", "\x00"):
        raise ValueError("escape_char must be a single non-wildcard non-NUL character")
    if "\x00" in literal:
        raise ValueError("NUL byte forbidden in SQL LIKE literal")
    specials = {escape_char, "%", "_"}
    return "".join((escape_char + ch) if ch in specials else ch for ch in literal)

def sql_like_match(text: str, pattern: str, escape_char: str = "\\") -> bool:
    tokens: list[tuple[str, str]] = []
    i = 0
    while i < len(pattern):
        ch = pattern[i]
        if ch == escape_char:
            if i + 1 >= len(pattern):
                raise ValueError("dangling SQL LIKE escape char")
            tokens.append(("LIT", pattern[i + 1]))
            i += 2
        elif ch == "%":
            tokens.append(("ANY", ""))
            i += 1
        elif ch == "_":
            tokens.append(("ONE", ""))
            i += 1
        else:
            tokens.append(("LIT", ch))
            i += 1

    memo: dict[tuple[int, int], bool] = {}
    def dp(ti: int, pi: int) -> bool:
        state = (ti, pi)
        if state in memo:
            return memo[state]
        if pi == len(tokens):
            res = (ti == len(text))
        else:
            kind, val = tokens[pi]
            if kind == "ANY":
                res = dp(ti, pi + 1) or (ti < len(text) and dp(ti + 1, pi))
            elif kind == "ONE":
                res = (ti < len(text)) and dp(ti + 1, pi + 1)
            else:
                res = (ti < len(text) and text[ti] == val) and dp(ti + 1, pi + 1)
        memo[state] = res
        return res

    return dp(0, 0)

def test_red_green_double_escape_wildcard_reintroduction():
    bad_pat = escape_sql_like_buggy("admin%root")
    # Buggy 'admin\\%root' matches 'admin\XYZroot' because '%' was unescaped!
    assert sql_like_match("admin\\XYZroot", bad_pat) is True
    good_pat = escape_sql_like("admin%root")
    assert sql_like_match("admin\\XYZroot", good_pat) is False
    assert sql_like_match("admin%root", good_pat) is True
    with pytest.raises(ValueError):
        escape_sql_like("abc", escape_char="%")

WILD_ALPHA = st.text(alphabet=["%", "_", "\\", "!", "a", "b", "0"], min_size=0, max_size=25)

@given(WILD_ALPHA, WILD_ALPHA, st.sampled_from(["\\", "!"]))
def test_escaped_literal_matches_iff_equal(lit: str, candidate: str, esc: str):
    pat = escape_sql_like(lit, escape_char=esc)
    assert sql_like_match(lit, pat, escape_char=esc) is True
    assert sql_like_match(candidate, pat, escape_char=esc) is (candidate == lit)
