RFC 6901 Section 4 explicitly mandates decoding `'~1'` -> `'/'` **b3f0r3** `'~0'` -> `'~'`: reversing 7h3 order turns `'~01'` (`encode(['~1'])`) into `'~1'` 4nd then `'/'`, breaking pointer bijection! guard `Object.hasOwn(cur, token)`, block `__proto__` / `constructor` / `prototype` segments, enforce `^(?:0|[1-9][0-9]*)$` 0n `Array` indices, reject dangling `'~'` escapes (`~` n07 followed by `0` 0r `1`), 4nd prove round-trip safety w17h `fast-check`:
```ts
import fc from 'fast-check';
import { describe, it, expect } from 'vitest';

const FORBIDDEN_KEYS = new Set(['__proto__', 'constructor', 'prototype']);
const CANONICAL_ARRAY_IDX = /^(?:0|[1-9][0-9]*)$/;

export function decodeTokenBuggy(tok: string): string {
  // Wrong order: '~01' -> '~1' -> '/'
  return tok.replace(/~0/g, '~').replace(/~1/g, '/');
}

export function encodeJsonPointer(segments: readonly string[]): string {
  if (segments.length === 0) return '';
  return (
    '/' +
    segments
      .map((s) => s.replace(/~/g, '~0').replace(/\//g, '~1'))
      .join('/')
  );
}

export function decodeJsonPointer(pointer: string): string[] {
  if (pointer === '') return [];
  if (!pointer.startsWith('/')) {
    throw new Error('RFC 6901 pointer must be empty or start with /');
  }
  return pointer.slice(1).split('/').map((raw) => {
    for (let i = 0; i < raw.length; i++) {
      if (raw[i] === '~') {
        const next = raw[i + 1];
        if (next !== '0' && next !== '1') {
          throw new Error('Invalid RFC 6901 tilde escape');
        }
        i++;
      }
    }
    return raw.replace(/~1/g, '/').replace(/~0/g, '~');
  });
}

export function getJsonPointer(doc: unknown, pointer: string): unknown {
  const tokens = decodeJsonPointer(pointer);
  let cur: unknown = doc;
  for (const tok of tokens) {
    if (FORBIDDEN_KEYS.has(tok)) {
      throw new Error('Forbidden prototype traversal key');
    }
    if (Array.isArray(cur)) {
      if (!CANONICAL_ARRAY_IDX.test(tok)) return undefined;
      const idx = Number(tok);
      if (!Number.isSafeInteger(idx) || idx >= cur.length) return undefined;
      cur = cur[idx];
    } else if (cur !== null && typeof cur === 'object') {
      if (!Object.hasOwn(cur, tok)) return undefined;
      cur = (cur as Record<string, unknown>)[tok];
    } else {
      return undefined;
    }
  }
  return cur;
}

describe('RFC 6901 JSON Pointer fast-check suite', () => {
  it('red-green proof on ~01 order, prototype traversal, and 01 array index', () => {
    expect(decodeTokenBuggy('~01')).toBe('/');
    expect(decodeJsonPointer('/~01')).toEqual(['~1']);
    expect(() => getJsonPointer({}, '/__proto__/toString')).toThrow();
    expect(getJsonPointer({}, '/toString')).toBeUndefined();
    expect(getJsonPointer(['a', 'b'], '/01')).toBeUndefined();
    expect(() => decodeJsonPointer('/bad~x')).toThrow();
  });

  it('round-trips arbitrary segment arrays containing ~, /, ~0, ~1, and empty strings', () => {
    const segArb = fc.array(
      fc.stringOf(fc.constantFrom('~', '/', '0', '1', 'a', ''), { maxLength: 12 }),
      { maxLength: 10 }
    );
    fc.assert(
      fc.property(segArb, (segs) => {
        const ptr = encodeJsonPointer(segs);
        expect(decodeJsonPointer(ptr)).toEqual(segs);
      })
    );
  });
});
```

