import fc from 'fast-check';
import { describe, it, expect } from 'vitest';

export function isSafeReturnUrlBuggy(rawTarget: string, allowedDomain: string): boolean {
  try {
    const u = new URL(rawTarget, 'https://' + allowedDomain);
    return u.hostname.endsWith(allowedDomain);
  } catch {
    return false;
  }
}

export function isSafeReturnUrl(rawTarget: string, allowedDomain: string): boolean {
  const dom = allowedDomain.trim().toLowerCase().replace(/^\.+|\.+$/g, '');
  if (!dom || dom.includes('/') || dom.includes('@') || dom.includes(':')) {
    return false;
  }
  if (/^[\s\x00-\x1f]|[\x00-\x1f\x7f\\]/.test(rawTarget)) {
    return false;
  }
  let parsed: URL;
  try {
    parsed = new URL(rawTarget); // No base URL: rejects '//evil.com' and relative ambiguity
  } catch {
    return false;
  }
  if (parsed.protocol !== 'https:') return false;
  if (parsed.username !== '' || parsed.password !== '') return false;
  if (parsed.port !== '' && parsed.port !== '443') return false;

  const host = parsed.hostname.toLowerCase();
  if (host.endsWith('.')) return false;
  return host === dom || host.endsWith('.' + dom);
}

describe('OAuth return URL allowlist fast-check suite', () => {
  it('red-green proof on suffix spoofing, backslash userinfo, and scheme downgrade', () => {
    expect(isSafeReturnUrlBuggy('https://evil-acme.com/cb', 'acme.com')).toBe(true);
    expect(isSafeReturnUrl('https://evil-acme.com/cb', 'acme.com')).toBe(false);
    expect(isSafeReturnUrl('//evil.com/cb', 'acme.com')).toBe(false);
    expect(isSafeReturnUrl('https://acme.com\\@evil.com/cb', 'acme.com')).toBe(false);
    expect(isSafeReturnUrl('https://phish@acme.com/cb', 'acme.com')).toBe(false);
    expect(isSafeReturnUrl('http://app.acme.com/cb', 'acme.com')).toBe(false);
    expect(isSafeReturnUrl('https://app.acme.com/oauth/cb?state=xyz', 'acme.com')).toBe(true);
  });

  it('accepts valid subdomains and always rejects attacker-suffixed or non-HTTPS hosts', () => {
    const labelArb = fc.stringMatching(/^[a-z0-9]{1,10}$/);
    fc.assert(
      fc.property(labelArb, labelArb, (sub, pathSeg) => {
        expect(isSafeReturnUrl(`https://${sub}.acme.com/${pathSeg}`, 'acme.com')).toBe(true);
        expect(isSafeReturnUrl(`https://${sub}-acme.com/${pathSeg}`, 'acme.com')).toBe(false);
        expect(isSafeReturnUrl(`http://${sub}.acme.com/${pathSeg}`, 'acme.com')).toBe(false);
      })
    );
  });
});
