// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "forge-std/Test.sol";

contract ExitFeeVault {
    uint256 public constant BPS = 10_000;
    uint256 public immutable feeBps;
    bool public immutable roundInVaultFavor;

    uint256 public totalAssets;
    uint256 public totalShares;
    mapping(address => uint256) public sharesOf;
    mapping(address => uint256) public walletAssets;

    constructor(uint256 _feeBps, bool _fix) {
        require(_feeBps < 1000, "fee too high");
        feeBps = _feeBps;
        roundInVaultFavor = _fix;
    }

    function fundWallet(address u, uint256 amt) external {
        walletAssets[u] += amt;
    }

    function _mulDivDown(uint256 x, uint256 y, uint256 d) internal pure returns (uint256) {
        return (x * y) / d;
    }

    function _mulDivUp(uint256 x, uint256 y, uint256 d) internal pure returns (uint256) {
        uint256 prod = x * y;
        return prod == 0 ? 0 : ((prod - 1) / d) + 1;
    }

    function previewDeposit(uint256 assets) public view returns (uint256) {
        return _mulDivDown(assets, totalShares + 1, totalAssets + 1);
    }

    function previewMint(uint256 shares) public view returns (uint256) {
        if (!roundInVaultFavor) {
            return _mulDivDown(shares, totalAssets + 1, totalShares + 1); // Bug!
        }
        return _mulDivUp(shares, totalAssets + 1, totalShares + 1);
    }

    function previewRedeem(uint256 shares) public view returns (uint256) {
        uint256 gross = _mulDivDown(shares, totalAssets + 1, totalShares + 1);
        uint256 fee = roundInVaultFavor
            ? _mulDivUp(gross, feeBps, BPS)
            : _mulDivDown(gross, feeBps, BPS);
        return gross - fee;
    }

    function previewWithdraw(uint256 netAssets) public view returns (uint256) {
        if (!roundInVaultFavor) {
            uint256 grossBug = _mulDivDown(netAssets, BPS, BPS - feeBps);
            return _mulDivDown(grossBug, totalShares + 1, totalAssets + 1); // Bug!
        }
        uint256 grossReq = _mulDivUp(netAssets, BPS, BPS - feeBps);
        return _mulDivUp(grossReq, totalShares + 1, totalAssets + 1);
    }

    function deposit(uint256 assets) external returns (uint256 shares) {
        shares = previewDeposit(assets);
        walletAssets[msg.sender] -= assets;
        totalAssets += assets;
        totalShares += shares;
        sharesOf[msg.sender] += shares;
    }

    function mint(uint256 shares) external returns (uint256 assets) {
        assets = previewMint(shares);
        walletAssets[msg.sender] -= assets;
        totalAssets += assets;
        totalShares += shares;
        sharesOf[msg.sender] += shares;
    }

    function redeem(uint256 shares) external returns (uint256 netAssets) {
        netAssets = previewRedeem(shares);
        sharesOf[msg.sender] -= shares;
        totalShares -= shares;
        totalAssets -= netAssets;
        walletAssets[msg.sender] += netAssets;
    }

    function withdraw(uint256 netAssets) external returns (uint256 shares) {
        shares = previewWithdraw(netAssets);
        sharesOf[msg.sender] -= shares;
        totalShares -= shares;
        totalAssets -= netAssets;
        walletAssets[msg.sender] += netAssets;
    }
}

