        vm.expectRevert(UnorderedNonces.NonceAlreadyUsed.selector);
        target.useNonceFixed(owner, nonce);

        uint256 neighbor = nonce ^ 1;
        target.useNonceFixed(owner, neighbor);

        count = uint16(bound(count, 0, 256));
        uint256 m = target.maskLowBitsFixed(count);
        if (count == 0) assertEq(m, 0);
        else if (count == 256) assertEq(m, type(uint256).max);
        else {
            assertEq((m >> (count - 1)) & 1, 1);
            assertEq(m >> count, 0);
        }
    }
}
